    fn objective_owner_identity_for_session(
        bridge_session_id: &SessionId,
    ) -> meerkat_mob::AgentIdentity {
        meerkat_mob::AgentIdentity::objective_lead_for_session(bridge_session_id)
    }

    pub async fn objective_principal_for_bridge_session(
        &self,
        bridge_session_id: &SessionId,
    ) -> Result<Option<(MobId, meerkat_mob::AgentIdentity)>, MobError> {
        self.ensure_restored().await?;
        let mob_ids = self.loaded_view().await.into_keys().collect::<Vec<_>>();
        // A real roster binding is authoritative when the same session also
        // owns an implicit child mob: conclusions belong in the lead's mob.
        for mob_id in &mob_ids {
            let roster = self.handle_for(mob_id).await?.roster().await;
            if let Some(entry) = roster.find_by_bridge_session_id(bridge_session_id) {
                return Ok(Some((mob_id.clone(), entry.agent_identity.clone())));
            }
        }
        for mob_id in mob_ids {
            let handle = self.handle_for(&mob_id).await?;
            if handle.owns_bridge_session(bridge_session_id).await? {
                return Ok(Some((
                    mob_id,
                    Self::objective_owner_identity_for_session(bridge_session_id),
                )));
            }
        }
        Ok(None)
    }

    pub async fn objective_principal_for_mob_owner_session(
        &self,
        mob_id: &MobId,
        bridge_session_id: &SessionId,
    ) -> Result<meerkat_mob::AgentIdentity, MobError> {
        let handle = self.handle_for(mob_id).await?;
        Self::objective_principal_on(&handle, bridge_session_id).await
    }

    /// [`Self::objective_principal_for_mob_owner_session`] in the mob
    /// `handle` serves, which the caller already resolved.
    pub(crate) async fn objective_principal_on(
        handle: &MobHandle,
        bridge_session_id: &SessionId,
    ) -> Result<meerkat_mob::AgentIdentity, MobError> {
        let roster = handle.roster().await;
        if let Some(entry) = roster.find_by_bridge_session_id(bridge_session_id) {
            return Ok(entry.agent_identity.clone());
        }
        drop(roster);
        if handle.owns_bridge_session(bridge_session_id).await? {
            return Ok(Self::objective_owner_identity_for_session(
                bridge_session_id,
            ));
        }
        Err(MobError::Internal(format!(
            "bridge session {bridge_session_id} is not an objective lead for mob {}",
            handle.mob_id()
        )))
    }

    #[doc(hidden)]
    pub async fn member_for_bridge_session(
        &self,
        bridge_session_id: &SessionId,
    ) -> Result<Option<(MobId, meerkat_mob::AgentIdentity)>, MobError> {
        Ok(self
            .member_handle_for_bridge_session(bridge_session_id)
            .await?
            .map(|(mob_id, _, identity)| (mob_id, identity)))
    }

    /// The member seated on `bridge_session_id` in a mob this state manages,
    /// with that mob's handle. A mob removed while the read runs (a
    /// concurrent destroy) is skipped, not an error.
    pub(crate) async fn member_handle_for_bridge_session(
        &self,
        bridge_session_id: &SessionId,
    ) -> Result<Option<(MobId, MobHandle, meerkat_mob::AgentIdentity)>, MobError> {
        self.ensure_restored().await?;
        let mob_ids = self.loaded_view().await.into_keys().collect::<Vec<_>>();
        for mob_id in mob_ids {
            let handle = match self.handle_for(&mob_id).await {
                Ok(handle) => handle,
                Err(MobError::MobNotFound(_)) => continue,
                Err(error) => return Err(error),
            };
            if let Some(entry) = handle
                .roster()
                .await
                .find_by_bridge_session_id(bridge_session_id)
            {
                let identity = entry.agent_identity.clone();
                return Ok(Some((mob_id, handle, identity)));
            }
        }
        Ok(None)
    }

    /// Who a detached outcome owed to the session `session_id` (a council's
    /// outcome owed to its convener) is committed for.
    ///
    /// A member seated in a loaded mob owns it as that member. Otherwise
    /// the session's stored member binding says whether it is a member of a
    /// mob this host knows and does not serve now, and such an outcome is
    /// never committed to the session as a plain session:
    ///
    /// - the binding names the default mob while it awaits its launch's
    ///   serve: the outcome stays owed ([`DetachedOutcomeOwner::AwaitingMob`]).
    ///   Nothing waits here for the serve: the caller is a pass that joins
    ///   many deliveries, and comes again when the launch has served;
    /// - the binding names another mob that is not loaded: the delivery is
    ///   demand for it, so it is loaded through the waiting lookup, as a
    ///   live delivery to its member loads it, and the member owns the
    ///   outcome. A mob that cannot be served now (held, quarantined, or a
    ///   load that failed) keeps the outcome owed;
    /// - the session has no stored binding (a plain session, or a member
    ///   session written before bindings were stored): it may be a member
    ///   of the host's default mob, so it is decided as one whose binding
    ///   names the default mob, in every state of that mob (it stays owed
    ///   while the default mob awaits its serve and while its store is
    ///   quarantined after a failed serve); it is a plain session once a
    ///   roster scan made with the default mob served does not seat it,
    ///   and on a host that declared no default mob;
    /// - a binding that cannot be read decides nothing: the error, and the
    ///   caller tries again.
    ///
    /// A binding that names a mob this host does not know, or a loaded mob
    /// that no longer seats the session, is a plain session's, as before.
    pub(crate) async fn detached_outcome_owner(
        &self,
        session_id: &SessionId,
    ) -> Result<DetachedOutcomeOwner, MobError> {
        // The decision reads one view of the set. A mob that reads served
        // after a roster scan that missed its member is scanned again (it
        // may have been loaded, or served by its launch, between the two
        // reads): a plain session is answered only after a scan made with
        // that mob served.
        // At most one load: the scan after it reads the mob it loaded.
        let mut scanned_while_served: Option<MobId> = None;
        for _ in 0..4 {
            if let Some((_, handle, identity)) =
                self.member_handle_for_bridge_session(session_id).await?
            {
                return Ok(DetachedOutcomeOwner::Member(handle, identity));
            }
            #[cfg(test)]
            self.park_at("detached outcome owner: after the roster scan")
                .await;
            let view = self
                .session_service
                .load_persisted_session_metadata(session_id)
                .await
                .map_err(|error| {
                    tracing::warn!(
                        %session_id,
                        %error,
                        "a session's stored member binding could not be read; the owner of what is owed to it is not decided"
                    );
                    MobError::ProvenanceUnavailable { mob_id: None }
                })?;
            // A session with no stored binding may still be a member of the
            // host's default mob (a member session written before bindings
            // were stored): it is decided as one whose binding names the
            // default mob, in every state of that mob. With no default mob
            // declared it is a plain session.
            let Some(mob_id) = view
                .as_ref()
                .and_then(persisted_mob_binding)
                .or_else(|| self.hosted.default_mob_id().cloned())
            else {
                return Ok(DetachedOutcomeOwner::Session);
            };
            if self.hosted.launch_serve_awaited().await.as_ref() == Some(&mob_id) {
                return Ok(DetachedOutcomeOwner::AwaitingMob(mob_id));
            }
            match self.hosted_mob(&mob_id).await {
                HostedMob::Absent => return Ok(DetachedOutcomeOwner::Session),
                HostedMob::Managed(_) => {
                    if scanned_while_served.as_ref() == Some(&mob_id) {
                        return Ok(DetachedOutcomeOwner::Session);
                    }
                    scanned_while_served = Some(mob_id);
                }
                HostedMob::Held(_) | HostedMob::Quarantined(_) => {
                    return Ok(DetachedOutcomeOwner::AwaitingMob(mob_id));
                }
                HostedMob::Unloaded | HostedMob::Unloading => {
                    if !self.load_if_unloaded(&mob_id).await {
                        return Ok(DetachedOutcomeOwner::AwaitingMob(mob_id));
                    }
                }
            }
        }
        // The set kept changing under the decision: nothing is decided, and
        // the caller tries again.
        Err(MobError::ProvenanceUnavailable { mob_id: None })
    }

    /// Whether the default mob awaits its launch's first serve
    /// ([`hosted_set::HostedSet::launch_serve_awaited`]).
    pub(crate) async fn launch_serve_awaited(&self) -> Option<MobId> {
        self.hosted.launch_serve_awaited().await
    }

    /// Whether mob `mob_id`, which an outcome waits for
    /// ([`DetachedOutcomeOwner::AwaitingMob`]), is served now or no longer
    /// known: either way the outcome's owner can be decided again.
    pub(crate) async fn awaited_mob_settled(&self, mob_id: &MobId) -> bool {
        matches!(
            self.hosted_mob(mob_id).await,
            HostedMob::Managed(_) | HostedMob::Absent
        )
    }

    /// What a sweep pass leaves owed, per mob: the mobs of `awaited` (one
    /// entry of it per outcome that waits for its mob,
    /// [`DetachedOutcomeOwner::AwaitingMob`]), each once, with the number of
    /// outcomes that wait for it and the state that holds them now. Nothing
    /// owed is no entry.
    pub(crate) async fn owed_outcomes_by_mob(&self, awaited: &[MobId]) -> Vec<OwedOutcomes> {
        let mut counted: BTreeMap<&MobId, usize> = BTreeMap::new();
        for mob_id in awaited {
            *counted.entry(mob_id).or_default() += 1;
        }
        let mut owed = Vec::with_capacity(counted.len());
        for (mob_id, outcomes) in counted {
            // The default mob that awaits its serve is named from its
            // store's record, which says whether the wait still stands.
            let state = if self.hosted.launch_serve_awaited().await.as_ref() == Some(mob_id) {
                OwedMobState::AwaitingServe
            } else {
                OwedMobState::of(&self.hosted_mob(mob_id).await)
            };
            owed.push(OwedOutcomes {
                mob_id: mob_id.clone(),
                outcomes,
                state,
            });
        }
        owed
    }

    /// Resolve the current runtime binding for an opaque member reference
    /// under the scope of the operation that will consume it.
    ///
    /// This deliberately does not call `mob_list_members`: resolving a write
    /// target must not secretly require `List`, and a denied write must fail
    /// before revealing whether the member exists.
    async fn member_binding_after_admission(
        &self,
        mob_id: &MobId,
        identity: &AgentIdentity,
        required: ControlScope,
    ) -> Result<(meerkat_mob::AgentRuntimeId, meerkat_mob::FenceToken), MobError> {
        let handle = self.admitted_handle_for(mob_id, required).await?;
        let entry = handle
            .list_members_including_retiring()
            .await
            .into_iter()
            .find(|entry| &entry.agent_identity == identity)
            .ok_or_else(|| MobError::MemberNotFound(identity.clone()))?;
        entry.binding_atoms().ok_or_else(|| {
            MobError::Internal(format!(
                "member {identity} has no MobMachine runtime binding"
            ))
        })
    }

