    /// Two hosted rosters naming the caller session record `Ambiguous` with
    /// their count, and never pick one of them; one names the member, none
    /// names the session.
    #[test]
    fn the_creation_provenance_never_picks_between_rosters() {
        let session_id = SessionId::new();
        let matched = |mob: &str| SessionMemberMatch {
            mob_id: MobId::from(mob),
            incarnation: meerkat_core::service::MobIncarnationId::mint(),
            identity: AgentIdentity::from("worker-1"),
            generation: meerkat_mob::Generation::INITIAL,
        };
        for caller in [SessionCreateCaller::Host, SessionCreateCaller::Session] {
            assert_eq!(
                session_creation_provenance(&session_id, vec![matched("a"), matched("b")], caller),
                meerkat_mob::MobProvenance::Ambiguous {
                    matching_rosters: 2
                }
            );
        }
        let one = matched("a");
        assert_eq!(
            session_creation_provenance(&session_id, vec![one.clone()], SessionCreateCaller::Host),
            meerkat_mob::MobProvenance::Member {
                parent_mob_id: one.mob_id.clone(),
                parent_incarnation: one.incarnation,
                creator_identity: one.identity.clone(),
                creator_generation: one.generation,
                owner_session: session_id.clone(),
            }
        );
        assert_eq!(
            session_creation_provenance(
                &session_id,
                vec![one.clone()],
                SessionCreateCaller::Session
            ),
            meerkat_mob::MobProvenance::OperatorMember {
                parent_mob_id: one.mob_id,
                parent_incarnation: one.incarnation,
                creator_identity: one.identity,
                creator_generation: one.generation,
                owner_session: session_id.clone(),
            }
        );
        assert_eq!(
            session_creation_provenance(&session_id, Vec::new(), SessionCreateCaller::Host),
            meerkat_mob::MobProvenance::Session {
                session_id: session_id.clone()
            }
        );
        assert_eq!(
            session_creation_provenance(&session_id, Vec::new(), SessionCreateCaller::Session),
            meerkat_mob::MobProvenance::OperatorSession {
                session_id: session_id.clone()
            }
        );
    }

    /// The council id form is decided in one place for every create: each
    /// allocation of storage for a new mob follows an `admit_create`, every
    /// `admit_create` but one is an ordinary create's, and the one that is a
    /// council's is reached only through `create_temporary_council_mob`,
    /// which the council coordinator alone calls. A create entry that passes
    /// itself off as a council's, or a new create that skips the admission,
    /// fails here.
    #[test]
    fn only_a_councils_own_create_may_use_the_council_id_form() {
        fn shipped(dir: &std::path::Path, out: &mut Vec<(std::path::PathBuf, String)>) {
            for entry in std::fs::read_dir(dir).expect("read the crate's sources") {
                let path = entry.expect("a source entry").path();
                if path.is_dir() {
                    // A `tests` directory holds test-only module files.
                    if path.file_name().is_some_and(|name| name == "tests") {
                        continue;
                    }
                    shipped(&path, out);
                    continue;
                }
                let name = path
                    .file_name()
                    .and_then(|name| name.to_str())
                    .unwrap_or_default();
                if !name.ends_with(".rs") || name == "tests.rs" || name.ends_with("_tests.rs") {
                    continue;
                }
                let source = std::fs::read_to_string(&path).expect("read a source file");
                let code = source.split("\nmod tests {").next().unwrap_or_default();
                out.push((path, code.to_string()));
            }
        }
        // Read when the test runs, not when it is compiled: an archived
        // test runs where the builder's checkout does not exist.
        let src = std::path::PathBuf::from(
            std::env::var_os("CARGO_MANIFEST_DIR")
                .expect("CARGO_MANIFEST_DIR is set for test processes"),
        )
        .join("src");
        let mut sources = Vec::new();
        shipped(&src, &mut sources);
        let count = |needle: &str| -> Vec<(String, usize)> {
            sources
                .iter()
                .map(|(path, code)| {
                    let name = path
                        .strip_prefix(&src)
                        .unwrap_or(path)
                        .display()
                        .to_string();
                    (name, code.matches(needle).count())
                })
                .filter(|(_, found)| *found > 0)
                .collect()
        };
        let in_lib = |found: usize| vec![("lib.rs".to_string(), found)];

        // Two creates allocate storage for a new mob (a definition's and a
        // mobpack's), and each is admitted first.
        assert_eq!(count("self.storage_for_new_mob("), in_lib(2));
        assert_eq!(count("self.admit_create("), in_lib(2));
        // Those two are the only places a new mob is built: a create that
        // built on storage of its own would allocate none here.
        assert_eq!(count("MobBuilder::new("), in_lib(2));
        // One entry passes a council's use, and the coordinator alone calls
        // it.
        assert_eq!(count("ReservedMobIdUse::TemporaryCouncil"), in_lib(1));
        let lib = &sources
            .iter()
            .find(|(path, _)| path == &src.join("lib.rs"))
            .expect("the crate root is shipped code")
            .1;
        let door = lib
            .find("pub(crate) async fn create_temporary_council_mob(")
            .expect("the council's create entry");
        let door_end = door + lib[door..].find("\n    }\n").expect("the entry ends");
        let council_use = lib
            .find("ReservedMobIdUse::TemporaryCouncil")
            .expect("the council's use");
        assert!(
            (door..door_end).contains(&council_use),
            "the council's use is passed by the council's create entry only"
        );
        assert_eq!(
            count(".create_temporary_council_mob("),
            vec![("temporary_council.rs".to_string(), 1)],
            "only the council coordinator creates a mob under the council id form"
        );
        // The same entry is the one place a create is told to be a council's:
        // a council origin is built once, there, and every other create
        // passes none.
        assert_eq!(count("MobCreateCouncilOrigin {"), in_lib(2));
        assert_eq!(count("Some(MobCreateCouncilOrigin {"), in_lib(1));
        let council_origin = lib
            .find("Some(MobCreateCouncilOrigin {")
            .expect("the council origin");
        assert!(
            (door..door_end).contains(&council_origin),
            "a council origin is built by the council's create entry only"
        );
    }

    /// The dispatcher's `mob_create` makes no ordinary mob under an id of the
    /// form temporary councils own: the call fails naming the reserved
    /// identifier, and no mob is managed under the id. One hyphen is an
    /// ordinary id.
    #[tokio::test]
    async fn the_dispatchers_mob_create_refuses_an_id_of_the_council_form() {
        let svc = Arc::new(MockSessionSvc::new());
        let state = Arc::new(
            MobMcpState::new(svc, meerkat_mob::MobControlPrincipal::Owner)
                .expect("construct runtime authority"),
        );
        let d = MobMcpDispatcher::new(state.clone());
        let definition = |id: &str| json!({"definition":{"id":id,"profiles":{"worker":{"model":"claude-sonnet-4-6","tools":{"comms":true}}}}});

        let error = call_tool_err(&d, "mob_create", definition("council--from-a-dispatcher")).await;
        let text = error.to_string();
        assert!(
            text.contains("reserved_system_identifier")
                && text.contains("council--from-a-dispatcher"),
            "the refusal names the reserved id: {text}"
        );
        assert!(
            state
                .handle_for(&MobId::from("council--from-a-dispatcher"))
                .await
                .is_err(),
            "no mob is created"
        );

        let created = call_tool(&d, "mob_create", definition("council-from-a-dispatcher")).await;
        assert_eq!(created["mob_id"], "council-from-a-dispatcher");
    }

    /// The hosted set's records have one writer. Every input of the store
    /// record machine is applied in the hosted set module, so no other code
    /// of this crate moves a mob between the sets; and only
    /// `try_mob_insert_handle` registers a host's handle, so a host insert
    /// can never skip the fact that keeps the
    /// member lookup's second completeness arm honest.
    #[test]
    fn every_store_record_input_is_applied_by_the_hosted_set() {
        // The shipped code of every source file of this crate: the code
        // before its `mod tests`, and no test-only module file.
        fn shipped_sources(dir: &std::path::Path, out: &mut Vec<(std::path::PathBuf, String)>) {
            for entry in std::fs::read_dir(dir).expect("read the crate's sources") {
                let path = entry.expect("a source entry").path();
                if path.is_dir() {
                    shipped_sources(&path, out);
                    continue;
                }
                let Some(name) = path.file_name().and_then(|name| name.to_str()) else {
                    continue;
                };
                if !name.ends_with(".rs") || name == "tests.rs" || name.ends_with("_tests.rs") {
                    continue;
                }
                let source = std::fs::read_to_string(&path).expect("read a source file");
                let shipped = source.split("\nmod tests {").next().unwrap_or_default();
                out.push((path, shipped.to_string()));
            }
        }
        // Where the method that starts with `signature` lies in `source`: up
        // to the end of its body at method indentation.
        fn method(source: &str, signature: &str) -> std::ops::Range<usize> {
            let start = source.find(signature).expect("the method exists");
            let end = source[start..]
                .find("\n    }\n")
                .map(|end| start + end)
                .expect("the method ends");
            start..end
        }
        let mut sources = Vec::new();
        shipped_sources(
            &std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("src"),
            &mut sources,
        );
        let src = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("src");
        let lib = src.join("lib.rs");
        let hosted_set = src.join("hosted_set.rs");
        let lib_source = &sources
            .iter()
            .find(|(path, _)| path == &lib)
            .expect("the crate root is shipped code")
            .1;
        assert!(
            sources.iter().any(|(path, _)| path == &hosted_set),
            "the hosted set module is shipped code"
        );
        let host_insert = method(lib_source, "pub async fn try_mob_insert_handle(");
        let mut record_writers = Vec::new();
        let mut host_registrations = Vec::new();
        for (path, source) in &sources {
            if path == &hosted_set {
                continue;
            }
            for needle in [
                "MobStoreRestoreLifecycleMachineMutator",
                "MobStoreRestoreLifecycleInput",
                "MobStoreRestoreLifecycleMachineAuthority",
            ] {
                for (at, _) in source.match_indices(needle) {
                    record_writers.push((path.clone(), needle, at));
                }
            }
            // The hosted set's one registration takes no origin: it is a
            // host's handle by its name. Every mention of it outside the
            // module is counted, a call and a path to it alike.
            for (at, _) in source.match_indices("register_host_handle") {
                host_registrations.push((path.clone(), at));
            }
        }
        assert!(
            record_writers.is_empty(),
            "only the hosted set module holds a store record or applies an input to one: {record_writers:?}"
        );
        assert_eq!(
            host_registrations.len(),
            1,
            "one host-handle registration outside the hosted set module: {host_registrations:?}"
        );
        assert!(
            host_registrations[0].0 == lib && host_insert.contains(&host_registrations[0].1),
            "the host-handle registration is try_mob_insert_handle: {host_registrations:?}"
        );
        // The hosted set module has that one registration and no other:
        // none that takes an origin, so no caller can register a handle as
        // anything but a host's.
        let hosted_set_source = &sources
            .iter()
            .find(|(path, _)| path == &hosted_set)
            .expect("the hosted set module is shipped code")
            .1;
        assert_eq!(
            hosted_set_source
                .match_indices("fn register_host_handle(")
                .count(),
            1,
            "the hosted set registers a host's handle in one method"
        );
        assert_eq!(
            hosted_set_source.match_indices("fn register(").count(),
            0,
            "the hosted set has no registration that takes an origin"
        );
        let registration = method(hosted_set_source, "pub(crate) fn register_host_handle(");
        assert_eq!(
            hosted_set_source
                .match_indices("Input::Register {")
                .filter(|(at, _)| !registration.contains(at))
                .count(),
            0,
            "a registration is applied to a record by that method alone"
        );
        // Whether a mob may be unloaded is decided by the record machine's
        // guard alone: no shipped code of this crate, the hosted set module
        // included, reads the origin a record holds. Only the hosted set
        // module holds a record, so there any field access named `origin`
        // is such a read, also through a local binding of the record's
        // state (`let state = ...; state.origin`).
        let origin_reads = sources
            .iter()
            .flat_map(|(path, source)| {
                let field: &[&'static str] = if path == &hosted_set {
                    &[".origin"]
                } else {
                    &[]
                };
                ["state().origin", ".origin()", "fn origin("]
                    .into_iter()
                    .chain(field.iter().copied())
                    .flat_map(move |needle| {
                        source
                            .match_indices(needle)
                            .map(move |(at, _)| (path.clone(), needle, at))
                    })
            })
            .collect::<Vec<_>>();
        assert!(
            origin_reads.is_empty(),
            "no code beside the machine reads a record's origin: {origin_reads:?}"
        );
    }

    /// This crate's `src` directory, read when the test runs, not when it is
    /// compiled: an archived test runs where the builder's checkout does not
    /// exist.
    fn crate_src_dir() -> std::path::PathBuf {
        std::path::PathBuf::from(
            std::env::var_os("CARGO_MANIFEST_DIR")
                .expect("CARGO_MANIFEST_DIR is set for test processes"),
        )
        .join("src")
    }

    /// The shipped code of every source file of this crate: the code before
    /// its `mod tests`, and no test-only module file.
    fn shipped_crate_sources() -> Vec<(std::path::PathBuf, String)> {
        fn walk(dir: &std::path::Path, out: &mut Vec<(std::path::PathBuf, String)>) {
            for entry in std::fs::read_dir(dir).expect("read the crate's sources") {
                let path = entry.expect("a source entry").path();
                if path.is_dir() {
                    walk(&path, out);
                    continue;
                }
                let Some(name) = path.file_name().and_then(|name| name.to_str()) else {
                    continue;
                };
                if !name.ends_with(".rs") || name == "tests.rs" || name.ends_with("_tests.rs") {
                    continue;
                }
                let source = std::fs::read_to_string(&path).expect("read a source file");
                let shipped = source.split("\nmod tests {").next().unwrap_or_default();
                out.push((path, shipped.to_string()));
            }
        }
        let mut sources = Vec::new();
        walk(&crate_src_dir(), &mut sources);
        sources
    }

    /// The facts about the hosted set as a whole live in the set's own
    /// machine: whether every store this host has from before is recorded,
    /// whether a host registered a handle of its own, and how far the pass
    /// over the stores from before came. No shipped code of this crate
    /// keeps one of them as a field of its own beside that machine.
    #[test]
    fn no_fact_of_the_hosted_set_is_kept_beside_its_machine() {
        let sources = shipped_crate_sources();
        let kept = sources
            .iter()
            .flat_map(|(path, source)| {
                [
                    "census_complete: ",
                    "host_inserted: ",
                    "restore_pass_attempted",
                    "restore_lock: Mutex<bool>",
                ]
                .into_iter()
                .flat_map(move |needle| {
                    source
                        .match_indices(needle)
                        .map(move |(at, _)| (path.clone(), needle, at))
                })
            })
            .collect::<Vec<_>>();
        assert!(
            kept.is_empty(),
            "a fact of the hosted set is kept as a field beside the set's machine: {kept:?}"
        );
    }

    /// The set's machine has one writer. Every input of it is applied in
    /// the hosted set module, through one function, and the input that says
    /// a host registered a handle of its own is applied in the step that
    /// registers the handle and nowhere else.
    #[test]
    fn every_input_of_the_set_machine_is_applied_by_the_hosted_set() {
        let sources = shipped_crate_sources();
        let hosted_set = crate_src_dir().join("hosted_set.rs");
        let outside = sources
            .iter()
            .filter(|(path, _)| path != &hosted_set)
            .flat_map(|(path, source)| {
                source
                    .match_indices("MobHostedSetLifecycle")
                    .map(move |(at, _)| (path.clone(), at))
            })
            .collect::<Vec<_>>();
        assert!(
            outside.is_empty(),
            "only the hosted set module holds the set's machine or applies an input to it: \
             {outside:?}"
        );
        let module = &sources
            .iter()
            .find(|(path, _)| path == &hosted_set)
            .expect("the hosted set module is shipped code")
            .1;
        assert_eq!(
            module
                .matches("MobHostedSetLifecycleMachineMutator::apply")
                .count(),
            1,
            "the hosted set module applies the set machine's inputs through one function"
        );
        let register = module
            .find("    pub(crate) fn register_host_handle(")
            .expect("the hosted set registers handles");
        let register = register
            ..module[register..]
                .find("\n    }\n")
                .map(|end| register + end)
                .expect("the registration ends");
        let host_handles = module
            .match_indices("::RegisterHostHandle")
            .map(|(at, _)| at)
            .collect::<Vec<_>>();
        assert_eq!(
            host_handles.len(),
            1,
            "one place says that a host registered a handle of its own: {host_handles:?}"
        );
        assert!(
            register.contains(&host_handles[0]),
            "a host's handle is noted in the step that registers it"
        );
    }

    /// The fact that a host registered a handle of its own outlives that
    /// handle. A host that inserted a mob and destroyed it again is still a
    /// host that restores its mobs itself: until it says its restore is
    /// done, a mob no record names may still be inserted, so the member
    /// lookup stays incomplete although no record of a host's handle is
    /// left.
    #[tokio::test]
    async fn a_destroyed_host_handle_still_keeps_the_member_lookup_incomplete() {
        let svc = Arc::new(MockSessionSvc::new());
        let state = Arc::new(
            MobMcpState::new(svc.clone(), meerkat_mob::MobControlPrincipal::Owner)
                .expect("runtime custody"),
        );
        let host = Arc::new(
            MobMcpState::new(svc.clone(), meerkat_mob::MobControlPrincipal::Owner)
                .expect("runtime custody"),
        );
        let inserted = host
            .mob_create_definition(explicit_definition("latch-inserted"))
            .await
            .expect("a mob the host restores by insertion");
        state
            .try_mob_insert_handle(
                inserted.clone(),
                host.handle_for(&inserted).await.expect("host handle"),
            )
            .await
            .expect("insert the host's mob");
        state
            .mob_destroy(&inserted)
            .await
            .expect("destroy the inserted mob");
        assert!(
            !state.hosted.read().await.is_managed(&inserted),
            "the destroyed mob is not managed any more"
        );
        let caller = SessionId::new();
        svc.insert_persisted_session(Session::with_id(caller.clone()))
            .await;
        let refused = state
            .mob_create_definition_with_owner_bridge_session(
                explicit_definition("latch-refused"),
                caller.clone(),
                false,
                false,
            )
            .await
            .expect_err("the host has not declared its restore done");
        assert!(
            matches!(refused, MobError::ProvenanceUnavailable { mob_id: None }),
            "{refused:?}"
        );
        assert!(!state.mob_set_complete());
        state.declare_mob_set_restored();
        assert!(state.mob_set_complete());
        state
            .mob_create_definition_with_owner_bridge_session(
                explicit_definition("latch-refused"),
                caller,
                false,
                false,
            )
            .await
            .expect("the declared set completes the lookup");
    }

    /// A pass over the persistent root that did not run to its end leaves
    /// the set incomplete: the verb that started it answers the failure,
    /// nothing is read as gone for good, and the next verb runs the pass
    /// again. The pass that finishes completes the set.
    #[cfg(unix)]
    #[tokio::test]
    async fn a_pass_that_did_not_finish_leaves_the_set_incomplete_and_the_next_pass_completes_it() {
        let svc = Arc::new(MockSessionSvc::new());
        let root = tempfile::tempdir().expect("tempdir");
        let state = restored_state(&svc, root.path());
        let mobs = MobMcpState::persistent_mob_root(root.path());
        let aside = root.path().join("mobs-aside");
        // The root is not a directory while the first pass runs.
        std::fs::rename(&mobs, &aside).expect("move the root aside");
        std::fs::write(&mobs, b"not a directory").expect("a file at the root's place");
        let failed = state
            .mob_list()
            .await
            .expect_err("a pass over a root that is no directory fails");
        assert!(matches!(failed, MobError::Internal(_)), "{failed:?}");
        assert!(
            !state.mob_set_complete(),
            "a pass that did not finish completes nothing"
        );
        assert!(
            !state.mob_is_retired(&MobId::from("never-listed")).await,
            "no mob is gone for good before a pass finished"
        );
        // The root is back: the next verb runs the pass again.
        std::fs::remove_file(&mobs).expect("remove the file");
        std::fs::rename(&aside, &mobs).expect("move the root back");
        state.mob_list().await.expect("the second pass finishes");
        assert!(
            state.mob_set_complete(),
            "the finished pass completes the set"
        );
        assert!(state.mob_is_retired(&MobId::from("never-listed")).await);
    }

    /// A held child's store is read once per hold: after the first lookup
    /// read it, a damaged store changes no answer, for the session its
    /// roster names or for any other. (A read that fails is not kept: see
    /// `an_incomplete_lookup_refuses_the_create_and_names_the_blocking_mob`,
    /// whose first read happens after the damage.)
    #[tokio::test]
    async fn a_held_childs_store_is_read_once_per_hold() {
        let root = tempfile::tempdir().expect("tempdir");
        let (svc, child, owner, worker_session) = seat_child_worker_then_exit(
            &Arc::new(MockSessionSvc::new()),
            root.path(),
            "held-read-once",
        )
        .await;
        svc.script_observation(
            &owner,
            Ok(meerkat_mob::LiveDurableSourceObservation::Absent),
        );
        let restored = restored_state(&svc, root.path());
        assert_eq!(
            restored
                .held_child_mobs()
                .await
                .expect("the held child mobs read")
                .len(),
            1
        );
        let first = restored
            .session_member_matches(&worker_session)
            .await
            .expect("the held child's roster is read");
        assert_eq!(first.len(), 1, "{first:?}");
        assert_eq!(first[0].mob_id, child);
        assert_eq!(first[0].identity, AgentIdentity::from("worker-1"));

        let held_path = restored
            .hosted
            .read()
            .await
            .held(&child)
            .map(|held| held.storage_path.clone())
            .expect("the child is held");
        std::fs::write(&held_path, b"not a mob store").expect("damage the held store");
        assert_eq!(
            restored
                .session_member_matches(&worker_session)
                .await
                .expect("the kept read answers"),
            first
        );
        assert!(
            restored
                .session_member_matches(&SessionId::new())
                .await
                .expect("the kept read answers for any session")
                .is_empty()
        );
    }

    /// The creator a mob's creation record proves, whose manage grant the
    /// agent mob tools re-derive after a restart: only a session's own create
    /// with its create capability. An OperatorSession record proves the
    /// creating session. An OperatorMember record proves the creating
    /// member's session while that session serves the recorded member at
    /// the recorded generation in the recorded parent incarnation (or its
    /// same-session successor, which other rows cover): once the member is
    /// respawned onto a new session at its next generation, neither its old
    /// session nor its new one proves anything. A create the host made for
    /// the same session or member (`Session`, `Member`) proves nothing: the
    /// session owns that mob but did not create it. A host create, and any
    /// other session, prove nothing.
    #[tokio::test]
    async fn a_creation_record_proves_its_creator_session_at_the_recorded_generation() {
        let svc = Arc::new(MockSessionSvc::new());
        let root = tempfile::tempdir().expect("tempdir");
        let state = restored_state(&svc, root.path());
        let parent = state
            .mob_create_definition(explicit_definition("creator-parent"))
            .await
            .expect("create the parent mob");
        let worker = AgentIdentity::from("worker-1");
        state
            .mob_spawn(
                &parent,
                ProfileName::from("worker"),
                worker.clone(),
                Some(MobRuntimeMode::TurnDriven),
                None,
                None,
            )
            .await
            .expect("spawn the creator");
        let creator_session = state
            .mob_resolve_bridge_session_id(&parent, &worker)
            .await
            .expect("resolve bridge session")
            .expect("creator bridge session");
        let member_child = state
            .create_mob_for_owner_bridge_session(
                explicit_definition("creator-member-child"),
                creator_session.clone(),
                false,
                false,
                SessionCreateCaller::Session,
            )
            .await
            .expect("the member's session creates a mob")
            .mob_id;
        let member_child = state
            .handle_for(&member_child)
            .await
            .expect("member child handle");
        assert!(matches!(
            member_child.provenance().await.expect("provenance"),
            meerkat_mob::MobProvenance::OperatorMember { .. }
        ));
        assert!(
            state
                .session_is_recorded_creator(&member_child, &creator_session)
                .await
        );
        assert!(
            !state
                .session_is_recorded_creator(&member_child, &SessionId::new())
                .await
        );
        let member_owned = state
            .mob_create_definition_with_owner_bridge_session(
                explicit_definition("creator-member-owned"),
                creator_session.clone(),
                false,
                false,
            )
            .await
            .expect("the host creates a mob for the member's session");
        let member_owned = state
            .handle_for(&member_owned)
            .await
            .expect("member owned handle");
        assert!(matches!(
            member_owned.provenance().await.expect("provenance"),
            meerkat_mob::MobProvenance::Member { .. }
        ));
        assert!(
            !state
                .session_is_recorded_creator(&member_owned, &creator_session)
                .await,
            "a mob the host created for the member's session is not the member's create"
        );

        let caller = SessionId::new();
        svc.insert_persisted_session(Session::with_id(caller.clone()))
            .await;
        let session_child = state
            .create_mob_for_owner_bridge_session(
                explicit_definition("creator-session-child"),
                caller.clone(),
                false,
                false,
                SessionCreateCaller::Session,
            )
            .await
            .expect("a session creates a mob")
            .mob_id;
        let session_child = state
            .handle_for(&session_child)
            .await
            .expect("session child handle");
        assert_eq!(
            session_child.provenance().await.expect("provenance"),
            meerkat_mob::MobProvenance::OperatorSession {
                session_id: caller.clone()
            }
        );
        assert!(
            state
                .session_is_recorded_creator(&session_child, &caller)
                .await
        );
        assert!(
            !state
                .session_is_recorded_creator(&session_child, &creator_session)
                .await
        );
        let session_owned = state
            .mob_create_definition_with_owner_bridge_session(
                explicit_definition("creator-session-owned"),
                caller.clone(),
                true,
                false,
            )
            .await
            .expect("the host creates a mob for the session");
        let session_owned = state
            .handle_for(&session_owned)
            .await
            .expect("session owned handle");
        assert!(
            !state
                .session_is_recorded_creator(&session_owned, &caller)
                .await,
            "a mob the host created for the session is not the session's create"
        );

        let host = state
            .mob_create_definition(explicit_definition("creator-host"))
            .await
            .expect("a host create");
        let host = state.handle_for(&host).await.expect("host handle");
        assert!(!state.session_is_recorded_creator(&host, &caller).await);
        assert!(
            !state
                .session_is_recorded_creator(&host, &creator_session)
                .await
        );

        state
            .mob_respawn(&parent, worker.clone(), None)
            .await
            .expect("respawn the creating member at its next generation");
        let respawned_session = state
            .mob_resolve_bridge_session_id(&parent, &worker)
            .await
            .expect("resolve the respawned bridge session")
            .expect("respawned bridge session");
        assert!(
            !state
                .session_is_recorded_creator(&member_child, &creator_session)
                .await,
            "the old session no longer serves the recorded generation"
        );
        assert!(
            !state
                .session_is_recorded_creator(&member_child, &respawned_session)
                .await,
            "a later generation of the creating member proves nothing"
        );
    }

    /// A session create whose lookup cannot be complete is refused before
    /// anything of the mob exists: while a state that inserted handles has
    /// not declared its mob set restored (no mob named), and while a held
    /// child's roster cannot be read (that child named). A host create runs
    /// no lookup and is not refused.
    #[tokio::test]
    async fn an_incomplete_lookup_refuses_the_create_and_names_the_blocking_mob() {
        let svc = Arc::new(MockSessionSvc::new());
        let state = Arc::new(
            MobMcpState::new(svc.clone(), meerkat_mob::MobControlPrincipal::Owner)
                .expect("runtime custody"),
        );
        let host = Arc::new(
            MobMcpState::new(svc.clone(), meerkat_mob::MobControlPrincipal::Owner)
                .expect("runtime custody"),
        );
        let inserted = host
            .mob_create_definition(explicit_definition("provenance-inserted"))
            .await
            .expect("a mob the host restores by insertion");
        state
            .try_mob_insert_handle(
                inserted.clone(),
                host.handle_for(&inserted).await.expect("host handle"),
            )
            .await
            .expect("insert the host's mob");
        let caller = SessionId::new();
        svc.insert_persisted_session(Session::with_id(caller.clone()))
            .await;
        let refused = state
            .mob_create_definition_with_owner_bridge_session(
                explicit_definition("provenance-refused"),
                caller.clone(),
                false,
                false,
            )
            .await
            .expect_err("an undeclared restore leaves the lookup incomplete");
        assert!(
            matches!(refused, MobError::ProvenanceUnavailable { mob_id: None }),
            "{refused:?}"
        );
        assert!(
            state
                .handle_for(&MobId::from("provenance-refused"))
                .await
                .is_err(),
            "nothing of the refused mob exists"
        );
        state
            .mob_create_definition(explicit_definition("provenance-host-anyway"))
            .await
            .expect("a host create runs no lookup");
        state.declare_mob_set_restored();
        state
            .mob_create_definition_with_owner_bridge_session(
                explicit_definition("provenance-refused"),
                caller,
                false,
                false,
            )
            .await
            .expect("the declared set completes the lookup");

        // A held child whose store cannot be read blocks every session
        // create, named.
        let root = tempfile::tempdir().expect("tempdir");
        let (svc, child, owner, _worker_session) = seat_child_worker_then_exit(
            &Arc::new(MockSessionSvc::new()),
            root.path(),
            "held-unreadable",
        )
        .await;
        svc.script_observation(
            &owner,
            Ok(meerkat_mob::LiveDurableSourceObservation::Absent),
        );
        let restored = restored_state(&svc, root.path());
        assert_eq!(
            restored
                .held_child_mobs()
                .await
                .expect("the held child mobs read")
                .len(),
            1
        );
        let held_path = restored
            .hosted
            .read()
            .await
            .held(&child)
            .map(|held| held.storage_path.clone())
            .expect("the child is held");
        std::fs::write(&held_path, b"not a mob store").expect("damage the held store");
        let caller = SessionId::new();
        svc.insert_persisted_session(Session::with_id(caller.clone()))
            .await;
        let refused = restored
            .mob_create_definition_with_owner_bridge_session(
                explicit_definition("provenance-blocked"),
                caller,
                false,
                false,
            )
            .await
            .expect_err("an unreadable held roster leaves the lookup incomplete");
        assert!(
            matches!(&refused, MobError::ProvenanceUnavailable { mob_id: Some(blocking) } if blocking == &child),
            "{refused:?}"
        );
        restored
            .mob_create_definition(explicit_definition("provenance-host-held"))
            .await
            .expect("a host create is not blocked");
    }

    /// A handle a host inserts while a member lookup scans may hold a roster
    /// the scan did not read: the lookup reads its completeness again after
    /// the scan, and the create is refused even though the inserted roster
    /// names the caller session.
    #[tokio::test]
    async fn a_handle_inserted_during_the_lookup_refuses_the_create() {
        let svc = Arc::new(MockSessionSvc::new());
        let host = Arc::new(
            MobMcpState::new(svc.clone(), meerkat_mob::MobControlPrincipal::Owner)
                .expect("runtime custody"),
        );
        let inserted = host
            .mob_create_definition(explicit_definition("provenance-racing-insert"))
            .await
            .expect("the mob the host inserts");
        let worker = AgentIdentity::from("worker-1");
        host.mob_spawn(
            &inserted,
            ProfileName::from("worker"),
            worker.clone(),
            Some(MobRuntimeMode::TurnDriven),
            None,
            None,
        )
        .await
        .expect("spawn the member whose session creates");
        let caller = host
            .mob_resolve_bridge_session_id(&inserted, &worker)
            .await
            .expect("resolve bridge session")
            .expect("member bridge session");
        let state = Arc::new(
            MobMcpState::new(svc.clone(), meerkat_mob::MobControlPrincipal::Owner)
                .expect("runtime custody"),
        );
        let hold = Arc::new(InsertHold::default());
        *state
            .member_lookup_hold
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(Arc::clone(&hold));
        let creating = Arc::clone(&state);
        let create_caller = caller.clone();
        let create = tokio::spawn(async move {
            creating
                .mob_create_definition_with_owner_bridge_session(
                    explicit_definition("provenance-during-insert"),
                    create_caller,
                    false,
                    false,
                )
                .await
        });
        tokio::time::timeout(Duration::from_secs(10), async {
            while !hold.reached.load(std::sync::atomic::Ordering::SeqCst) {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("the lookup passed its first completeness check");
        state
            .try_mob_insert_handle(
                inserted.clone(),
                host.handle_for(&inserted).await.expect("host handle"),
            )
            .await
            .expect("insert the host's mob while the lookup is parked");
        hold.release.notify_one();
        let refused = create
            .await
            .expect("the create task ends")
            .expect_err("an insert during the lookup leaves it incomplete");
        assert!(
            matches!(refused, MobError::ProvenanceUnavailable { mob_id: None }),
            "{refused:?}"
        );
        assert!(
            state
                .handle_for(&MobId::from("provenance-during-insert"))
                .await
                .is_err(),
            "nothing of the refused mob exists"
        );
    }

    /// An operator releases a held child whose owner never resolves: it is
    /// destroyed through the ordinary destroy envelope.
    #[tokio::test]
    async fn operator_destroys_a_held_child_mob() {
        let svc = Arc::new(MockSessionSvc::new());
        let root = tempfile::tempdir().expect("tempdir");
        let (svc, mob_id, owner, _worker_session) =
            seat_child_worker_then_exit(&svc, root.path(), "owner-never-resolves").await;
        svc.script_observation(
            &owner,
            Ok(meerkat_mob::LiveDurableSourceObservation::Absent),
        );
        let activations_before = svc.session_activation_count();
        let restored = restored_state(&svc, root.path());
        assert_held_before_activation(restored.handle_for(&mob_id).await, "owner_absent");

        // A release cancelled while it holds at its WorkGraph preflight
        // leaves the child held: typed lookup, storage kept, nothing
        // activated. (This state is not shared, so the release runs on its
        // caller; the shared, state-owned handoff is pinned below.)
        let hold = hold_teardown_preflight(&restored);
        cancel_at_teardown_preflight(restored.destroy_held_child_mob(&mob_id), &hold).await;
        release_teardown_preflight(&restored);
        assert_held_before_activation(restored.handle_for(&mob_id).await, "owner_absent");
        assert_eq!(
            mob_store_files(root.path()),
            1,
            "a cancelled release keeps storage"
        );
        assert_eq!(svc.session_activation_count(), activations_before);

        restored
            .destroy_held_child_mob(&mob_id)
            .await
            .expect("the operator releases the held child");
        assert!(matches!(
            restored.handle_for(&mob_id).await,
            Err(MobError::MobNotFound(_))
        ));
        assert!(
            restored
                .held_child_mobs()
                .await
                .expect("the held child mobs read")
                .is_empty()
        );
        assert_eq!(
            mob_store_files(root.path()),
            0,
            "the released child's storage is removed"
        );
        assert_eq!(
            svc.session_activation_count(),
            activations_before,
            "the operator release never activates the member"
        );
    }

    /// On a shared state the held child's release hands over to a task the
    /// state owns: a caller cancelled at the WorkGraph preflight leaves the
    /// handoff parked and the stand-down unsettled; once the gate is
    /// notified, the handoff finishes without its caller and the stand-down
    /// settles.
    #[tokio::test]
    async fn a_cancelled_shared_release_finishes_as_a_state_task() {
        let svc = Arc::new(MockSessionSvc::new());
        let root = tempfile::tempdir().expect("tempdir");
        let (svc, mob_id, owner, _worker_session) =
            seat_child_worker_then_exit(&svc, root.path(), "shared-release").await;
        svc.script_observation(
            &owner,
            Ok(meerkat_mob::LiveDurableSourceObservation::Absent),
        );
        let activations_before = svc.session_activation_count();
        let restored = MobMcpState::new(svc.clone(), meerkat_mob::MobControlPrincipal::Owner)
            .expect("runtime custody")
            .with_persistent_storage_root(Some(root.path().to_path_buf()))
            .into_shared();
        assert_held_before_activation(restored.handle_for(&mob_id).await, "owner_absent");

        let hold = hold_teardown_preflight(&restored);
        cancel_at_teardown_preflight(restored.destroy_held_child_mob(&mob_id), &hold).await;
        let parked = restored
            .stand_down(std::time::Instant::now() + Duration::from_millis(50))
            .await;
        assert!(
            matches!(&parked, MobStateStandDown::Unsettled { reasons } if reasons.iter().any(|reason| reason.contains("child mob teardown handoff"))),
            "the parked handoff holds the stand-down: {parked:?}"
        );
        assert_eq!(
            mob_store_files(root.path()),
            1,
            "nothing is torn down while the handoff is parked"
        );

        // Clearing the gate's slot would not wake the parked task: notify it.
        hold.release.notify_one();
        assert_eq!(
            restored.stand_down(far_deadline()).await,
            MobStateStandDown::Clean
        );
        assert!(
            restored
                .held_child_mobs()
                .await
                .expect("the held child mobs read")
                .is_empty(),
            "the handoff moved the child into managed custody without its caller"
        );
        assert_eq!(svc.session_activation_count(), activations_before);
    }

    /// A scavenger pass cancelled at its teardown preflight, with the owner
    /// now archived, leaves the child held; a later pass tears it down.
    #[tokio::test]
    async fn cancelled_reobservation_keeps_the_child_held() {
        let svc = Arc::new(MockSessionSvc::new());
        let root = tempfile::tempdir().expect("tempdir");
        let (svc, mob_id, owner, _worker_session) =
            seat_child_worker_then_exit(&svc, root.path(), "reobserve-cancelled").await;
        svc.script_observation(
            &owner,
            Ok(meerkat_mob::LiveDurableSourceObservation::Absent),
        );
        let activations_before = svc.session_activation_count();
        let restored = restored_state(&svc, root.path());
        assert_held_before_activation(restored.handle_for(&mob_id).await, "owner_absent");

        svc.script_observation(
            &owner,
            Ok(meerkat_mob::LiveDurableSourceObservation::Archived),
        );
        let hold = hold_teardown_preflight(&restored);
        cancel_at_teardown_preflight(
            restored.scavenge_orphaned_bridge_session_scoped_mobs(),
            &hold,
        )
        .await;
        release_teardown_preflight(&restored);
        assert_held_before_activation(restored.handle_for(&mob_id).await, "owner_absent");
        assert_eq!(
            mob_store_files(root.path()),
            1,
            "a cancelled pass keeps storage"
        );
        assert_eq!(svc.session_activation_count(), activations_before);

        assert_eq!(
            restored
                .scavenge_orphaned_bridge_session_scoped_mobs()
                .await,
            vec![mob_id.clone()],
            "a later pass tears the child down"
        );
        assert!(
            restored
                .held_child_mobs()
                .await
                .expect("the held child mobs read")
                .is_empty()
        );
        assert_eq!(mob_store_files(root.path()), 0);
        assert_eq!(svc.session_activation_count(), activations_before);
    }

    /// Park every child teardown of `state` right before its WorkGraph
    /// preflight.
    fn hold_teardown_preflight(state: &MobMcpState) -> Arc<TeardownPreflightHold> {
        let hold = Arc::new(TeardownPreflightHold::default());
        *state
            .teardown_preflight_hold
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(hold.clone());
        hold
    }

    fn release_teardown_preflight(state: &MobMcpState) {
        *state
            .teardown_preflight_hold
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = None;
    }

    /// Drive `future` until its teardown parks at the preflight, then drop
    /// it: the caller is cancelled exactly there.
    async fn cancel_at_teardown_preflight<F: std::future::Future>(
        future: F,
        hold: &TeardownPreflightHold,
    ) {
        let mut future = std::pin::pin!(future);
        let deadline = tokio::time::Instant::now() + Duration::from_secs(10);
        while !hold.reached.load(std::sync::atomic::Ordering::SeqCst) {
            assert!(
                tokio::time::Instant::now() < deadline,
                "the teardown reaches its preflight"
            );
            tokio::select! {
                biased;
                _ = &mut future => panic!("the transfer completed before its preflight"),
                () = tokio::task::yield_now() => {}
            }
        }
    }

