    /// #1701: restoring a child mob asks the host customizer for each member's
    /// rebuild through `customize_resume`, with the member's bound session.
    /// The host restores every member at start (`Eager`), so the rebuild is
    /// part of the restore; under `OnDemand` it comes at the member's first
    /// touch (`a_dormant_child_member_is_customized_with_its_resume_view_at_its_first_touch`).
    #[tokio::test]
    async fn restored_child_mob_members_are_customized_with_their_resume_view() {
        let svc = Arc::new(MockSessionSvc::new());
        let root = tempfile::tempdir().expect("tempdir");
        let (svc, mob_id, session) =
            seat_worker_then_exit(&svc, root.path(), true, "restored-customized-child").await;
        let host = Arc::new(WideningHostCustomizer::default());
        let restored = Arc::new(
            MobMcpState::new(svc.clone(), meerkat_mob::MobControlPrincipal::Owner)
                .expect("runtime custody")
                .with_persistent_storage_root(Some(root.path().to_path_buf()))
                .with_member_restore_policy(meerkat_mob::MemberRestorePolicy::Eager)
                .with_child_spawn_member_customizer(host.clone()),
        );
        let status = restored
            .mob_member_status(&mob_id, &AgentIdentity::from("worker-1"))
            .await
            .expect("restore member status");
        assert_eq!(status.status, meerkat_mob::MobMemberStatus::Active);
        let calls = host.calls();
        assert!(
            calls
                .iter()
                .any(|(mob, source, member, view)| mob == &mob_id
                    && *source == meerkat_mob::SpawnSource::Resume
                    && member.as_str() == "worker-1"
                    && view.as_ref() == Some(&session)),
            "the restore asks the host customizer with the worker's session: {calls:?}"
        );
    }

    /// #1701 under the default restore policy (`OnDemand`): a restored child
    /// mob's member is rebuilt at its first touch, and that rebuild asks the
    /// host customizer through `customize_resume` with the member's bound
    /// session. A status read before it leaves the member Dormant and asks
    /// nothing.
    #[tokio::test]
    async fn a_dormant_child_member_is_customized_with_its_resume_view_at_its_first_touch() {
        let svc = Arc::new(MockSessionSvc::new());
        let root = tempfile::tempdir().expect("tempdir");
        let (svc, mob_id, session) =
            seat_worker_then_exit(&svc, root.path(), true, "first-touch-customized-child").await;
        let host = Arc::new(WideningHostCustomizer::default());
        let restored = Arc::new(
            MobMcpState::new(svc.clone(), meerkat_mob::MobControlPrincipal::Owner)
                .expect("runtime custody")
                .with_persistent_storage_root(Some(root.path().to_path_buf()))
                .with_child_spawn_member_customizer(host.clone()),
        );
        let worker = AgentIdentity::from("worker-1");
        let status = restored
            .mob_member_status(&mob_id, &worker)
            .await
            .expect("restore member status");
        assert_eq!(status.status, meerkat_mob::MobMemberStatus::Active);
        let rebuilt = |calls: &[(
            MobId,
            meerkat_mob::SpawnSource,
            AgentIdentity,
            Option<SessionId>,
        )]| {
            calls.iter().any(|(mob, source, member, view)| {
                mob == &mob_id
                    && *source == meerkat_mob::SpawnSource::Resume
                    && member == &worker
                    && view.as_ref() == Some(&session)
            })
        };
        assert!(
            !rebuilt(&host.calls()),
            "a status read rebuilds no member: {:?}",
            host.calls()
        );
        restored
            .handle_for(&mob_id)
            .await
            .expect("the child mob is restored")
            .ensure_member_live(&worker)
            .await
            .expect("the member's first touch rebuilds it");
        let calls = host.calls();
        assert!(
            rebuilt(&calls),
            "the rebuild asks the host customizer with the worker's session: {calls:?}"
        );
    }

    /// #1701 restore ordering, under the joint child-policy decision: a
    /// restored mob is classified as a child mob before any member is
    /// restored, so its members' rebuilds run under the child policy. A
    /// managed host without a child policy still restores everything: the
    /// child mob comes up, and its members are not brought back unconstrained.
    /// Each carries a typed restore failure saying why and naming the fixes,
    /// and calls into it return that refusal. (Recovery once the refusal
    /// lifts is proved in meerkat-mob:
    /// `refused_restore_is_per_member_and_recovers_once_admitted`.)
    #[tokio::test]
    async fn unconfigured_child_policy_refuses_restored_child_members_not_the_restore() {
        let svc = Arc::new(MockSessionSvc::new());
        let root = tempfile::tempdir().expect("tempdir");
        let worker = AgentIdentity::from("worker-1");
        let seating = Arc::new(
            MobMcpState::new(svc.clone(), meerkat_mob::MobControlPrincipal::Owner)
                .expect("runtime custody")
                .with_persistent_storage_root(Some(root.path().to_path_buf())),
        );
        let owner = SessionId::new();
        svc.insert_persisted_session(Session::with_id(owner.clone()))
            .await;
        let child = seating
            .mob_create_definition_with_owner_bridge_session(
                explicit_definition("restored-policy-child"),
                owner,
                true,
                false,
            )
            .await
            .expect("create child mob");
        let host_mob = seating
            .mob_create_definition(explicit_definition("restored-policy-host"))
            .await
            .expect("create host mob");
        for mob_id in [&child, &host_mob] {
            seating
                .mob_spawn(
                    mob_id,
                    ProfileName::from("worker"),
                    worker.clone(),
                    Some(MobRuntimeMode::TurnDriven),
                    None,
                    None,
                )
                .await
                .expect("spawn worker");
            seating
                .handle_for(mob_id)
                .await
                .expect("predecessor mob handle")
                .shutdown()
                .await
                .expect("retire the predecessor supervisor route");
        }
        let svc = Arc::new(svc.cold_restart().await);

        // The host restores every member at start (`Eager`), so the refusal
        // is the restore's; under `OnDemand` it comes at the member's first
        // touch (`an_unconfigured_child_policy_refuses_a_dormant_child_member_at_its_first_touch`).
        let unconfigured = Arc::new(
            MobMcpState::new(svc.clone(), meerkat_mob::MobControlPrincipal::Owner)
                .expect("runtime custody")
                .with_persistent_storage_root(Some(root.path().to_path_buf()))
                .with_member_restore_policy(meerkat_mob::MemberRestorePolicy::Eager)
                .with_tool_consequence_policy_registry(managed_policy_registry()),
        );
        let mobs = unconfigured
            .mob_list()
            .await
            .expect("the restore completes");
        for mob_id in [&child, &host_mob] {
            assert!(
                mobs.iter().any(|(id, _)| id == mob_id),
                "{mob_id} is restored: {mobs:?}"
            );
        }
        assert_eq!(
            unconfigured
                .mob_member_status(&host_mob, &worker)
                .await
                .expect("host mob member status")
                .status,
            meerkat_mob::MobMemberStatus::Active,
            "the host mob's member restores"
        );
        let refusal = unconfigured
            .handle_for(&child)
            .await
            .expect("the child mob is restored")
            .member(&worker)
            .await
            .map(|_| ())
            .expect_err("the child member is refused");
        let MobError::MemberRestoreFailed { reason, .. } = &refusal else {
            panic!("a typed restore failure, got {refusal:?}");
        };
        for needle in [
            "no child application tool policy is configured",
            "MobMcpState::with_child_application_tool_policy(binding)",
            "child_application_tool_policy",
            "ApplicationToolPolicyBinding::Unmanaged",
        ] {
            assert!(reason.contains(needle), "{needle} missing from: {reason}");
        }
    }

    /// #1701 under the default restore policy (`OnDemand`): a managed host
    /// without a child policy restores the child mob, and the child member's
    /// rebuild is refused at its first touch. The touch and every later call
    /// into the member answer the typed restore failure naming the fixes. (The
    /// refusal at an `Eager` restore is
    /// `unconfigured_child_policy_refuses_restored_child_members_not_the_restore`;
    /// recovery once the refusal lifts is proved in meerkat-mob:
    /// `refused_restore_is_per_member_and_recovers_once_admitted`.)
    #[tokio::test]
    async fn an_unconfigured_child_policy_refuses_a_dormant_child_member_at_its_first_touch() {
        let svc = Arc::new(MockSessionSvc::new());
        let root = tempfile::tempdir().expect("tempdir");
        let worker = AgentIdentity::from("worker-1");
        let seating = Arc::new(
            MobMcpState::new(svc.clone(), meerkat_mob::MobControlPrincipal::Owner)
                .expect("runtime custody")
                .with_persistent_storage_root(Some(root.path().to_path_buf())),
        );
        let owner = SessionId::new();
        svc.insert_persisted_session(Session::with_id(owner.clone()))
            .await;
        let child = seating
            .mob_create_definition_with_owner_bridge_session(
                explicit_definition("first-touch-policy-child"),
                owner,
                true,
                false,
            )
            .await
            .expect("create child mob");
        let host_mob = seating
            .mob_create_definition(explicit_definition("first-touch-policy-host"))
            .await
            .expect("create host mob");
        for mob_id in [&child, &host_mob] {
            seating
                .mob_spawn(
                    mob_id,
                    ProfileName::from("worker"),
                    worker.clone(),
                    Some(MobRuntimeMode::TurnDriven),
                    None,
                    None,
                )
                .await
                .expect("spawn worker");
            seating
                .handle_for(mob_id)
                .await
                .expect("predecessor mob handle")
                .shutdown()
                .await
                .expect("retire the predecessor supervisor route");
        }
        let svc = Arc::new(svc.cold_restart().await);

        let unconfigured = Arc::new(
            MobMcpState::new(svc.clone(), meerkat_mob::MobControlPrincipal::Owner)
                .expect("runtime custody")
                .with_persistent_storage_root(Some(root.path().to_path_buf()))
                .with_tool_consequence_policy_registry(managed_policy_registry()),
        );
        let mobs = unconfigured
            .mob_list()
            .await
            .expect("the restore completes");
        for mob_id in [&child, &host_mob] {
            assert!(
                mobs.iter().any(|(id, _)| id == mob_id),
                "{mob_id} is restored: {mobs:?}"
            );
        }
        assert_eq!(
            unconfigured
                .mob_member_status(&host_mob, &worker)
                .await
                .expect("host mob member status")
                .status,
            meerkat_mob::MobMemberStatus::Active,
            "the host mob's member restores"
        );
        let child_handle = unconfigured
            .handle_for(&child)
            .await
            .expect("the child mob is restored");
        // The member is rebuilt at its first touch, under the child policy.
        let touched = child_handle
            .ensure_member_live(&worker)
            .await
            .expect_err("the child member's rebuild is refused");
        let refusal = child_handle
            .member(&worker)
            .await
            .map(|_| ())
            .expect_err("the child member is refused");
        for error in [&touched, &refusal] {
            let MobError::MemberRestoreFailed { reason, .. } = error else {
                panic!("a typed restore failure, got {error:?}");
            };
            for needle in [
                "no child application tool policy is configured",
                "MobMcpState::with_child_application_tool_policy(binding)",
                "child_application_tool_policy",
                "ApplicationToolPolicyBinding::Unmanaged",
            ] {
                assert!(reason.contains(needle), "{needle} missing from: {reason}");
            }
        }
    }

    /// The in-memory service shared by every mob of one state reports each
    /// live session as belonging only to the mob it was built for, so the
    /// aggregate owner check (owner routing, archive classification) never
    /// reports another mob's member, or a live session no mob built, as
    /// mob-owned on that mob's account.
    #[tokio::test]
    async fn in_memory_sessions_belong_only_to_their_own_mob() {
        let state = MobMcpState::new_in_memory();
        let first = state
            .mob_create_definition(explicit_definition("ownership-first"))
            .await
            .expect("create first mob");
        let second = state
            .mob_create_definition(explicit_definition("ownership-second"))
            .await
            .expect("create second mob");
        let worker = AgentIdentity::from("worker-1");
        for mob_id in [&first, &second] {
            state
                .mob_spawn(
                    mob_id,
                    ProfileName::from("worker"),
                    worker.clone(),
                    Some(MobRuntimeMode::TurnDriven),
                    None,
                    None,
                )
                .await
                .expect("spawn worker");
        }
        let first_session = state
            .mob_resolve_bridge_session_id(&first, &worker)
            .await
            .expect("resolve first session")
            .expect("first worker session");
        let second_session = state
            .mob_resolve_bridge_session_id(&second, &worker)
            .await
            .expect("resolve second session")
            .expect("second worker session");
        let service = state.session_service();
        assert!(service.session_belongs_to_mob(&first_session, &first).await);
        assert!(
            !service
                .session_belongs_to_mob(&first_session, &second)
                .await
        );
        assert!(
            service
                .session_belongs_to_mob(&second_session, &second)
                .await
        );
        assert!(
            !service
                .session_belongs_to_mob(&second_session, &first)
                .await
        );
        assert!(
            !service
                .session_belongs_to_mob(&SessionId::new(), &first)
                .await,
            "an unknown session is no mob's"
        );
        assert!(
            state
                .owns_service_reported_bridge_session(&first_session)
                .await
        );

        // A live session no mob built is not mob-owned, although mobs exist.
        let unbound = Session::new();
        let unbound_id = unbound.id().clone();
        service
            .create_session(CreateSessionRequest {
                injected_context: Vec::new(),
                model: "claude-opus-5".into(),
                prompt: "unbound".into(),
                system_prompt: meerkat_core::SystemPromptOverride::Inherit,
                max_tokens: None,
                event_tx: None,
                build: Some(meerkat_core::service::SessionBuildOptions {
                    resume_session: Some(unbound),
                    ..Default::default()
                }),
                initial_turn: meerkat_core::service::InitialTurnPolicy::Defer,
                deferred_prompt_policy: meerkat_core::service::DeferredPromptPolicy::Discard,
                labels: None,
            })
            .await
            .expect("create a live session no mob built");
        assert!(service.has_live_session(&unbound_id).await.expect("live"));
        assert!(!service.session_belongs_to_mob(&unbound_id, &first).await);
        assert!(
            !state
                .owns_service_reported_bridge_session(&unbound_id)
                .await,
            "a live session no mob built is not reported as mob-owned"
        );
    }

    /// #1701 control: the managed host without a child policy that refuses a
    /// restored child mob's members (above) restores a host-created mob's
    /// members as before: it is never classified as a child mob, so the child
    /// policy does not govern its members' rebuilds. The host restores every
    /// member at start (`Eager`), so the rebuild is the restore's; under
    /// `OnDemand` it comes at the member's first touch
    /// (`a_dormant_host_mob_member_is_rebuilt_once_at_its_first_touch_with_its_seated_binding`).
    #[tokio::test]
    async fn host_mob_restore_is_untouched_by_the_child_policy() {
        let svc = Arc::new(MockSessionSvc::new());
        let root = tempfile::tempdir().expect("tempdir");
        let (svc, mob_id, session) =
            seat_worker_then_exit(&svc, root.path(), false, "restored-host-mob").await;
        let activations_before = svc.session_activation_count();
        let restored = Arc::new(
            MobMcpState::new(svc.clone(), meerkat_mob::MobControlPrincipal::Owner)
                .expect("runtime custody")
                .with_persistent_storage_root(Some(root.path().to_path_buf()))
                .with_member_restore_policy(meerkat_mob::MemberRestorePolicy::Eager)
                .with_tool_consequence_policy_registry(managed_policy_registry()),
        );
        let worker = AgentIdentity::from("worker-1");
        let status = restored
            .mob_member_status(&mob_id, &worker)
            .await
            .expect("the host mob restores");
        assert_eq!(status.status, meerkat_mob::MobMemberStatus::Active);
        assert!(
            svc.session_activation_count() > activations_before,
            "control: the restore rebuilds the member"
        );
        let rebuilt_on = restored
            .mob_resolve_bridge_session_id(&mob_id, &worker)
            .await
            .expect("resolve bridge session")
            .expect("the restored member has a session");
        assert_eq!(
            svc.build_policies_for(&rebuilt_on).last(),
            svc.build_policies_for(&session).last(),
            "the restored member is built with the binding it was seated with"
        );
    }

    /// #1701 control under the default restore policy (`OnDemand`): a
    /// host-created mob is never a child mob, so the child policy does not
    /// govern its member's rebuild. The member's first touch builds it once
    /// more, with the binding it was seated with. This mock serves no
    /// persistent sessions (`supports_persistent_sessions` is false), so the
    /// rebuild creates the member a fresh session, as every restore on such a
    /// service does; only a persistent service resumes the seated one.
    #[tokio::test]
    async fn a_dormant_host_mob_member_is_rebuilt_once_at_its_first_touch_with_its_seated_binding()
    {
        let svc = Arc::new(MockSessionSvc::new());
        let root = tempfile::tempdir().expect("tempdir");
        let (svc, mob_id, session) =
            seat_worker_then_exit(&svc, root.path(), false, "first-touch-host-mob").await;
        let restored = Arc::new(
            MobMcpState::new(svc.clone(), meerkat_mob::MobControlPrincipal::Owner)
                .expect("runtime custody")
                .with_persistent_storage_root(Some(root.path().to_path_buf()))
                .with_tool_consequence_policy_registry(managed_policy_registry()),
        );
        let worker = AgentIdentity::from("worker-1");
        let status = restored
            .mob_member_status(&mob_id, &worker)
            .await
            .expect("the host mob restores");
        assert_eq!(status.status, meerkat_mob::MobMemberStatus::Active);
        let seated = svc.build_policies_for(&session);
        let activations_before = svc.session_activation_count();
        restored
            .handle_for(&mob_id)
            .await
            .expect("the host mob is restored")
            .ensure_member_live(&worker)
            .await
            .expect("the member's first touch rebuilds it");
        assert_eq!(
            svc.session_activation_count(),
            activations_before + 1,
            "the first touch built the member once"
        );
        let rebuilt_on = restored
            .mob_resolve_bridge_session_id(&mob_id, &worker)
            .await
            .expect("resolve bridge session")
            .expect("the restored member has a session");
        assert_eq!(
            svc.build_policies_for(&rebuilt_on).last(),
            seated.last(),
            "the restored member is built with the binding it was seated with"
        );
    }

    #[tokio::test]
    async fn current_session_schedule_survives_member_respawn_and_runtime_restart() {
        use meerkat::surface::SurfaceScheduleMobHost as _;

        let svc = Arc::new(MockSessionSvc::new());
        let root = tempfile::tempdir().expect("tempdir");
        let runtime_root = root.path().join("runtime");
        let schedule_path = root.path().join("schedules.db");
        let identity = AgentIdentity::from("worker-1");
        let mut definition = explicit_definition("scheduled-identity-e2e");
        if let Some(meerkat_mob::ProfileBinding::Inline(profile)) =
            definition.profiles.get_mut(&ProfileName::from("worker"))
        {
            profile.external_addressable = true;
        }

        let state = Arc::new(
            MobMcpState::new(svc.clone(), meerkat_mob::MobControlPrincipal::Owner)
                .expect("construct runtime authority")
                .with_persistent_storage_root(Some(runtime_root.clone())),
        );
        let mob_id = state
            .mob_create_definition(definition)
            .await
            .expect("create persistent mob");
        state
            .mob_spawn(
                &mob_id,
                ProfileName::from("worker"),
                identity.clone(),
                Some(meerkat_mob::MobRuntimeMode::TurnDriven),
                None,
                None,
            )
            .await
            .expect("spawn original worker");
        let original_bridge_session = state
            .mob_resolve_bridge_session_id(&mob_id, &identity)
            .await
            .expect("resolve original bridge session")
            .expect("original bridge session exists");

        let schedule_store = Arc::new(
            meerkat_store::SqliteScheduleStore::open(&schedule_path).expect("open schedule store"),
        );
        let schedule_service = meerkat_schedule::ScheduleService::new(schedule_store.clone());
        let dispatcher = meerkat_schedule::CurrentSessionScheduleToolDispatcher::new_with_resolver(
            Arc::new(meerkat_schedule::ScheduleToolDispatcher::new(
                schedule_service.clone(),
            )),
            original_bridge_session.clone(),
            Arc::new(
                meerkat::surface::MobMemberCurrentSessionScheduleResolver::new(
                    meerkat_core::MobMemberBinding {
                        mob_id: mob_id.to_string(),
                        role: "worker".to_string(),
                        member: identity.to_string(),
                    },
                ),
            ),
        );
        let schedule_args = json!({
            "name": "durable identity schedule",
            "description": "created by an identity-backed member through current_session",
            "trigger": {
                "type": "interval",
                "start_at_utc": chrono::Utc::now(),
                "every_seconds": 60
            },
            "target": {
                "target_kind": "session",
                "type": "current_session",
                "action": {
                    "type": "prompt",
                    "prompt": "scheduled identity survives restart"
                }
            },
            "misfire_policy": { "type": "skip" },
            "overlap_policy": "skip_if_running",
            "missing_target_policy": "mark_misfired",
            "planning_horizon_occurrences": 1
        });
        let raw_schedule_args =
            serde_json::value::RawValue::from_string(schedule_args.to_string()).expect("raw args");
        let created = dispatcher
            .dispatch(ToolCallView {
                id: "schedule-1",
                name: "meerkat_schedule_create",
                args: raw_schedule_args.as_ref(),
            })
            .await
            .expect("schedule create through current_session wrapper");
        let created: serde_json::Value =
            serde_json::from_str(&created.result.text_content()).expect("created schedule json");
        let schedule_id = meerkat_schedule::ScheduleId::parse(
            created["schedule_id"]
                .as_str()
                .expect("created schedule id"),
        )
        .expect("valid schedule id");
        let persisted = schedule_service
            .get(&schedule_id)
            .await
            .expect("load created schedule");
        let meerkat::TargetBinding::Identity(binding) = &persisted.target else {
            panic!("current_session from mob member must persist as identity target");
        };
        assert!(
            !binding
                .identity()
                .contains(&original_bridge_session.to_string()),
            "durable identity must not include the transient bridge session"
        );
        assert!(
            !binding.identity().contains("worker\""),
            "durable identity must not include the old profile/role"
        );

        state
            .mob_respawn(&mob_id, identity.clone(), None)
            .await
            .expect("respawn worker");
        let respawned_bridge_session = state
            .mob_resolve_bridge_session_id(&mob_id, &identity)
            .await
            .expect("resolve respawned bridge session")
            .expect("respawned bridge session exists");
        assert_ne!(
            respawned_bridge_session, original_bridge_session,
            "respawn should regenerate the bridge session"
        );

        let old_handle = state.handle_for(&mob_id).await.expect("old mob handle");
        old_handle
            .crash_stop_preserving_durable_work_for_test()
            .await
            .expect("crash-stop old mob actor before reopening durable storage");
        let closed_error = tokio::time::timeout(Duration::from_secs(1), old_handle.stop())
            .await
            .expect("old actor command channel closes after crash stop")
            .expect_err("crash-stopped actor must reject later commands");
        assert!(matches!(closed_error, MobError::ActorCommandChannelClosed));
        drop(old_handle);
        drop(state);
        // A process restart rebuilds both the surface sidecars and their
        // machine-owned executor attachments. Retain only the mock session
        // facts needed to stand those actors back up; reusing the old machine
        // here would be a warm surface replacement over a live attachment,
        // which correctly requires its original exact sidecar.
        let svc = Arc::new(svc.cold_restart().await);
        let restored_state = Arc::new(
            MobMcpState::new(svc.clone(), meerkat_mob::MobControlPrincipal::Owner)
                .expect("construct runtime authority")
                .with_persistent_storage_root(Some(runtime_root)),
        );
        assert_eq!(
            restored_state
                .mob_status(&mob_id)
                .await
                .expect("restored mob status"),
            MobState::Running,
            "fresh session recreation must restore its generated runtime binding before admission"
        );

        let restored_schedule_store = Arc::new(
            meerkat_store::SqliteScheduleStore::open(&schedule_path)
                .expect("reopen schedule store"),
        );
        let restored_schedule_service =
            meerkat_schedule::ScheduleService::new(restored_schedule_store);
        let restored_schedule = restored_schedule_service
            .get(&schedule_id)
            .await
            .expect("load schedule after restart");
        let occurrence = meerkat_schedule::Occurrence::planned_from_schedule(
            &restored_schedule,
            meerkat_schedule::OccurrenceOrdinal(0),
            chrono::Utc::now(),
        )
        .expect("plan restored occurrence");
        let meerkat::TargetBinding::Identity(restored_binding) = &restored_schedule.target else {
            panic!("restored schedule must keep identity target");
        };
        let host = MobMcpScheduleHost::new(restored_state.clone());
        let probe = host
            .probe_identity_target(restored_binding)
            .await
            .expect("probe restored identity target")
            .expect("mob identity should be handled by mob host");
        assert!(matches!(probe, meerkat::TargetProbeOutcome::Ready));

        let before_turns = svc.start_turn_call_count();
        let delivery_identity = meerkat::ScheduleDeliveryIdentity::for_occurrence(&occurrence);
        let dispatch = host
            .deliver_identity_target(&occurrence, &delivery_identity, restored_binding)
            .await
            .expect("deliver restored identity target")
            .expect("mob identity should deliver through restored mob host");
        let terminal = dispatch.completion.await.expect("delivery completion");
        assert_eq!(
            terminal.phase,
            meerkat::OccurrencePhase::Completed,
            "scheduled identity delivery failed: {terminal:?}"
        );
        assert_eq!(
            dispatch.correlation_id.as_deref(),
            Some(delivery_identity.correlation_id.as_str())
        );
        let delivery_deadline = Instant::now() + Duration::from_secs(2);
        while svc.start_turn_call_count() <= before_turns {
            assert!(
                Instant::now() < delivery_deadline,
                "accepted scheduled delivery should reach the restored member session"
            );
            sleep(Duration::from_millis(10)).await;
        }
        assert_eq!(
            svc.start_turn_call_count(),
            before_turns + 1,
            "scheduled prompt should reach the restored current member session"
        );
        let (delivered_session, delivered_prompt) = svc
            .last_start_turn()
            .await
            .expect("scheduled delivery should start a turn");
        // The member stayed dormant through the restart; the delivery woke it,
        // and its wake recreated the explicitly nonpersistent session.
        let restored_bridge_session = restored_state
            .mob_resolve_bridge_session_id(&mob_id, &identity)
            .await
            .expect("resolve restored bridge session")
            .expect("restored bridge session exists");
        assert_ne!(
            restored_bridge_session, respawned_bridge_session,
            "the explicitly nonpersistent session fixture must rotate its bridge session after a cold restart"
        );
        assert_eq!(
            delivered_session, restored_bridge_session,
            "scheduled prompt must target the restored current materialized session"
        );
        assert_ne!(
            delivered_session, original_bridge_session,
            "scheduled prompt must not target the original transient bridge session"
        );
        assert_eq!(delivered_prompt, "scheduled identity survives restart");
    }

    #[tokio::test]
    async fn test_mob_destroy_removes_persistent_store_file() {
        let svc = Arc::new(LocalSessionService::new());
        assert!(
            !MobSessionService::supports_persistent_sessions(svc.as_ref()),
            "fixture must prove Mob event-log persistence independently of session-body persistence"
        );
        let root = tempfile::tempdir().expect("tempdir");
        let state = Arc::new(
            MobMcpState::new(svc.clone(), meerkat_mob::MobControlPrincipal::Owner)
                .expect("construct runtime authority")
                .with_persistent_storage_root(Some(root.path().to_path_buf())),
        );

        let mob_id = state
            .mob_create_definition(explicit_definition("destroyed-explicit"))
            .await
            .expect("create explicit mob");
        let storage_root = MobMcpState::persistent_mob_root(root.path());
        let storage_path = MobMcpState::persistent_storage_path(&storage_root, &mob_id);
        assert!(
            tokio::fs::metadata(&storage_path).await.is_ok(),
            "persistent mob db should exist after create"
        );

        state.mob_destroy(&mob_id).await.expect("destroy mob");
        assert!(
            tokio::fs::metadata(&storage_path).await.is_err(),
            "destroy should remove persistent mob db"
        );

        let restored = Arc::new(
            MobMcpState::new(svc, meerkat_mob::MobControlPrincipal::Owner)
                .expect("construct runtime authority")
                .with_persistent_storage_root(Some(root.path().to_path_buf())),
        );
        assert!(
            restored
                .mob_list()
                .await
                .expect("list restored mobs")
                .is_empty(),
            "destroyed persistent mobs must not reappear after restart"
        );
    }

    /// [`explicit_definition`] with a second profile, `reviewer`: the
    /// definition the stored-definition rows replace a stored one with.
    fn definition_with_reviewer(mob_id: &str) -> MobDefinition {
        let mut definition = explicit_definition(mob_id);
        let reviewer = definition
            .profiles
            .get(&ProfileName::from("worker"))
            .expect("the worker profile")
            .clone();
        definition
            .profiles
            .insert(ProfileName::from("reviewer"), reviewer);
        definition
    }

    /// A restart over `root` with the mob `mob_id` stored: created through a
    /// state over the root, its actor shut down, the state dropped.
    async fn a_stored_mob_before_a_restart(
        svc: &Arc<MockSessionSvc>,
        root: &std::path::Path,
        mob_id: &str,
    ) -> MobId {
        let state = restored_state(svc, root);
        let mob_id = state
            .mob_create_definition(explicit_definition(mob_id))
            .await
            .expect("create the stored mob");
        state
            .handle_for(&mob_id)
            .await
            .expect("predecessor mob handle")
            .shutdown()
            .await
            .expect("retire the predecessor supervisor route");
        mob_id
    }

    /// The store of `mob_id` under the persistent root `root`.
    fn stored_mob_path(root: &std::path::Path, mob_id: &MobId) -> PathBuf {
        MobMcpState::persistent_storage_path(&MobMcpState::persistent_mob_root(root), mob_id)
    }

    /// The definition the store of `mob_id` under `root` holds, and its
    /// epoch, read from the store itself.
    async fn stored_definition(root: &std::path::Path, mob_id: &MobId) -> (MobDefinition, u64) {
        let snapshot = MobStorage::persistent(stored_mob_path(root, mob_id))
            .expect("open the mob store")
            .created_definition_snapshot()
            .await
            .expect("read the stored definition")
            .expect("the store holds a definition");
        (snapshot.definition().clone(), snapshot.epoch())
    }

    /// Whether `state` has run its restore scan: the hosted set's word,
    /// read under the lock a pass runs under.
    async fn restore_has_run(state: &MobMcpState) -> bool {
        let _one_pass = state.restore_lock.lock().await;
        state.hosted.pass_finished()
    }

    /// What the storage itself answers to a definition update of a store
    /// that has a live handle in the process: it commits the next epoch. The
    /// running mob keeps the definition it started with, so the store is one
    /// epoch ahead of its own live mob until the next resume. The storage
    /// call is for a mob whose process is down; a state that manages the mob
    /// has to refuse the update itself.
    #[tokio::test]
    async fn the_storage_commits_a_definition_update_under_a_live_handle_of_the_same_store() {
        let svc = Arc::new(MockSessionSvc::new());
        let root = tempfile::tempdir().expect("tempdir");
        let state = restored_state(&svc, root.path());
        let mob_id = state
            .mob_create_definition(explicit_definition("live-store"))
            .await
            .expect("create the managed mob");
        let updated = definition_with_reviewer("live-store");

        let answer = MobStorage::persistent(stored_mob_path(root.path(), &mob_id))
            .expect("open the managed mob's store")
            .update_definition(1, updated.clone())
            .await;

        let revision = answer.expect("the storage does not see the live handle");
        assert_eq!((revision.epoch, revision.projection_revision), (2, 2));
        let live = state.handle_for(&mob_id).await.expect("the managed mob");
        assert_eq!(
            live.definition(),
            &explicit_definition("live-store"),
            "the running mob keeps the definition it started with"
        );
        assert_eq!(
            stored_definition(root.path(), &mob_id).await,
            (updated, 2),
            "its store is one epoch ahead of it"
        );
    }

    /// A host replaces the stored definition of a cold mob through the
    /// state: the state resumes nothing for it, and the first mob verb then
    /// resumes the mob with the new definition at the advanced epoch.
    #[tokio::test]
    async fn a_cold_stored_definition_update_is_what_the_first_mob_verb_resumes() {
        let svc = Arc::new(MockSessionSvc::new());
        let root = tempfile::tempdir().expect("tempdir");
        let mob_id = a_stored_mob_before_a_restart(&svc, root.path(), "cold-replace").await;
        let updated = definition_with_reviewer("cold-replace");

        let state = restored_state(&svc, root.path());
        let revision = state
            .mob_update_stored_definition(&mob_id, 1, updated.clone())
            .await
            .expect("the cold mob's stored definition is replaced");
        assert_eq!((revision.epoch, revision.projection_revision), (2, 2));
        assert!(
            state.hosted.read().await.loaded_handles().next().is_none(),
            "the update resumes nothing"
        );

        let resumed = state
            .handle_for(&mob_id)
            .await
            .expect("the first mob verb resumes the mob");
        assert_eq!(
            resumed.definition(),
            &updated,
            "the mob resumes with the new definition"
        );
        state
            .mob_spawn(
                &mob_id,
                ProfileName::from("reviewer"),
                AgentIdentity::from("reviewer-1"),
                Some(MobRuntimeMode::TurnDriven),
                None,
                None,
            )
            .await
            .expect("the resumed mob seats a member of the added profile");
        assert_eq!(
            stored_definition(root.path(), &mob_id).await,
            (updated, 2),
            "the store holds the new definition at the advanced epoch"
        );
        let health = MobStorage::persistent(stored_mob_path(root.path(), &mob_id))
            .expect("open the mob store")
            .definition_projection_health()
            .await
            .expect("read the projection health");
        assert!(
            matches!(
                health,
                Some(meerkat_mob::MobDefinitionProjectionHealth::Healthy {
                    authority_epoch: 2,
                    projection_revision: 2,
                })
            ),
            "{health:?}"
        );
    }

    /// The update opens the one store it names and starts no restore scan:
    /// a second store beside it, whose bytes are not a database, is neither
    /// read nor quarantined, and the first mob verb still runs the restore.
    #[tokio::test]
    async fn a_cold_stored_definition_update_starts_no_restore_scan() {
        let svc = Arc::new(MockSessionSvc::new());
        let root = tempfile::tempdir().expect("tempdir");
        let mob_id = a_stored_mob_before_a_restart(&svc, root.path(), "no-scan").await;
        let broken_store = MobMcpState::persistent_mob_root(root.path())
            .join(format!("{}broken.db", MobMcpState::MOB_STORE_FILE_PREFIX));
        tokio::fs::write(&broken_store, b"not a sqlite database")
            .await
            .expect("write an undecodable mob store");

        let state = restored_state(&svc, root.path());
        state
            .mob_update_stored_definition(&mob_id, 1, definition_with_reviewer("no-scan"))
            .await
            .expect("the cold mob's stored definition is replaced");

        assert!(
            !restore_has_run(&state).await,
            "the update does not run the restore"
        );
        assert!(
            !state.hosted.census_complete(),
            "the managed set is not declared restored"
        );
        assert!(
            state.hosted.read().await.loaded_handles().next().is_none(),
            "the update resumes nothing"
        );
        assert!(
            state
                .hosted
                .read()
                .await
                .quarantined_stores()
                .next()
                .is_none(),
            "the store beside it is not reported"
        );
        assert_eq!(
            tokio::fs::read(&broken_store)
                .await
                .expect("read the store beside it"),
            b"not a sqlite database",
            "the store beside it is kept as found"
        );

        let listed = state.mob_list().await.expect("the first mob verb restores");
        assert!(
            listed.iter().any(|(listed, _)| listed == &mob_id),
            "the updated mob is restored: {listed:?}"
        );
        assert_eq!(
            state.hosted.read().await.quarantined_stores().count(),
            1,
            "the restore finds the undecodable store"
        );
    }

    /// A mob this state manages is refused, typed, and nothing is written:
    /// a mob it created, a mob it restored, and a mob of a state without a
    /// persistent root.
    #[tokio::test]
    async fn a_managed_mob_refuses_a_stored_definition_update() {
        let svc = Arc::new(MockSessionSvc::new());
        let root = tempfile::tempdir().expect("tempdir");
        let state = restored_state(&svc, root.path());
        let mob_id = state
            .mob_create_definition(explicit_definition("managed"))
            .await
            .expect("create the managed mob");

        let created = state
            .mob_update_stored_definition(&mob_id, 1, definition_with_reviewer("managed"))
            .await
            .expect_err("a mob this state created is managed");
        assert!(
            matches!(
                &created,
                MobStoredDefinitionError::Managed { mob_id: refused } if refused == &mob_id
            ),
            "{created:?}"
        );
        assert_eq!(
            stored_definition(root.path(), &mob_id).await,
            (explicit_definition("managed"), 1),
            "nothing is written"
        );

        state
            .handle_for(&mob_id)
            .await
            .expect("predecessor mob handle")
            .shutdown()
            .await
            .expect("retire the predecessor supervisor route");
        drop(state);
        let restarted = restored_state(&svc, root.path());
        restarted.mob_list().await.expect("restore the mob");
        let restored = restarted
            .mob_update_stored_definition(&mob_id, 1, definition_with_reviewer("managed"))
            .await
            .expect_err("a mob this state restored is managed");
        assert!(
            matches!(
                &restored,
                MobStoredDefinitionError::Managed { mob_id: refused } if refused == &mob_id
            ),
            "{restored:?}"
        );
        assert_eq!(
            stored_definition(root.path(), &mob_id).await,
            (explicit_definition("managed"), 1),
            "nothing is written"
        );

        let rootless = MobMcpState::new_in_memory();
        let in_memory = rootless
            .mob_create_definition(explicit_definition("managed-in-memory"))
            .await
            .expect("create a mob without a persistent root");
        let refused = rootless
            .mob_update_stored_definition(
                &in_memory,
                1,
                definition_with_reviewer("managed-in-memory"),
            )
            .await
            .expect_err("a managed mob of a state without a root is managed");
        assert!(
            matches!(
                &refused,
                MobStoredDefinitionError::Managed { mob_id: refused } if refused == &in_memory
            ),
            "{refused:?}"
        );
    }

    /// A wrong expected revision answers the storage's own compare-and-swap
    /// refusal, and nothing is written.
    #[tokio::test]
    async fn a_cold_stored_definition_update_at_a_wrong_revision_answers_the_storage_conflict() {
        let svc = Arc::new(MockSessionSvc::new());
        let root = tempfile::tempdir().expect("tempdir");
        let mob_id = a_stored_mob_before_a_restart(&svc, root.path(), "wrong-revision").await;
        let updated = definition_with_reviewer("wrong-revision");
        let storage_answer = MobStorage::persistent(stored_mob_path(root.path(), &mob_id))
            .expect("open the mob store")
            .update_definition(7, updated.clone())
            .await
            .expect_err("the storage refuses a wrong expected revision");

        let state = restored_state(&svc, root.path());
        let refused = state
            .mob_update_stored_definition(&mob_id, 7, updated)
            .await
            .expect_err("a wrong expected revision is refused");
        assert!(
            matches!(
                &refused,
                MobStoredDefinitionError::Mob(MobError::SpecRevisionConflict {
                    mob_id: conflicted,
                    expected: Some(7),
                    actual: 1,
                }) if conflicted == &mob_id
            ),
            "{refused:?}"
        );
        assert_eq!(refused.to_string(), storage_answer.to_string());
        assert_eq!(
            stored_definition(root.path(), &mob_id).await,
            (explicit_definition("wrong-revision"), 1),
            "nothing is written"
        );
    }

    /// An exact retry answers as the storage does: the revision the first
    /// call committed, and no second epoch. Another definition at the same
    /// expected revision then meets the compare-and-swap refusal.
    #[tokio::test]
    async fn a_cold_stored_definition_update_retried_exactly_answers_the_committed_revision() {
        let svc = Arc::new(MockSessionSvc::new());
        let root = tempfile::tempdir().expect("tempdir");
        let mob_id = a_stored_mob_before_a_restart(&svc, root.path(), "exact-retry").await;
        let updated = definition_with_reviewer("exact-retry");

        let state = restored_state(&svc, root.path());
        let first = state
            .mob_update_stored_definition(&mob_id, 1, updated.clone())
            .await
            .expect("the first update commits");
        let retried = state
            .mob_update_stored_definition(&mob_id, 1, updated.clone())
            .await
            .expect("the exact retry answers the committed revision");
        assert_eq!(retried, first);
        assert_eq!(first.epoch, 2);
        assert_eq!(
            stored_definition(root.path(), &mob_id).await,
            (updated, 2),
            "the retry commits no second epoch"
        );

        let other = state
            .mob_update_stored_definition(&mob_id, 1, explicit_definition("exact-retry"))
            .await
            .expect_err("another definition at the same expected revision is refused");
        assert!(
            matches!(
                &other,
                MobStoredDefinitionError::Mob(MobError::SpecRevisionConflict {
                    expected: Some(1),
                    actual: 2,
                    ..
                })
            ),
            "{other:?}"
        );
    }

    /// A mob id this state has no store for answers `MobNotFound`, and no
    /// store is made for it: a state without a persistent root, an unknown
    /// id under a root, and a definition that names another mob than the id
    /// the call addresses (whose store is left alone).
    #[tokio::test]
    async fn a_stored_definition_update_without_a_store_of_the_mob_answers_mob_not_found() {
        let unknown = MobId::from("unknown");
        let rootless = MobMcpState::new_in_memory();
        let no_root = rootless
            .mob_update_stored_definition(&unknown, 1, explicit_definition("unknown"))
            .await
            .expect_err("a state without a persistent root stores no mob");
        assert!(
            matches!(
                &no_root,
                MobStoredDefinitionError::Mob(MobError::MobNotFound(missing))
                    if missing == &unknown
            ),
            "{no_root:?}"
        );

        let svc = Arc::new(MockSessionSvc::new());
        let root = tempfile::tempdir().expect("tempdir");
        let state = restored_state(&svc, root.path());
        let no_store = state
            .mob_update_stored_definition(&unknown, 1, explicit_definition("unknown"))
            .await
            .expect_err("the root holds no store of the mob");
        assert!(
            matches!(
                &no_store,
                MobStoredDefinitionError::Mob(MobError::MobNotFound(missing))
                    if missing == &unknown
            ),
            "{no_store:?}"
        );
        assert_eq!(mob_store_files(root.path()), 0, "no store is made for it");
        assert!(!restore_has_run(&state).await);
        drop(state);

        // A store under the id `update-moved-b` that holds the mob `update-moved-a`.
        let moved_a = a_stored_mob_before_a_restart(&svc, root.path(), "update-moved-a").await;
        let moved_b = MobId::from("update-moved-b");
        let from = MobMcpState::storage_file_paths(&stored_mob_path(root.path(), &moved_a));
        let to = MobMcpState::storage_file_paths(&stored_mob_path(root.path(), &moved_b));
        for (from, to) in from.iter().zip(&to) {
            if tokio::fs::try_exists(from)
                .await
                .expect("look for the file")
            {
                tokio::fs::rename(from, to).await.expect("move the store");
            }
        }
        let state = restored_state(&svc, root.path());
        let other_mob = state
            .mob_update_stored_definition(&moved_b, 1, definition_with_reviewer("update-moved-a"))
            .await
            .expect_err("the definition names another mob than the call addresses");
        assert!(
            matches!(
                &other_mob,
                MobStoredDefinitionError::Mob(MobError::MobNotFound(missing))
                    if missing == &moved_a
            ),
            "{other_mob:?}"
        );
        let held = MobStorage::persistent(&to[0])
            .expect("open the moved store")
            .created_definition_snapshot()
            .await
            .expect("read the moved store")
            .expect("the moved store holds a definition");
        assert_eq!(
            (held.definition(), held.epoch()),
            (&explicit_definition("update-moved-a"), 1),
            "the store under the addressed id is left alone"
        );
    }

    /// A store the restore keeps quarantined answers the typed quarantine,
    /// and is kept as found. Before the restore has run the state knows no
    /// quarantine: the same store answers the storage's own failure.
    #[tokio::test]
    async fn a_quarantined_store_refuses_a_stored_definition_update_with_its_quarantine() {
        let svc = Arc::new(MockSessionSvc::new());
        let root = tempfile::tempdir().expect("tempdir");
        a_stored_mob_before_a_restart(&svc, root.path(), "beside-quarantined").await;
        let broken = MobId::from("broken");
        let broken_store = stored_mob_path(root.path(), &broken);
        tokio::fs::write(&broken_store, b"not a sqlite database")
            .await
            .expect("write an undecodable mob store");

        let state = restored_state(&svc, root.path());
        let cold = state
            .mob_update_stored_definition(&broken, 1, explicit_definition("broken"))
            .await
            .expect_err("an undecodable store cannot be updated");
        match &cold {
            MobStoredDefinitionError::Mob(error) => assert_ne!(
                quarantine_data(error)["kind"],
                MOB_QUARANTINED_KIND,
                "before the restore the answer is the storage's own: {error:?}"
            ),
            other => panic!("expected the storage's failure, got {other:?}"),
        }
        assert!(!restore_has_run(&state).await);

        state.mob_list().await.expect("the restore runs");
        let quarantined = state
            .mob_update_stored_definition(&broken, 1, explicit_definition("broken"))
            .await
            .expect_err("a quarantined store is not updated");
        match &quarantined {
            MobStoredDefinitionError::Mob(error) => {
                let data = quarantine_data(error);
                assert_eq!(data["kind"], MOB_QUARANTINED_KIND, "{error:?}");
                assert_eq!(data["mob_id"], "broken", "{error:?}");
                assert_eq!(data["class"], "store_unreadable", "{error:?}");
            }
            other => panic!("expected the typed quarantine, got {other:?}"),
        }
        assert_eq!(
            tokio::fs::read(&broken_store)
                .await
                .expect("read the quarantined store"),
            b"not a sqlite database",
            "the quarantined store is kept as found"
        );
    }

    /// A restored child mob held before activation answers its hold, and its
    /// store is kept as recovered.
    #[tokio::test]
    async fn a_held_child_mob_refuses_a_stored_definition_update_with_its_hold() {
        let svc = Arc::new(MockSessionSvc::new());
        let root = tempfile::tempdir().expect("tempdir");
        let (svc, mob_id, owner, _worker_session) =
            seat_child_worker_then_exit(&svc, root.path(), "held-child").await;
        svc.script_observation(
            &owner,
            Ok(meerkat_mob::LiveDurableSourceObservation::Absent),
        );
        let state = restored_state(&svc, root.path());
        assert_held_before_activation(state.handle_for(&mob_id).await, "owner_absent");
        let (stored, epoch) = stored_definition(root.path(), &mob_id).await;
        let mut updated = stored.clone();
        let reviewer = updated
            .profiles
            .get(&ProfileName::from("worker"))
            .expect("the worker profile")
            .clone();
        updated
            .profiles
            .insert(ProfileName::from("reviewer"), reviewer);

        let refused = state
            .mob_update_stored_definition(&mob_id, epoch, updated)
            .await
            .expect_err("a held child mob is not updated");
        match &refused {
            MobStoredDefinitionError::Mob(error) => {
                assert!(error.is_held_before_activation(), "{error:?}");
            }
            other => panic!("expected the hold, got {other:?}"),
        }
        assert_eq!(
            stored_definition(root.path(), &mob_id).await,
            (stored, epoch),
            "the held child's store is kept as recovered"
        );
    }

