    #[tokio::test]
    async fn test_archive_session_with_mob_cleanup_surfaces_incomplete_and_retries_success() {
        let svc = Arc::new(MockSessionSvc::new());
        let state = Arc::new(
            MobMcpState::new(svc.clone(), meerkat_mob::MobControlPrincipal::Owner)
                .expect("construct runtime authority"),
        );
        let owner_session_id = SessionId::new();
        svc.insert_persisted_session(Session::with_id(owner_session_id.clone()))
            .await;

        let definition = explicit_definition("archive-helper-partial-destroy");
        let mob_id = state
            .mob_create_definition_with_owner_bridge_session(
                definition,
                owner_session_id.clone(),
                true,
                false,
            )
            .await
            .expect("create archive-helper-owned mob");
        state
            .mob_spawn(
                &mob_id,
                ProfileName::from("worker"),
                AgentIdentity::from("worker-1"),
                Some(meerkat_mob::MobRuntimeMode::TurnDriven),
                None,
                None,
            )
            .await
            .expect("spawn worker");
        let bridge_session_id = state
            .handle_for(&mob_id)
            .await
            .expect("mob handle")
            .resolve_bridge_session_id(&AgentIdentity::from("worker-1"))
            .await
            .expect("worker bridge session");
        svc.fail_archive(
            bridge_session_id.clone(),
            "forced archive-helper cleanup archive failure",
        )
        .await;

        let err = crate::agent_tools::archive_session_with_mob_cleanup(
            svc.clone(),
            state.clone(),
            &owner_session_id,
        )
        .await
        .expect_err("archive helper must fail closed on incomplete mob cleanup");
        let SessionError::FailedWithData { data, .. } = err else {
            panic!("expected typed incomplete session error, got {err:?}");
        };
        assert_eq!(
            data.get("code").and_then(serde_json::Value::as_str),
            Some("mob_destroy_incomplete")
        );
        assert_eq!(
            data.get("retryable").and_then(serde_json::Value::as_bool),
            Some(true)
        );
        assert!(
            state.handle_for(&mob_id).await.is_ok(),
            "incomplete archive helper cleanup must retain the mob retry anchor"
        );
        assert!(
            !svc.session_exists(&owner_session_id).await,
            "first archive attempt should have removed the owner session before mob cleanup failed"
        );
        assert!(
            svc.session_exists(&bridge_session_id).await,
            "failed member archive must retain the bridge session for retry"
        );

        svc.clear_archive_failure(&bridge_session_id).await;
        crate::agent_tools::archive_session_with_mob_cleanup(
            svc.clone(),
            state.clone(),
            &owner_session_id,
        )
        .await
        .expect("retry should report success after retained mob cleanup completes");
        assert!(
            state.handle_for(&mob_id).await.is_err(),
            "successful archive helper retry should remove the mob retry anchor"
        );
        assert!(
            !svc.session_exists(&bridge_session_id).await,
            "successful archive helper retry must archive the worker bridge session"
        );
    }

    /// Archiving a member's session retries the member's retirement. A
    /// retirement the first attempt left stuck is re-driven once per archive
    /// request; while its cause still fails, the archive surfaces the typed
    /// stuck retirement with that cause (never masked, never looped), and once
    /// the cause clears the next archive completes it.
    #[tokio::test]
    async fn test_archive_of_a_member_session_redrives_its_stuck_retirement_and_surfaces_a_still_failing_cause()
     {
        let svc = Arc::new(MockSessionSvc::new());
        let state = Arc::new(
            MobMcpState::new(svc.clone(), meerkat_mob::MobControlPrincipal::Owner)
                .expect("construct runtime authority"),
        );
        let mob_id = state
            .mob_create_definition(explicit_definition("archive-redrive"))
            .await
            .expect("create mob");
        state
            .mob_spawn(
                &mob_id,
                ProfileName::from("worker"),
                AgentIdentity::from("worker-1"),
                Some(meerkat_mob::MobRuntimeMode::TurnDriven),
                None,
                None,
            )
            .await
            .expect("spawn worker");
        let bridge_session_id = state
            .handle_for(&mob_id)
            .await
            .expect("mob handle")
            .resolve_bridge_session_id(&AgentIdentity::from("worker-1"))
            .await
            .expect("worker bridge session");
        svc.fail_archive(bridge_session_id.clone(), "forced member archive failure")
            .await;

        let first = crate::agent_tools::archive_session_with_mob_cleanup(
            svc.clone(),
            state.clone(),
            &bridge_session_id,
        )
        .await
        .expect_err("the member archive fails");
        assert!(
            first.to_string().contains("forced member archive failure"),
            "the first archive surfaces the failure: {first}"
        );

        // The cause still fails: the archive re-drives the stuck retirement
        // once and surfaces it, typed, with its cause.
        let still_failing = crate::agent_tools::archive_session_with_mob_cleanup(
            svc.clone(),
            state.clone(),
            &bridge_session_id,
        )
        .await
        .expect_err("a re-driven retirement whose cause still fails surfaces it");
        let text = still_failing.to_string();
        assert!(
            text.contains("is stuck at") && text.contains("forced member archive failure"),
            "the archive surfaces the stuck retirement and its cause: {text}"
        );
        assert!(
            svc.session_exists(&bridge_session_id).await,
            "a failed re-drive keeps the member session for the next retry"
        );

        svc.clear_archive_failure(&bridge_session_id).await;
        crate::agent_tools::archive_session_with_mob_cleanup(
            svc.clone(),
            state.clone(),
            &bridge_session_id,
        )
        .await
        .expect("the archive re-drives the stuck retirement to completion");
        assert!(
            !svc.session_exists(&bridge_session_id).await,
            "the re-driven retirement archives the member session"
        );
    }

    /// Archiving a member's session while the member's FreshSession rotation
    /// is held for its host leaves the rotation held, as a retire by any
    /// caller other than the host does. The member is host-pending (its host
    /// keeps its own record of the rotation and re-issues it): the rotation's
    /// archive failed, the mob restarted with the member marked host-pending,
    /// and the start held the rotation for the host. The archive answers the
    /// stuck retirement, typed, with the cause that names the host's wait.
    /// Nothing is re-driven: the member keeps its retiring generation and its
    /// session, and the host's re-issue then finishes the rotation once.
    ///
    /// RED: let the archive re-drive a held rotation (drop the
    /// `rotation_held_for_host` check in `retire_member_by_bridge_session_id`):
    /// the archive finishes the rotation onto its next session and answers
    /// success, and the host's re-issue rotates the member a second time.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn test_archive_of_a_member_session_leaves_a_rotation_held_for_its_host() {
        const STEP: Duration = Duration::from_secs(10);
        let identity = AgentIdentity::from("worker-1");
        let spec = || {
            SpawnMemberSpec::new("worker", identity.clone())
                .with_runtime_mode(MobRuntimeMode::TurnDriven)
        };
        let svc = Arc::new(MockSessionSvc::new());
        let storage = MobStorage::in_memory();
        let first = tokio::time::timeout(
            STEP,
            MobBuilder::new(
                explicit_definition("archive-held-rotation"),
                storage.clone(),
            )
            .with_session_service(svc.clone())
            .allow_ephemeral_sessions(true)
            .with_network_member_comms()
            .create(),
        )
        .await
        .expect("the create answers")
        .expect("create the mob");
        tokio::time::timeout(STEP, first.spawn_spec(spec()))
            .await
            .expect("the spawn answers")
            .expect("spawn the member");
        let old_session = first
            .resolve_bridge_session_id(&identity)
            .await
            .expect("the member's session");
        // The rotation's retirement durably starts and its archive fails:
        // the rotation stands, stuck, and the member stays Retiring.
        svc.fail_archive(old_session.clone(), "forced member archive failure")
            .await;
        tokio::time::timeout(STEP, first.rotate_member(spec()))
            .await
            .expect("the rotation answers")
            .expect_err("the rotation's archive fails");
        tokio::time::timeout(STEP, first.shutdown())
            .await
            .expect("the shutdown answers")
            .expect("retire the predecessor supervisor route");
        drop(first);
        svc.clear_archive_failure(&old_session).await;
        let restarted = Arc::new(svc.cold_restart().await);
        let resumed = tokio::time::timeout(
            STEP,
            Box::pin(
                MobBuilder::for_resume(storage)
                    .with_session_service(restarted.clone())
                    .allow_ephemeral_sessions(true)
                    .with_network_member_comms()
                    .with_host_pending_members([identity.clone()])
                    .notify_orchestrator_on_resume(false)
                    .resume(),
            ),
        )
        .await
        .expect("the restart answers")
        .expect("the restart succeeds");
        assert!(
            resumed
                .rotation_held_for_host(&identity)
                .expect("read the published machine state"),
            "the start holds the host-pending member's rotation for its host"
        );
        let state = Arc::new(
            MobMcpState::new(restarted.clone(), MobControlPrincipal::Owner)
                .expect("construct runtime authority"),
        );
        state
            .mob_insert_handle(resumed.mob_id().clone(), resumed.clone())
            .await;

        // The archive's retire answers the held rotation's stuck retirement,
        // typed, naming the host's wait.
        let refused =
            tokio::time::timeout(STEP, state.retire_member_by_bridge_session_id(&old_session))
                .await
                .expect("the retire answers")
                .expect_err("the archive leaves the held rotation to its host");
        match &refused {
            MobError::MemberRetirementStuck {
                member_id, cause, ..
            } => {
                assert_eq!(member_id, &identity);
                assert!(
                    matches!(
                        cause.as_ref(),
                        MobError::LifecycleOperationPending { intent }
                            if intent.contains("rotate_member")
                    ),
                    "the stuck retirement names the host's wait: {cause}"
                );
            }
            other => panic!("expected the held rotation's stuck retirement, got {other:?}"),
        }
        // The session archive surface answers the same, and keeps the
        // session.
        let surfaced = tokio::time::timeout(
            STEP,
            crate::agent_tools::archive_session_with_mob_cleanup(
                restarted.clone(),
                Arc::clone(&state),
                &old_session,
            ),
        )
        .await
        .expect("the archive answers")
        .expect_err("the session archive leaves the held rotation to its host");
        let text = surfaced.to_string();
        assert!(
            text.contains("is stuck at") && text.contains("rotate_member"),
            "the archive surfaces the held rotation's stuck retirement: {text}"
        );

        // Nothing re-drove the rotation: it stays held, and the member keeps
        // its retiring generation and its session.
        assert!(
            resumed
                .rotation_held_for_host(&identity)
                .expect("read the published machine state"),
            "the archive leaves the rotation held for its host"
        );
        assert_eq!(
            resumed
                .get_member(&identity)
                .await
                .expect("roster read")
                .map(|entry| entry.generation),
            Some(meerkat_mob::Generation::INITIAL)
        );
        assert!(
            restarted.session_exists(&old_session).await,
            "the held rotation keeps the member's session"
        );

        // The host's re-issue finishes the rotation, once.
        let next_session = tokio::time::timeout(STEP, resumed.rotate_member(spec()))
            .await
            .expect("the re-issue answers")
            .expect("the host's re-issue finishes the held rotation");
        assert_ne!(next_session, old_session);
        assert_eq!(
            resumed
                .get_member(&identity)
                .await
                .expect("roster read")
                .map(|entry| entry.generation),
            Some(meerkat_mob::Generation::new(1))
        );
        assert_eq!(
            resumed.resolve_bridge_session_id(&identity).await,
            Some(next_session)
        );
        assert!(
            !resumed
                .rotation_held_for_host(&identity)
                .expect("read the published machine state"),
            "the host's own rotation ends the hold"
        );
        assert!(
            !restarted.session_exists(&old_session).await,
            "the finished rotation archives the retired incarnation's session"
        );
        // The host's mob stays inserted in the state until here.
        drop(state);
    }

    /// A principal granted Retire but not List archives a member's session
    /// whose retirement is stuck for an ordinary cause, and once the cause
    /// clears its archive re-drives the retirement to completion. The
    /// archive re-drives as a caller other than the host: the actor decides
    /// a host's hold in the re-drive's own step, under the Retire scope the
    /// archive holds, so the archive reads nothing that needs the List scope.
    ///
    /// RED: read the hold through `MobHandle::rotation_held_for_host` (the
    /// List scope) before the re-drive: the archive fails `ScopeDenied`
    /// (List), and the stuck retirement is never re-driven.
    #[tokio::test]
    async fn test_archive_by_a_retire_only_principal_redrives_an_ordinary_stuck_retirement() {
        let svc = Arc::new(MockSessionSvc::new());
        let owner = Arc::new(
            MobMcpState::new(svc.clone(), MobControlPrincipal::Owner)
                .expect("construct runtime authority"),
        );
        let mob_id = owner
            .mob_create_definition(explicit_definition("archive-retire-only"))
            .await
            .expect("create mob");
        let worker = AgentIdentity::from("worker-1");
        owner
            .mob_spawn(
                &mob_id,
                ProfileName::from("worker"),
                worker.clone(),
                Some(MobRuntimeMode::TurnDriven),
                None,
                None,
            )
            .await
            .expect("spawn worker");
        let bridge_session_id = owner
            .handle_for(&mob_id)
            .await
            .expect("mob handle")
            .resolve_bridge_session_id(&worker)
            .await
            .expect("worker bridge session");
        let principal =
            meerkat_core::auth::PrincipalId::new("archive-retire-only").expect("principal");
        owner
            .mob_grant_scopes(
                &mob_id,
                principal.clone(),
                BTreeSet::from([ControlScope::Retire]),
                None,
            )
            .await
            .expect("grant Retire only");
        let retirer = Arc::new(
            MobMcpState::new(svc.clone(), MobControlPrincipal::External(principal))
                .expect("construct runtime authority"),
        );
        retirer
            .mob_insert_handle(
                mob_id.clone(),
                owner.handle_for(&mob_id).await.expect("owner handle"),
            )
            .await;

        // The first archive's retirement is stuck on the archive failure.
        svc.fail_archive(bridge_session_id.clone(), "forced member archive failure")
            .await;
        let first = crate::agent_tools::archive_session_with_mob_cleanup(
            svc.clone(),
            Arc::clone(&retirer),
            &bridge_session_id,
        )
        .await
        .expect_err("the member archive fails");
        assert!(
            first.to_string().contains("forced member archive failure"),
            "the first archive surfaces the failure: {first}"
        );

        // Once the cause clears, the Retire-only principal's archive
        // re-drives the stuck retirement to completion.
        svc.clear_archive_failure(&bridge_session_id).await;
        crate::agent_tools::archive_session_with_mob_cleanup(
            svc.clone(),
            Arc::clone(&retirer),
            &bridge_session_id,
        )
        .await
        .expect("the archive re-drives the stuck retirement without the List scope");
        assert!(
            !svc.session_exists(&bridge_session_id).await,
            "the re-driven retirement archives the member session"
        );
        assert!(
            owner
                .handle_for(&mob_id)
                .await
                .expect("mob handle")
                .get_member(&worker)
                .await
                .expect("roster read")
                .is_none(),
            "the member is retired"
        );
        drop(retirer);
    }

    #[tokio::test]
    async fn test_archive_session_with_mob_cleanup_runs_member_retire_then_child_cleanup() {
        let svc = Arc::new(MockSessionSvc::new());
        let state = Arc::new(
            MobMcpState::new(svc.clone(), meerkat_mob::MobControlPrincipal::Owner)
                .expect("construct runtime authority"),
        );
        let parent_mob_id = state
            .mob_create_definition(explicit_definition("archive-helper-live-parent"))
            .await
            .expect("create parent mob");
        let parent_identity = AgentIdentity::from("worker-1");
        state
            .mob_spawn(
                &parent_mob_id,
                ProfileName::from("worker"),
                parent_identity.clone(),
                Some(meerkat_mob::MobRuntimeMode::TurnDriven),
                None,
                None,
            )
            .await
            .expect("spawn parent worker");
        let member_session_id = state
            .handle_for(&parent_mob_id)
            .await
            .expect("parent mob handle")
            .resolve_bridge_session_id(&parent_identity)
            .await
            .expect("parent member bridge session");

        let child_definition = explicit_definition("archive-helper-live-member-child");
        let child_mob_id = state
            .mob_create_definition_with_owner_bridge_session(
                child_definition,
                member_session_id.clone(),
                true,
                false,
            )
            .await
            .expect("create child mob owned by parent member session");
        let child_identity = AgentIdentity::from("child-worker-1");
        state
            .mob_spawn(
                &child_mob_id,
                ProfileName::from("worker"),
                child_identity.clone(),
                Some(meerkat_mob::MobRuntimeMode::TurnDriven),
                None,
                None,
            )
            .await
            .expect("spawn child worker");
        let child_bridge_session_id = state
            .handle_for(&child_mob_id)
            .await
            .expect("child mob handle")
            .resolve_bridge_session_id(&child_identity)
            .await
            .expect("child worker bridge session");
        svc.fail_archive(
            child_bridge_session_id.clone(),
            "forced archive-helper live-member child cleanup failure",
        )
        .await;

        let err = crate::agent_tools::archive_session_with_mob_cleanup(
            svc.clone(),
            state.clone(),
            &member_session_id,
        )
        .await
        .expect_err("archive helper must fail closed on child cleanup after member retire");
        let SessionError::FailedWithData { data, .. } = err else {
            panic!("expected typed incomplete child cleanup error, got {err:?}");
        };
        assert_eq!(
            data.get("code").and_then(serde_json::Value::as_str),
            Some("mob_destroy_incomplete")
        );
        assert!(
            !svc.session_exists(&member_session_id).await,
            "successful parent retire must archive the mob member bridge session before child cleanup"
        );
        assert!(
            state.handle_for(&child_mob_id).await.is_ok(),
            "incomplete child cleanup must retain the child mob retry anchor"
        );

        svc.clear_archive_failure(&child_bridge_session_id).await;
        crate::agent_tools::archive_session_with_mob_cleanup(
            svc.clone(),
            state.clone(),
            &member_session_id,
        )
        .await
        .expect("retry should complete retained child cleanup after parent member retire");
        assert!(
            state.handle_for(&child_mob_id).await.is_err(),
            "successful retry must remove the child mob retry anchor"
        );
        assert!(
            !svc.session_exists(&child_bridge_session_id).await,
            "successful retry must archive the child worker bridge session"
        );
    }

    #[tokio::test]
    async fn test_destroy_bridge_session_mobs_uses_generated_cleanup_authority() {
        let state = MobMcpState::new_in_memory();
        let sid = SessionId::new().to_string();

        // Mob ids are unique per test: a mob's supervisor registers
        // `<mob_id>/__mob_supervisor__` in the process-global in-process
        // comms registry, so two concurrently running tests that reuse one id
        // collide with `ParticipantNameOccupied`.
        let manual = explicit_definition("manual-owner-index-destroy");
        let manual_id = state
            .mob_create_definition(manual)
            .await
            .expect("create manual unowned mob");

        let bridge_session_scoped = explicit_definition("bridge-session-scoped-owner");
        let bridge_session_scoped_id = state
            .mob_create_definition_with_owner_bridge_session(
                bridge_session_scoped,
                SessionId::parse(&sid).expect("session id"),
                true,
                false,
            )
            .await
            .expect("create bridge-session-scoped mob");

        state.destroy_bridge_session_mobs(&sid).await.unwrap();

        assert!(
            state.handle_for(&manual_id).await.is_ok(),
            "manual unowned mob must not be eligible for owner-session cleanup"
        );
        assert!(
            state.handle_for(&bridge_session_scoped_id).await.is_err(),
            "generated DestroyOnOwnerArchive authority must remain the cleanup truth"
        );
    }

