        /// A restart loads the default mob from its used store: nothing is
        /// created, the stored definition stands (not the one the launch
        /// passes), the stored creation record says `Host`, and the host
        /// composition is asked for the load of the default mob.
        #[tokio::test]
        async fn the_default_mob_is_loaded_from_a_used_store_and_its_stored_definition_stands() {
            const LAUNCH: &str = row_id!("launch-mob");
            for policy in [MobRestorePolicy::Eager, MobRestorePolicy::OnDemand] {
                let svc = Arc::new(MockSessionSvc::new());
                let dir = tempfile::tempdir().expect("tempdir");
                let launch = MobId::from(LAUNCH);
                {
                    let composition = RecordingComposition::new(&svc);
                    let first = host_state(LAUNCH, &svc, dir.path(), &composition, policy);
                    first
                        .serve_default_mob(explicit_definition(LAUNCH))
                        .await
                        .expect("the first launch creates the default mob");
                    end_process(&first).await;
                }
                let stored = MobStorage::persistent(launch_store(dir.path()))
                    .expect("open the default mob's store");
                assert_eq!(
                    stored
                        .creation_provenance()
                        .await
                        .expect("its creation record"),
                    Some(meerkat_mob::MobProvenance::Host),
                    "the create stored a creation record that names the host"
                );
                drop(stored);

                let svc = Arc::new(svc.cold_restart().await);
                let composition = RecordingComposition::new(&svc);
                let restarted = host_state(LAUNCH, &svc, dir.path(), &composition, policy);
                let mut supplied = explicit_definition(LAUNCH);
                let mut extra = supplied
                    .profiles
                    .get(&ProfileName::from("worker"))
                    .cloned()
                    .expect("the worker profile");
                // A bundle no create of this host offers: a serve that only
                // loads does not judge the definition it was handed.
                extra
                    .as_inline_mut()
                    .expect("an inline profile")
                    .tools
                    .bundles
                    .push("not-offered".to_string());
                supplied.profiles.insert(ProfileName::from("extra"), extra);
                let served = restarted
                    .serve_default_mob(supplied)
                    .await
                    .expect("the set loads the default mob");
                assert!(!served.created, "the store held the mob ({policy:?})");
                assert!(
                    !served
                        .handle
                        .definition()
                        .profiles
                        .contains_key(&ProfileName::from("extra")),
                    "the stored definition stands"
                );
                assert_eq!(
                    composition.composed(),
                    vec![(launch.clone(), HostMobBuildStage::Load, true)],
                    "the host composition built the load, told that it is the default mob"
                );
                assert_eq!(composition.expected(), vec![launch.clone()]);
                assert_eq!(
                    restarted.store_opens_for_test(),
                    1,
                    "the set opened the default mob's store once"
                );
                assert_eq!(
                    listed(restarted.mob_list().await.expect("the mobs")),
                    vec![launch.clone()]
                );
                end_process(&restarted).await;
            }
        }

        /// A default mob whose store cannot be opened is quarantined by the
        /// set, under the declared id: the serve answers the typed
        /// quarantine, the file is kept as found, nothing is created over
        /// it, and every other mob serves.
        #[tokio::test]
        async fn a_default_mob_whose_store_cannot_be_opened_is_quarantined_by_the_set() {
            const LAUNCH: &str = row_id!("launch-mob");
            for policy in [MobRestorePolicy::Eager, MobRestorePolicy::OnDemand] {
                let svc = Arc::new(MockSessionSvc::new());
                let dir = tempfile::tempdir().expect("tempdir");
                let launch = MobId::from(LAUNCH);
                let healthy = {
                    let composition = RecordingComposition::new(&svc);
                    let first = host_state(LAUNCH, &svc, dir.path(), &composition, policy);
                    let healthy = first
                        .mob_create_definition(explicit_definition("host-healthy"))
                        .await
                        .expect("create a second host mob");
                    end_process(&first).await;
                    healthy
                };
                std::fs::write(launch_store(dir.path()), b"not a sqlite database")
                    .expect("write an undecodable store at the default mob's place");

                let composition = RecordingComposition::new(&svc);
                let state = host_state(LAUNCH, &svc, dir.path(), &composition, policy);
                let refused = state
                    .serve_default_mob(explicit_definition(LAUNCH))
                    .await
                    .map(|_| ())
                    .expect_err("an unreadable store has no mob to serve")
                    .error;
                let data = quarantine_data(&refused);
                assert_eq!(
                    data["kind"], MOB_QUARANTINED_KIND,
                    "{refused:?} ({policy:?})"
                );
                assert_eq!(data["mob_id"], LAUNCH, "{refused:?}");
                assert_eq!(data["class"], "store_unreadable", "{refused:?}");
                assert_eq!(
                    quarantined_ids(&state.mob_inventory().await.expect("the inventory")),
                    vec![launch.clone()],
                    "the set quarantined the default mob's store"
                );
                assert_eq!(
                    std::fs::read(launch_store(dir.path())).expect("the store file"),
                    b"not a sqlite database",
                    "the store is kept as found"
                );
                assert!(
                    !composition
                        .composed()
                        .iter()
                        .any(|(mob_id, _, _)| mob_id == &launch),
                    "nothing was built for the default mob: {:?}",
                    composition.composed()
                );
                state
                    .mob_status(&healthy)
                    .await
                    .expect("the other mob serves");
                end_process(&state).await;
            }
        }

        /// A stopped mob stays stopped across a restart, the default mob
        /// included: loading it, serving it and looking it up resume
        /// nothing. The launch resumes its default mob on the handle it was
        /// served, and that resumes no other mob.
        #[tokio::test]
        async fn a_stopped_default_mob_is_served_stopped_and_resumed_by_the_launch_on_its_handle() {
            const LAUNCH: &str = row_id!("launch-mob");
            for policy in [MobRestorePolicy::Eager, MobRestorePolicy::OnDemand] {
                let svc = Arc::new(MockSessionSvc::new());
                let dir = tempfile::tempdir().expect("tempdir");
                let launch = MobId::from(LAUNCH);
                let second = {
                    let composition = RecordingComposition::new(&svc);
                    let first = host_state(LAUNCH, &svc, dir.path(), &composition, policy);
                    first
                        .serve_default_mob(explicit_definition(LAUNCH))
                        .await
                        .expect("the first launch creates the default mob");
                    let second = first
                        .mob_create_definition(explicit_definition("host-stopped"))
                        .await
                        .expect("create a second host mob");
                    for mob_id in [&launch, &second] {
                        first.mob_stop(mob_id).await.expect("stop the mob");
                        assert_eq!(
                            first.mob_status(mob_id).await.expect("its phase"),
                            MobState::Stopped
                        );
                    }
                    end_process(&first).await;
                    second
                };

                let svc = Arc::new(svc.cold_restart().await);
                let composition = RecordingComposition::new(&svc);
                let restarted = host_state(LAUNCH, &svc, dir.path(), &composition, policy);
                let served = restarted
                    .serve_default_mob(explicit_definition(LAUNCH))
                    .await
                    .expect("the set loads the default mob");
                assert_eq!(
                    served.handle.status().await.expect("its phase"),
                    MobState::Stopped,
                    "serving the default mob does not resume it ({policy:?})"
                );
                for mob_id in [&launch, &second] {
                    assert_eq!(
                        restarted.mob_status(mob_id).await.expect("its phase"),
                        MobState::Stopped,
                        "a restart and a lookup resume no stopped mob: {mob_id}"
                    );
                }

                // The launch runs its default mob by resuming it on the
                // handle it was served, as a launch does today.
                served
                    .handle
                    .resume()
                    .await
                    .expect("the launch resumes its default mob on the served handle");
                assert_eq!(
                    restarted.mob_status(&launch).await.expect("its phase"),
                    MobState::Running,
                    "the launch's resume ran the default mob"
                );
                assert_eq!(
                    restarted.mob_status(&second).await.expect("its phase"),
                    MobState::Stopped,
                    "and no other mob"
                );
                end_process(&restarted).await;
            }
        }

        /// The default mob's id is the launch's: no other create of the set
        /// takes it, before or after the default mob exists, and nothing is
        /// written at its place by a refused create.
        #[tokio::test]
        async fn only_the_launch_creates_a_mob_under_the_default_mobs_id() {
            const LAUNCH: &str = row_id!("launch-mob");
            let svc = Arc::new(MockSessionSvc::new());
            let dir = tempfile::tempdir().expect("tempdir");
            let composition = RecordingComposition::new(&svc);
            let state = host_state(
                LAUNCH,
                &svc,
                dir.path(),
                &composition,
                MobRestorePolicy::Eager,
            );
            let launch = MobId::from(LAUNCH);
            // The refusal is the one of every id the set knows: for a
            // caller the id is taken, before the default mob exists too.
            let taken = MobMcpState::default_mob_id_taken_error(&launch).to_string();

            let host_create = state
                .mob_create_definition(explicit_definition(LAUNCH))
                .await;
            assert!(
                matches!(&host_create, Err(error) if error.to_string() == taken),
                "a host create does not take the default mob's id: {host_create:?}"
            );
            let owner = SessionId::new();
            svc.insert_persisted_session(Session::with_id(owner.clone()))
                .await;
            let session_create = state
                .mob_create_definition_with_owner_bridge_session(
                    explicit_definition(LAUNCH),
                    owner,
                    true,
                    false,
                )
                .await;
            assert!(
                matches!(&session_create, Err(error) if error.to_string() == taken),
                "a create for a session does not take the default mob's id: {session_create:?}"
            );
            let pack_create = state
                .mob_create_from_mobpack(
                    explicit_definition(LAUNCH),
                    BTreeMap::new(),
                    meerkat_mob::MobDefinitionSourceIdentity::mobpack("a".repeat(64), Vec::new()),
                )
                .await;
            // The same typed refusal as the two creates above, not only an
            // error: the id is taken, and the refusal names it.
            assert!(
                matches!(
                    &pack_create,
                    Err(MobError::MobAlreadyExists(taken_id)) if taken_id == &launch
                ),
                "a mobpack create does not take the default mob's id: {pack_create:?}"
            );
            assert!(
                listed(state.mob_list().await.expect("the mobs")).is_empty()
                    && composition.composed().is_empty()
                    && state
                        .default_mob_stored_definition()
                        .await
                        .expect("the launch's read")
                        .is_none(),
                "a refused create built nothing and wrote no mob into the declared store"
            );

            let served = state
                .serve_default_mob(explicit_definition(LAUNCH))
                .await
                .expect("the launch creates its default mob");
            assert!(served.created);
            assert!(
                state
                    .mob_create_definition(explicit_definition(LAUNCH))
                    .await
                    .is_err(),
                "nor once the default mob exists"
            );
            assert_eq!(
                listed(state.mob_list().await.expect("the mobs")),
                vec![launch]
            );
        }

        /// A create under an id the set knows is refused with a typed
        /// refusal, which a surface reads without parsing text: its kind
        /// and the id. It is the same refusal for a managed mob's id and
        /// for the default mob's: for a caller the id is taken.
        #[tokio::test]
        async fn a_create_under_a_known_id_is_refused_as_mob_already_exists() {
            const LAUNCH: &str = row_id!("launch-mob");
            let svc = Arc::new(MockSessionSvc::new());
            let dir = tempfile::tempdir().expect("tempdir");
            let composition = RecordingComposition::new(&svc);
            let state = host_state(
                LAUNCH,
                &svc,
                dir.path(),
                &composition,
                MobRestorePolicy::Eager,
            );
            let names_the_taken_id = |refused: &MobError, mob_id: &str| {
                refused.structured_data()
                    == Some(serde_json::json!({
                        "kind": "mob_already_exists",
                        "mob_id": mob_id,
                    }))
            };

            // The default mob's id, before its launch has created it.
            let default_id = state
                .mob_create_definition(explicit_definition(LAUNCH))
                .await
                .expect_err("the id is the default mob's");
            assert!(names_the_taken_id(&default_id, LAUNCH), "{default_id:?}");
            assert_eq!(
                default_id.to_string(),
                format!("mob already exists: {LAUNCH}")
            );

            // A managed mob's id.
            state
                .mob_create_definition(explicit_definition("known-mob"))
                .await
                .expect("the first create");
            let managed = state
                .mob_create_definition(explicit_definition("known-mob"))
                .await
                .expect_err("the id is a managed mob's");
            assert!(names_the_taken_id(&managed, "known-mob"), "{managed:?}");
            assert_eq!(managed.to_string(), "mob already exists: known-mob");
        }

        /// The lookups a stand-down releases meet the state's closed
        /// admission whatever runs between the end of their wait and the
        /// rest of the stand-down: none of them loads the default mob, and
        /// the composition is not asked for a mob its launch never served.
        #[tokio::test]
        async fn a_lookup_a_stand_down_released_never_loads_the_default_mob() {
            const LAUNCH: &str = row_id!("launch-mob");
            let svc = Arc::new(MockSessionSvc::new());
            let dir = tempfile::tempdir().expect("tempdir");
            launch_of_an_earlier_process(LAUNCH, &svc, dir.path(), &[]).await;
            let svc = Arc::new(svc.cold_restart().await);
            let composition = RecordingComposition::new(&svc);
            let launch = MobId::from(LAUNCH);
            // A state that owns its tasks, as a host's is.
            let state = MobMcpState::new(svc.clone(), meerkat_mob::MobControlPrincipal::Owner)
                .expect("runtime custody")
                .with_persistent_storage_root(Some(dir.path().to_path_buf()))
                .with_host_mob_composition(composition.clone())
                .with_default_mob(DefaultMobDeclaration::persistent(
                    launch.clone(),
                    launch_store(dir.path()),
                ))
                .expect("the default mob is declared once")
                .into_shared();
            let held = lookups(&state, &launch, 4);
            all_still_wait(
                &held,
                "a lookup of the default mob waits for the launch's serve",
            )
            .await;

            // The stand-down is held right after it ended the wait.
            let hold = Arc::new(InsertHold::default());
            state
                .test_holds
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .insert(
                    "stand-down: after the wait for the launch ended",
                    Arc::clone(&hold),
                );
            let stand_down = {
                let state = Arc::clone(&state);
                tokio::spawn(async move {
                    state
                        .stand_down(std::time::Instant::now() + Duration::from_mins(10))
                        .await
                })
            };
            tokio::time::timeout(Duration::from_secs(30), async {
                while !hold.reached.load(std::sync::atomic::Ordering::SeqCst) {
                    tokio::time::sleep(Duration::from_millis(10)).await;
                }
            })
            .await
            .expect("the stand-down ends the wait for the launch");
            // The released lookups run on while the stand-down is held.
            for lookup in held {
                let answer = answer_of(lookup).await;
                assert!(
                    matches!(&answer, Err(MobError::Internal(reason)) if reason.contains("stood down")),
                    "a released lookup answers the stood-down error: {answer:?}"
                );
            }
            assert!(
                composition.composed().is_empty(),
                "nothing was built for a state that stands down: {:?}",
                composition.composed()
            );
            hold.release.notify_one();
            let stood_down = answer_of(stand_down).await;
            assert!(stood_down.is_clean(), "{stood_down:?}");
        }

        /// A destroy recorded against a record that refuses it changes
        /// nothing: the default mob's record refuses a destroy, so the mob
        /// stays served with its handle, whichever door let the destroy in.
        #[tokio::test]
        async fn a_destroy_the_record_refuses_leaves_the_default_mob_served() {
            const LAUNCH: &str = row_id!("launch-mob");
            let svc = Arc::new(MockSessionSvc::new());
            let dir = tempfile::tempdir().expect("tempdir");
            let composition = RecordingComposition::new(&svc);
            let state = host_state(
                LAUNCH,
                &svc,
                dir.path(),
                &composition,
                MobRestorePolicy::Eager,
            );
            let launch = MobId::from(LAUNCH);
            state
                .serve_default_mob(explicit_definition(LAUNCH))
                .await
                .expect("the launch creates its default mob");
            let handle = state.handle_for(&launch).await.expect("the default mob");
            let retired = Arc::new(RetiredMob {
                caller: MobDestroyCaller::Console,
                incarnation: handle.incarnation(),
                report: meerkat_mob::MobDestroyReport::default(),
                storage: None,
            });

            let left_the_set =
                state
                    .hosted
                    .write()
                    .await
                    .destroyed(&launch, &handle.actor_task_watch(), &retired);
            assert!(!left_the_set, "the record refused: nothing left the set");
            assert!(
                state.handle_for(&launch).await.is_ok(),
                "the default mob is still served with its handle"
            );
            assert_eq!(
                listed(state.mob_list().await.expect("the mobs")),
                vec![launch]
            );
            end_process(&state).await;
        }

        /// A host composition has one default mob: a second declaration is
        /// refused, and it names the default mob already declared.
        #[tokio::test]
        async fn a_second_declaration_of_a_default_mob_is_refused() {
            const LAUNCH: &str = row_id!("launch-mob");
            let svc = Arc::new(MockSessionSvc::new());
            let dir = tempfile::tempdir().expect("tempdir");
            let declared = MobMcpState::new(svc.clone(), meerkat_mob::MobControlPrincipal::Owner)
                .expect("runtime custody")
                .with_persistent_storage_root(Some(dir.path().to_path_buf()))
                .with_default_mob(DefaultMobDeclaration::persistent(
                    MobId::from(LAUNCH),
                    launch_store(dir.path()),
                ))
                .expect("the first declaration");
            let second = declared
                .with_default_mob(DefaultMobDeclaration::in_memory(MobId::from(
                    "another-default",
                )))
                .map(|_| ());
            assert!(
                matches!(
                    &second,
                    Err(MobError::WiringError(reason))
                        if reason.contains(LAUNCH) && reason.contains("another-default")
                ),
                "a second declaration is refused and names both mobs: {second:?}"
            );
        }

        /// A host that declared its default mob with a store file has one
        /// forked-participant table, the declared file's. A persistent root
        /// configured after that declaration opens no participant table of
        /// its own: with the councils' store given by the host, the root
        /// leaves no participant table file, and it still opens its realm
        /// profile store.
        #[tokio::test]
        async fn a_persistent_root_under_a_declared_default_store_opens_no_participant_table_of_its_own()
         {
            const LAUNCH: &str = row_id!("launch-mob");
            let svc = Arc::new(MockSessionSvc::new());
            let dir = tempfile::tempdir().expect("tempdir");
            let state = MobMcpState::new(svc, meerkat_mob::MobControlPrincipal::Owner)
                .expect("runtime custody")
                .with_temporary_council_store(Arc::new(InMemoryTemporaryCouncilStore::new()))
                .with_default_mob(DefaultMobDeclaration::persistent(
                    MobId::from(LAUNCH),
                    launch_store(dir.path()),
                ))
                .expect("the declaration")
                .try_with_persistent_storage_root(Some(dir.path().to_path_buf()))
                .expect("the persistent root");
            assert!(
                state.hosted.custody_table().is_some(),
                "the declared file's table is open"
            );
            assert!(
                MobMcpState::persistent_mob_root(dir.path())
                    .join(MobMcpState::REALM_PROFILE_STORE_FILE_NAME)
                    .exists(),
                "the root opens its realm profile store"
            );
            assert!(
                !MobMcpState::persistent_forked_participant_store_path(dir.path()).exists(),
                "the root opened a participant table file of its own beside the declared \
                 file's table"
            );
        }

        /// A declared store file whose table cannot be opened leaves the
        /// state on its own table, and a persistent root configured after
        /// the declaration then opens the root's table as it does for a host
        /// that declared no default store.
        #[tokio::test]
        async fn a_persistent_root_opens_its_participant_table_when_the_declared_files_table_is_not_open()
         {
            const LAUNCH: &str = row_id!("launch-mob");
            let svc = Arc::new(MockSessionSvc::new());
            let dir = tempfile::tempdir().expect("tempdir");
            std::fs::write(launch_store(dir.path()), b"not a database").expect("a damaged store");
            let state = MobMcpState::new(svc, meerkat_mob::MobControlPrincipal::Owner)
                .expect("runtime custody")
                .with_temporary_council_store(Arc::new(InMemoryTemporaryCouncilStore::new()))
                .with_default_mob(DefaultMobDeclaration::persistent(
                    MobId::from(LAUNCH),
                    launch_store(dir.path()),
                ))
                .expect("the declaration")
                .try_with_persistent_storage_root(Some(dir.path().to_path_buf()))
                .expect("the persistent root");
            assert!(
                state.hosted.custody_table().is_none(),
                "the declared file's table is not open"
            );
            assert!(
                MobMcpState::persistent_forked_participant_store_path(dir.path()).exists(),
                "the root opens its own participant table"
            );
        }

        /// The declared file's table is opened again before the set's first
        /// pass and never after it. A first pass that did not run to its
        /// end has already been offered the table and went on with the
        /// state's own: the pass that follows it finds the declared file
        /// openable and still adopts nothing, so the host never has two
        /// tables in one process.
        #[cfg(unix)]
        #[tokio::test]
        async fn the_declared_table_is_reopened_before_the_first_pass_only() {
            const LAUNCH: &str = row_id!("launch-mob");
            let svc = Arc::new(MockSessionSvc::new());
            let dir = tempfile::tempdir().expect("tempdir");
            std::fs::write(launch_store(dir.path()), b"not a database").expect("a damaged store");
            let state = MobMcpState::new(svc, meerkat_mob::MobControlPrincipal::Owner)
                .expect("runtime custody")
                .with_temporary_council_store(Arc::new(InMemoryTemporaryCouncilStore::new()))
                .with_default_mob(DefaultMobDeclaration::persistent(
                    MobId::from(LAUNCH),
                    launch_store(dir.path()),
                ))
                .expect("the declaration")
                .try_with_persistent_storage_root(Some(dir.path().to_path_buf()))
                .expect("the persistent root");
            assert!(
                state.hosted.custody_table_missing(),
                "the declared file's table is not open"
            );
            // The first pass: the declared file is still damaged, and the
            // root is no directory, so the pass does not finish.
            let mobs = MobMcpState::persistent_mob_root(dir.path());
            let aside = dir.path().join("mobs-aside");
            std::fs::rename(&mobs, &aside).expect("move the root aside");
            std::fs::write(&mobs, b"not a directory").expect("a file at the root's place");
            state
                .mob_list()
                .await
                .expect_err("a pass over a root that is no directory fails");
            assert!(!state.mob_set_complete());
            assert!(
                state.hosted.custody_table_missing(),
                "the first pass could not open the damaged file's table"
            );
            // Both are repaired: the declared file could be opened now.
            std::fs::remove_file(launch_store(dir.path())).expect("remove the damaged store");
            std::fs::remove_file(&mobs).expect("remove the file");
            std::fs::rename(&aside, &mobs).expect("move the root back");
            state.mob_list().await.expect("the second pass finishes");
            assert!(state.mob_set_complete());
            assert!(
                state.hosted.custody_table_missing(),
                "a pass after the first adopts no table"
            );
        }

        /// A serve whose definition names another mob than the declared
        /// default mob is refused, and so are both verbs at a host that
        /// declared no default mob: nothing is created.
        #[tokio::test]
        async fn a_serve_that_does_not_name_the_declared_default_mob_is_refused() {
            const LAUNCH: &str = row_id!("launch-mob");
            let svc = Arc::new(MockSessionSvc::new());
            let dir = tempfile::tempdir().expect("tempdir");
            let composition = RecordingComposition::new(&svc);
            let state = host_state(
                LAUNCH,
                &svc,
                dir.path(),
                &composition,
                MobRestorePolicy::Eager,
            );
            let other = state
                .serve_default_mob(explicit_definition("another-mob"))
                .await;
            assert!(
                matches!(
                    other,
                    Err(DefaultMobServeError {
                        error: MobError::WiringError(_),
                        declared_update: None,
                    })
                ),
                "a definition of another mob is not the default mob's"
            );
            let plain = restored_state(&svc, dir.path());
            assert_eq!(plain.default_mob_id(), None);
            assert!(
                matches!(
                    plain.serve_default_mob(explicit_definition(LAUNCH)).await,
                    Err(DefaultMobServeError {
                        error: MobError::WiringError(_),
                        declared_update: None,
                    })
                ),
                "a host that declared no default mob serves none"
            );
            assert!(
                matches!(
                    plain.default_mob_stored_definition().await,
                    Err(MobError::WiringError(_))
                ),
                "and reads no default mob's store"
            );
            assert!(
                listed(state.mob_list().await.expect("the mobs")).is_empty()
                    && listed(plain.mob_list().await.expect("the mobs")).is_empty()
                    && state
                        .default_mob_stored_definition()
                        .await
                        .expect("the launch's read")
                        .is_none(),
                "nothing was created"
            );
        }

        /// A file at the default mob's place that holds no mob is the
        /// launch's: the set does not sweep it as it sweeps an empty store
        /// under its root, and the default mob is created in it.
        #[tokio::test]
        async fn an_empty_store_at_the_default_mobs_place_is_kept_and_the_mob_is_created_in_it() {
            const LAUNCH: &str = row_id!("launch-mob");
            for policy in [MobRestorePolicy::Eager, MobRestorePolicy::OnDemand] {
                let svc = Arc::new(MockSessionSvc::new());
                let dir = tempfile::tempdir().expect("tempdir");
                drop(
                    MobStorage::persistent(launch_store(dir.path()))
                        .expect("an empty store at the default mob's place"),
                );
                let composition = RecordingComposition::new(&svc);
                let state = host_state(LAUNCH, &svc, dir.path(), &composition, policy);
                assert!(
                    listed(state.mob_list().await.expect("the mobs")).is_empty(),
                    "an empty store holds no mob to list"
                );
                let served = state
                    .serve_default_mob(explicit_definition(LAUNCH))
                    .await
                    .expect("the set creates the default mob in the empty store");
                assert!(served.created, "the store held no mob ({policy:?})");
                assert!(launch_store(dir.path()).exists());
                assert_eq!(
                    composition.composed(),
                    vec![(MobId::from(LAUNCH), HostMobBuildStage::Create, true)]
                );
                end_process(&state).await;

                // The same store again, now holding the mob: an empty read
                // before the create removed nothing the create then wrote.
                let svc = Arc::new(svc.cold_restart().await);
                let composition = RecordingComposition::new(&svc);
                let restarted = host_state(LAUNCH, &svc, dir.path(), &composition, policy);
                assert!(
                    !restarted
                        .serve_default_mob(explicit_definition(LAUNCH))
                        .await
                        .expect("the set loads the default mob")
                        .created
                );
                end_process(&restarted).await;
            }
        }

        /// The serve that reads the empty file at the default mob's place
        /// finds no mob there and creates the mob in that same file: the
        /// file is not removed and written again.
        #[cfg(unix)]
        #[tokio::test]
        async fn a_load_does_not_remove_an_empty_file_at_the_default_mobs_place() {
            const LAUNCH: &str = row_id!("launch-mob");
            use std::os::unix::fs::MetadataExt as _;
            let svc = Arc::new(MockSessionSvc::new());
            let dir = tempfile::tempdir().expect("tempdir");
            drop(
                MobStorage::persistent(launch_store(dir.path()))
                    .expect("an empty store at the default mob's place"),
            );
            let before = std::fs::metadata(launch_store(dir.path()))
                .expect("the empty store file")
                .ino();
            // An open descriptor keeps the file's inode from being handed to
            // a file written in its place.
            let _same_file =
                std::fs::File::open(launch_store(dir.path())).expect("open the empty store file");
            let composition = RecordingComposition::new(&svc);
            let state = host_state(
                LAUNCH,
                &svc,
                dir.path(),
                &composition,
                MobRestorePolicy::Eager,
            );
            let launch = MobId::from(LAUNCH);
            assert_eq!(
                state.mob_inventory().await.expect("the inventory").dormant,
                vec![launch.clone()],
                "the census knows the file at the default mob's place and has not read it"
            );
            assert!(
                state
                    .serve_default_mob(explicit_definition(LAUNCH))
                    .await
                    .expect("the set creates the default mob in the empty store")
                    .created
            );
            assert_eq!(
                std::fs::metadata(launch_store(dir.path()))
                    .expect("the store file")
                    .ino(),
                before,
                "the load read the store and kept the file: the create wrote into it"
            );
            let inventory = state.mob_inventory().await.expect("the inventory");
            assert!(
                inventory.dormant.is_empty() && inventory.quarantined.is_empty(),
                "the created mob is neither dormant nor quarantined: {:?} {:?}",
                inventory.dormant,
                inventory.quarantined
            );
        }

        /// No pass is offered the declared store: the sweep over the dormant
        /// mobs opens every store it is offered before it asks for a load,
        /// and it does not open the default mob's store before the launch's
        /// serve. The record would refuse the load in any case; this is
        /// about the read.
        #[tokio::test]
        async fn no_pass_is_offered_the_declared_store() {
            const LAUNCH: &str = row_id!("launch-mob");
            let svc = Arc::new(MockSessionSvc::new());
            let dir = tempfile::tempdir().expect("tempdir");
            launch_of_an_earlier_process(LAUNCH, &svc, dir.path(), &[]).await;
            let svc = Arc::new(svc.cold_restart().await);
            let composition = RecordingComposition::new(&svc);
            let state = host_state(
                LAUNCH,
                &svc,
                dir.path(),
                &composition,
                MobRestorePolicy::OnDemand,
            );
            let launch = MobId::from(LAUNCH);
            assert_eq!(
                state.mob_inventory().await.expect("the inventory").dormant,
                vec![launch],
                "the default mob is known and not loaded"
            );
            let opens = state.store_opens_for_test();

            let torn_down = state.sweep_dormant_mobs().await;
            assert!(torn_down.is_empty(), "{torn_down:?}");
            assert_eq!(
                state.store_opens_for_test(),
                opens,
                "the sweep opened no store: the declared one is not offered to it"
            );
            still_awaits_its_serve(LAUNCH, &state, &composition).await;
        }

        /// No pass of the set loads the default mob: the eager restore
        /// loads every other store and leaves it dormant, and so does the
        /// start of an on-demand set that must load every dormant mob. The
        /// launch's serve loads it.
        #[tokio::test]
        async fn no_pass_of_the_set_loads_the_default_mob() {
            const LAUNCH: &str = row_id!("launch-mob");
            const HOST_SECOND: &str = row_id!("host-second");
            for policy in [MobRestorePolicy::Eager, MobRestorePolicy::OnDemand] {
                let svc = Arc::new(MockSessionSvc::new());
                let dir = tempfile::tempdir().expect("tempdir");
                let launch = MobId::from(LAUNCH);
                let second = {
                    let composition = RecordingComposition::new(&svc);
                    let first = host_state(LAUNCH, &svc, dir.path(), &composition, policy);
                    first
                        .serve_default_mob(explicit_definition(LAUNCH))
                        .await
                        .expect("the first launch creates the default mob");
                    let second = first
                        .mob_create_definition(explicit_definition(HOST_SECOND))
                        .await
                        .expect("create a second host mob");
                    end_process(&first).await;
                    second
                };

                let svc = Arc::new(svc.cold_restart().await);
                let composition = RecordingComposition::new(&svc);
                let restarted = host_state(LAUNCH, &svc, dir.path(), &composition, policy);
                // The start cannot tell which mobs hold work: it loads
                // every dormant mob it may load.
                restarted.script_start_obligations_for_test(
                    meerkat_runtime::RuntimeBootObligations {
                        recovery_work: meerkat_runtime::RuntimeRecoveryWork::Unobserved(
                            meerkat_runtime::RuntimeRecoveryWorkUnobserved::RecoveryScanUnsupported,
                        ),
                        pending_deliveries: HashSet::new(),
                    },
                );
                let inventory = restarted.mob_inventory().await.expect("the inventory");
                assert_eq!(
                    inventory
                        .managed
                        .iter()
                        .map(|(mob_id, _)| mob_id.clone())
                        .collect::<Vec<_>>(),
                    vec![second.clone()],
                    "the pass loaded the other host mob ({policy:?})"
                );
                assert_eq!(
                    inventory.dormant,
                    vec![launch.clone()],
                    "and left the default mob known and not loaded ({policy:?})"
                );
                assert_eq!(
                    composition.composed(),
                    vec![(second.clone(), HostMobBuildStage::Load, false)],
                    "the composition was not asked for the default mob"
                );
                assert!(
                    !restarted
                        .serve_default_mob(explicit_definition(LAUNCH))
                        .await
                        .expect("the launch's serve loads the default mob")
                        .created
                );
                end_process(&restarted).await;
            }
        }

        /// A host that declared its default mob inserts no handle of its
        /// own under that id: the door for foreign handles refuses it, and
        /// keeps taking every other id.
        #[tokio::test]
        async fn a_foreign_handle_is_not_inserted_under_the_default_mobs_id() {
            const LAUNCH: &str = row_id!("launch-mob");
            let svc = Arc::new(MockSessionSvc::new());
            let dir = tempfile::tempdir().expect("tempdir");
            let composition = RecordingComposition::new(&svc);
            let state = host_state(
                LAUNCH,
                &svc,
                dir.path(),
                &composition,
                MobRestorePolicy::Eager,
            );
            let foreign = |id: &str| {
                let svc = svc.clone();
                let definition = explicit_definition(id);
                async move {
                    MobBuilder::new(definition, MobStorage::in_memory())
                        .with_session_service(svc)
                        .allow_ephemeral_sessions(true)
                        .create()
                        .await
                        .expect("a mob built outside the set")
                }
            };
            let refused = state
                .try_mob_insert_handle(MobId::from(LAUNCH), foreign(LAUNCH).await)
                .await;
            assert!(
                matches!(&refused, Err(MobError::MobAlreadyExists(mob_id)) if mob_id.as_str() == LAUNCH),
                "the default mob's id takes no foreign handle: {refused:?}"
            );
            assert!(
                listed(state.mob_list().await.expect("the mobs")).is_empty(),
                "nothing was inserted"
            );
            state
                .try_mob_insert_handle(MobId::from("foreign-mob"), foreign("foreign-mob").await)
                .await
                .expect("another id takes a foreign handle as before");
            assert_eq!(
                listed(state.mob_list().await.expect("the mobs")),
                vec![MobId::from("foreign-mob")]
            );
        }

        /// The launch reads what its default mob's store holds through the
        /// set, before anything is built: nothing for a store with no mob
        /// in it, the stored definition for a used one (the mob stays not
        /// loaded and the composition is not asked), and the typed
        /// quarantine for a store that cannot be opened.
        #[tokio::test]
        async fn the_launch_reads_its_default_mobs_stored_definition_without_loading_it() {
            const LAUNCH: &str = row_id!("launch-mob");
            let svc = Arc::new(MockSessionSvc::new());
            let dir = tempfile::tempdir().expect("tempdir");
            let launch = MobId::from(LAUNCH);
            {
                let composition = RecordingComposition::new(&svc);
                let first = host_state(
                    LAUNCH,
                    &svc,
                    dir.path(),
                    &composition,
                    MobRestorePolicy::Eager,
                );
                assert!(
                    first
                        .default_mob_stored_definition()
                        .await
                        .expect("a store with no mob reads")
                        .is_none(),
                    "a store with no events holds no mob"
                );
                assert!(
                    quarantined_ids(&first.mob_inventory().await.expect("the inventory"))
                        .is_empty(),
                    "and is not quarantined for it"
                );
                first
                    .serve_default_mob(explicit_definition(LAUNCH))
                    .await
                    .expect("the first launch creates the default mob");
                end_process(&first).await;
            }

            let svc = Arc::new(svc.cold_restart().await);
            let composition = RecordingComposition::new(&svc);
            let restarted = host_state(
                LAUNCH,
                &svc,
                dir.path(),
                &composition,
                MobRestorePolicy::Eager,
            );
            let stored = restarted
                .default_mob_stored_definition()
                .await
                .expect("the used store reads")
                .expect("it holds the default mob");
            assert_eq!(stored.definition().id, launch);
            assert_eq!(
                restarted
                    .mob_inventory()
                    .await
                    .expect("the inventory")
                    .dormant,
                vec![launch.clone()],
                "the read loaded nothing"
            );
            assert!(composition.composed().is_empty() && composition.expected().is_empty());
            // The snapshot the read answered binds the load.
            *composition
                .bind
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(stored);
            assert!(
                !restarted
                    .serve_default_mob(explicit_definition(LAUNCH))
                    .await
                    .expect("the load bound to the snapshot is served")
                    .created
            );
            end_process(&restarted).await;

            std::fs::write(launch_store(dir.path()), b"not a sqlite database")
                .expect("write an undecodable store at the default mob's place");
            let svc = Arc::new(svc.cold_restart().await);
            let composition = RecordingComposition::new(&svc);
            let broken = host_state(
                LAUNCH,
                &svc,
                dir.path(),
                &composition,
                MobRestorePolicy::Eager,
            );
            let refused = broken
                .default_mob_stored_definition()
                .await
                .expect_err("an unreadable store is not read as empty");
            assert!(
                quarantine_data(&refused)["kind"] != MOB_QUARANTINED_KIND,
                "a failed read answers its own error, not a quarantine: {refused:?}"
            );
            let inventory = broken.mob_inventory().await.expect("the inventory");
            assert!(
                inventory.quarantined.is_empty(),
                "a failed read quarantines nothing: {:?}",
                inventory.quarantined
            );
            assert_eq!(
                inventory.dormant,
                vec![launch.clone()],
                "the store's record is as the census left it"
            );
            // The launch's serve is what loads the store, and what
            // quarantines it.
            let served = broken
                .serve_default_mob(explicit_definition(LAUNCH))
                .await
                .map(|_| ())
                .expect_err("the serve meets the unreadable store")
                .error;
            assert_eq!(
                quarantine_data(&served)["kind"],
                MOB_QUARANTINED_KIND,
                "{served:?}"
            );
            assert_eq!(
                quarantined_ids(&broken.mob_inventory().await.expect("the inventory")),
                vec![launch]
            );
            let read = broken
                .default_mob_stored_definition()
                .await
                .expect_err("a quarantined store is not read as holding no mob");
            assert_eq!(
                quarantine_data(&read)["kind"],
                MOB_QUARANTINED_KIND,
                "a read after the serve answers the quarantine the serve met: {read:?}"
            );
        }

        /// A store at the default mob's place that holds another mob is not
        /// served as the default mob and not under its own id: the set
        /// quarantines it under the declared id.
        #[tokio::test]
        async fn a_store_at_the_default_mobs_place_that_names_another_mob_is_quarantined_under_the_default_id()
         {
            const LAUNCH: &str = row_id!("launch-mob");
            const ANOTHER_LAUNCH: &str = row_id!("another-launch");
            for policy in [MobRestorePolicy::Eager, MobRestorePolicy::OnDemand] {
                let svc = Arc::new(MockSessionSvc::new());
                let dir = tempfile::tempdir().expect("tempdir");
                let other = MobId::from(ANOTHER_LAUNCH);
                {
                    let earlier = Arc::new(
                        MobMcpState::new(svc.clone(), meerkat_mob::MobControlPrincipal::Owner)
                            .expect("runtime custody")
                            .with_default_mob(DefaultMobDeclaration::persistent(
                                other.clone(),
                                launch_store(dir.path()),
                            ))
                            .expect("the default mob is declared once"),
                    );
                    earlier
                        .serve_default_mob(explicit_definition(ANOTHER_LAUNCH))
                        .await
                        .expect("an earlier launch created another mob at the place");
                    end_process(&earlier).await;
                }
                let before = std::fs::metadata(launch_store(dir.path()))
                    .expect("the store file")
                    .len();

                let svc = Arc::new(svc.cold_restart().await);
                let composition = RecordingComposition::new(&svc);
                let state = host_state(LAUNCH, &svc, dir.path(), &composition, policy);
                let refused = state
                    .serve_default_mob(explicit_definition(LAUNCH))
                    .await
                    .map(|_| ())
                    .expect_err("the store holds another mob")
                    .error;
                let data = quarantine_data(&refused);
                assert_eq!(
                    data["kind"], MOB_QUARANTINED_KIND,
                    "{refused:?} ({policy:?})"
                );
                assert_eq!(data["mob_id"], LAUNCH, "{refused:?}");
                assert_eq!(data["class"], "resume_refused", "{refused:?}");
                assert_eq!(
                    quarantined_ids(&state.mob_inventory().await.expect("the inventory")),
                    vec![MobId::from(LAUNCH)]
                );
                assert!(
                    matches!(
                        state.mob_status(&other).await,
                        Err(MobError::MobNotFound(_))
                    ),
                    "the stored mob is not served under its own id either"
                );
                assert!(
                    composition.composed().is_empty(),
                    "nothing was built: {:?}",
                    composition.composed()
                );
                // A declared update is no way around it: the store holds
                // another mob, so nothing is committed to it and the serve
                // answers the same quarantine.
                let declared = state
                    .serve_default_mob(
                        DefaultMobServe::new(explicit_definition(LAUNCH)).declaring_update(1),
                    )
                    .await
                    .expect_err("the store holds another mob");
                assert_eq!(
                    quarantine_data(&declared.error)["kind"],
                    MOB_QUARANTINED_KIND,
                    "{declared:?}"
                );
                assert!(declared.declared_update.is_none(), "{declared:?}");
                assert_eq!(
                    MobStorage::persistent(launch_store(dir.path()))
                        .expect("open the store at the default mob's place")
                        .created_definition()
                        .await
                        .expect("read its definition")
                        .expect("its stored definition")
                        .id,
                    other,
                    "the other mob's definition is untouched"
                );
                assert!(
                    std::fs::metadata(launch_store(dir.path()))
                        .expect("the store file")
                        .len()
                        >= before,
                    "the store is kept"
                );
            }
        }

        /// A store at the default mob's place whose creation record names
        /// another mob and whose log is gone disagrees with itself. It is
        /// quarantined under the default mob's id, where the launch finds
        /// it, so the id is not free for a create over a store that is
        /// kept.
        #[tokio::test]
        async fn a_store_at_the_default_mobs_place_that_disagrees_with_itself_is_quarantined_under_the_default_id()
         {
            const LAUNCH: &str = row_id!("launch-mob");
            const ANOTHER_LAUNCH: &str = row_id!("another-launch");
            let svc = Arc::new(MockSessionSvc::new());
            let dir = tempfile::tempdir().expect("tempdir");
            {
                let earlier = Arc::new(
                    MobMcpState::new(svc.clone(), meerkat_mob::MobControlPrincipal::Owner)
                        .expect("runtime custody")
                        .with_default_mob(DefaultMobDeclaration::persistent(
                            MobId::from(ANOTHER_LAUNCH),
                            launch_store(dir.path()),
                        ))
                        .expect("the default mob is declared once"),
                );
                earlier
                    .serve_default_mob(explicit_definition(ANOTHER_LAUNCH))
                    .await
                    .expect("an earlier launch created another mob at the place");
                end_process(&earlier).await;
            }
            MobStorage::drop_event_log_for_test(&launch_store(dir.path()))
                .expect("drop the store's event log");

            let svc = Arc::new(svc.cold_restart().await);
            let composition = RecordingComposition::new(&svc);
            let state = host_state(
                LAUNCH,
                &svc,
                dir.path(),
                &composition,
                MobRestorePolicy::OnDemand,
            );
            let refused = state
                .serve_default_mob(explicit_definition(LAUNCH))
                .await
                .map(|_| ())
                .expect_err("a store that disagrees with itself has no mob to serve")
                .error;
            let data = quarantine_data(&refused);
            assert_eq!(data["kind"], MOB_QUARANTINED_KIND, "{refused:?}");
            assert_eq!(data["mob_id"], LAUNCH, "{refused:?}");
            assert_eq!(data["class"], "resume_refused", "{refused:?}");
            assert_eq!(
                quarantined_ids(&state.mob_inventory().await.expect("the inventory")),
                vec![MobId::from(LAUNCH)],
                "the fault is filed under the default mob's id"
            );
            assert!(
                composition.composed().is_empty(),
                "nothing was built: {:?}",
                composition.composed()
            );
        }

        /// A launch mob an earlier release built outside the set (its
        /// creation records something other than the host, or nothing) is
        /// the default mob all the same once the host declares it: the set
        /// loads it from the declared store with the host composition.
        #[tokio::test]
        async fn a_default_mob_created_outside_the_set_is_loaded_with_the_host_composition() {
            const LAUNCH: &str = row_id!("launch-mob");
            let svc = Arc::new(MockSessionSvc::new());
            let dir = tempfile::tempdir().expect("tempdir");
            let launch = MobId::from(LAUNCH);
            MobBuilder::new(
                explicit_definition(LAUNCH),
                MobStorage::persistent(launch_store(dir.path())).expect("the launch mob's store"),
            )
            .with_session_service(svc.clone())
            .allow_ephemeral_sessions(true)
            .with_provenance(meerkat_mob::MobProvenance::Session {
                session_id: SessionId::new(),
            })
            .create()
            .await
            .expect("a launch mob built outside the set")
            .shutdown()
            .await
            .expect("end the earlier process");

            let svc = Arc::new(svc.cold_restart().await);
            let composition = RecordingComposition::new(&svc);
            let state = host_state(
                LAUNCH,
                &svc,
                dir.path(),
                &composition,
                MobRestorePolicy::Eager,
            );
            let served = state
                .serve_default_mob(explicit_definition(LAUNCH))
                .await
                .expect("the set loads the launch mob");
            assert!(!served.created);
            assert_eq!(
                composition.composed(),
                vec![(launch, HostMobBuildStage::Load, true)],
                "the default mob is a host build whatever its creation recorded"
            );
        }

        /// A default mob declared to live in memory is created in memory:
        /// no store file is written for it, also at a host with a
        /// persistent root, and its store holds nothing a later launch
        /// could read.
        #[tokio::test]
        async fn a_default_mob_declared_in_memory_writes_no_store() {
            const LAUNCH: &str = row_id!("launch-mob");
            let svc = Arc::new(MockSessionSvc::new());
            let dir = tempfile::tempdir().expect("tempdir");
            let launch = MobId::from(LAUNCH);
            let state = Arc::new(
                MobMcpState::new(svc.clone(), meerkat_mob::MobControlPrincipal::Owner)
                    .expect("runtime custody")
                    .with_persistent_storage_root(Some(dir.path().to_path_buf()))
                    .with_default_mob(DefaultMobDeclaration::in_memory(launch.clone()))
                    .expect("the default mob is declared once"),
            );
            assert!(
                state
                    .serve_default_mob(explicit_definition(LAUNCH))
                    .await
                    .expect("the set creates the default mob")
                    .created
            );
            assert_eq!(
                mob_store_files(dir.path()),
                0,
                "the default mob is not a store under the root"
            );
            assert!(
                state
                    .default_mob_stored_definition()
                    .await
                    .expect("the read answers")
                    .is_none(),
                "a mob in memory has no store a launch could read"
            );
            assert_eq!(
                listed(state.mob_list().await.expect("the mobs")),
                vec![launch]
            );
        }

        /// The default mob's definition is the host's own, as a definition
        /// a host builds with `MobBuilder` is: an inline profile of it may
        /// opt into tool bundles (`tools.bundles`). The launch's serve
        /// creates the mob from such a definition, and the mob's builder
        /// mounts each named bundle the host's composition registered and
        /// withholds the rest. A host create of any other mob still offers
        /// no tool bundle.
        #[tokio::test]
        async fn the_serve_creates_a_default_mob_whose_profile_opts_into_a_tool_bundle() {
            const LAUNCH: &str = row_id!("launch-mob");
            let svc = Arc::new(MockSessionSvc::new());
            let state = Arc::new(
                MobMcpState::new(svc, meerkat_mob::MobControlPrincipal::Owner)
                    .expect("runtime custody")
                    .with_default_mob(DefaultMobDeclaration::in_memory(MobId::from(LAUNCH)))
                    .expect("the default mob is declared once"),
            );
            let served = state.serve_default_mob(opting_definition(LAUNCH)).await;
            assert!(
                matches!(&served, Ok(served) if served.created),
                "the serve creates a default mob whose inline profile opts into a tool \
                 bundle: {:?}",
                served.as_ref().err()
            );
            let other = state
                .mob_create_definition(opting_definition("another-host-mob"))
                .await;
            assert!(
                matches!(&other, Err(MobError::ToolBundleNotOffered { .. })),
                "a host create of another mob still offers no tool bundle: {other:?}"
            );
        }

        /// A default mob declared to live in memory is the launch's from the
        /// declaration on, like one with a store file: the set knows it and
        /// names it as not loaded, a lookup of it waits for the launch's
        /// first serve, and every waiting lookup is then served the mob.
        #[tokio::test]
        async fn lookups_of_a_default_mob_in_memory_wait_for_the_launchs_first_serve() {
            const LAUNCH: &str = row_id!("launch-mob");
            let svc = Arc::new(MockSessionSvc::new());
            let launch = MobId::from(LAUNCH);
            let state = Arc::new(
                MobMcpState::new(svc.clone(), meerkat_mob::MobControlPrincipal::Owner)
                    .expect("runtime custody")
                    .with_default_mob(DefaultMobDeclaration::in_memory(launch.clone()))
                    .expect("the default mob is declared once"),
            );
            assert_eq!(
                state.mob_inventory().await.expect("the inventory").dormant,
                vec![launch.clone()],
                "the declared mob is known and not loaded before its launch serves it"
            );
            assert!(
                !state.awaited_mob_settled(&launch).await,
                "what waits for the declared mob is not decided again before its launch \
                 serves it: the recovery sweep does not use its passes up on it"
            );
            let held = lookups(&state, &launch, 3);
            all_still_wait(
                &held,
                "a lookup of the default mob in memory waits for the launch's serve",
            )
            .await;

            assert!(
                state
                    .serve_default_mob(explicit_definition(LAUNCH))
                    .await
                    .expect("the set creates the default mob")
                    .created
            );
            for lookup in held {
                let answer = tokio::time::timeout(Duration::from_secs(30), lookup)
                    .await
                    .expect("the lookup is released by the serve")
                    .expect("the lookup task");
                assert!(
                    answer.is_ok(),
                    "each held lookup is served the mob: {answer:?}"
                );
            }
            assert!(
                state
                    .mob_inventory()
                    .await
                    .expect("the inventory")
                    .dormant
                    .is_empty(),
                "the served mob is not named as waiting to be loaded"
            );
            end_process(&state).await;
        }

        /// Under `OnDemand` the idle unload asks every loaded mob but the
        /// default mob: a further host mob is unloaded when idle, the
        /// default mob stays loaded.
        #[tokio::test]
        async fn the_default_mob_is_not_asked_for_an_idle_unload() {
            const LAUNCH: &str = row_id!("launch-mob");
            let svc = Arc::new(MockSessionSvc::new());
            let dir = tempfile::tempdir().expect("tempdir");
            let composition = RecordingComposition::new(&svc);
            let state = host_state(
                LAUNCH,
                &svc,
                dir.path(),
                &composition,
                MobRestorePolicy::OnDemand,
            );
            let launch = MobId::from(LAUNCH);
            state
                .serve_default_mob(explicit_definition(LAUNCH))
                .await
                .expect("the set creates the default mob");
            let second = state
                .mob_create_definition(explicit_definition("host-idle"))
                .await
                .expect("create a second host mob");

            let unloaded = tokio::time::timeout(Duration::from_mins(1), state.unload_idle_mobs())
                .await
                .expect("the unload pass finishes");
            assert_eq!(
                unloaded,
                vec![second.clone()],
                "the idle host mob is unloaded, the default mob is not asked"
            );
            let inventory = state.mob_inventory().await.expect("the inventory");
            assert_eq!(inventory.dormant, vec![second.clone()]);
            assert_eq!(
                inventory
                    .managed
                    .iter()
                    .map(|(mob_id, _)| mob_id.clone())
                    .collect::<Vec<_>>(),
                vec![launch]
            );
            // The unloaded host mob loads again, built by the composition.
            state
                .mob_status(&second)
                .await
                .expect("the host mob loads again");
            assert_eq!(
                composition.composed().last(),
                Some(&(second, HostMobBuildStage::Load, false))
            );
        }

        /// A host with no persistent root (its further mobs live for the
        /// process) and a default mob with a store of its own: the set
        /// knows that store from its first verb, its census is complete
        /// without a declaration of the host, and a restart loads the mob.
        #[tokio::test]
        async fn a_host_without_a_persistent_root_still_knows_its_default_mobs_store() {
            const LAUNCH: &str = row_id!("launch-mob");
            for policy in [MobRestorePolicy::Eager, MobRestorePolicy::OnDemand] {
                let svc = Arc::new(MockSessionSvc::new());
                let dir = tempfile::tempdir().expect("tempdir");
                let launch = MobId::from(LAUNCH);
                let rootless = |svc: &Arc<MockSessionSvc>| {
                    Arc::new(
                        MobMcpState::new(svc.clone(), meerkat_mob::MobControlPrincipal::Owner)
                            .expect("runtime custody")
                            .with_mob_restore_policy(policy)
                            .with_default_mob(DefaultMobDeclaration::persistent(
                                launch.clone(),
                                launch_store(dir.path()),
                            ))
                            .expect("the default mob is declared once"),
                    )
                };
                {
                    let first = rootless(&svc);
                    assert!(
                        first
                            .serve_default_mob(explicit_definition(LAUNCH))
                            .await
                            .expect("the set creates the default mob")
                            .created
                    );
                    end_process(&first).await;
                }

                let svc = Arc::new(svc.cold_restart().await);
                let restarted = rootless(&svc);
                let inventory = restarted.mob_inventory().await.expect("the inventory");
                assert_eq!(
                    inventory.dormant,
                    vec![launch.clone()],
                    "the first verb's census knows the default mob's store ({policy:?})"
                );
                assert!(
                    restarted.mob_set_complete(),
                    "the census is complete without a declaration of the host"
                );
                assert!(
                    !restarted
                        .serve_default_mob(explicit_definition(LAUNCH))
                        .await
                        .expect("the set loads the default mob")
                        .created
                );
                end_process(&restarted).await;
            }
        }

        /// The launch mob `launch` of an earlier process and `others` further
        /// host mobs: created by the set, the launch mob at [`launch_store`],
        /// and ended. The ids of the further mobs.
        async fn launch_of_an_earlier_process(
            launch: &str,
            svc: &Arc<MockSessionSvc>,
            dir: &std::path::Path,
            others: &[&str],
        ) -> Vec<MobId> {
            let composition = RecordingComposition::new(svc);
            let first = host_state(launch, svc, dir, &composition, MobRestorePolicy::Eager);
            first
                .serve_default_mob(explicit_definition(launch))
                .await
                .expect("the first launch creates the default mob");
            let mut created = Vec::new();
            for other in others {
                created.push(
                    first
                        .mob_create_definition(explicit_definition(other))
                        .await
                        .expect("create a further host mob"),
                );
            }
            end_process(&first).await;
            created
        }

        /// `count` lookups of the mob `mob_id`, each on a task of its own.
        fn lookups(
            state: &Arc<MobMcpState>,
            mob_id: &MobId,
            count: usize,
        ) -> Vec<tokio::task::JoinHandle<Result<MobState, MobError>>> {
            (0..count)
                .map(|_| {
                    let state = Arc::clone(state);
                    let mob_id = mob_id.clone();
                    tokio::spawn(async move { state.mob_status(&mob_id).await })
                })
                .collect()
        }

        /// Give the tasks time to run, then check that none has answered.
        async fn all_still_wait<T>(tasks: &[tokio::task::JoinHandle<T>], why: &str) {
            tokio::time::sleep(Duration::from_millis(500)).await;
            assert!(tasks.iter().all(|task| !task.is_finished()), "{why}");
        }

        /// The default mob `launch` still awaits its serve: nothing loaded
        /// it, and the composition was not asked for it.
        async fn still_awaits_its_serve(
            launch: &str,
            state: &MobMcpState,
            composition: &RecordingComposition,
        ) {
            let launch = MobId::from(launch);
            assert!(
                !composition
                    .composed()
                    .iter()
                    .any(|(mob_id, _, _)| mob_id == &launch),
                "the composition is not asked for the default mob before the launch's serve: {:?}",
                composition.composed()
            );
            let inventory = state.mob_inventory().await.expect("the inventory");
            assert!(
                inventory.dormant.contains(&launch) && inventory.quarantined.is_empty(),
                "the default mob is known and not loaded while it awaits its serve: {:?} {:?}",
                inventory.dormant,
                inventory.quarantined
            );
        }

        /// The answer of a task that must end now.
        async fn answer_of<T>(task: tokio::task::JoinHandle<T>) -> T {
            tokio::time::timeout(Duration::from_mins(1), task)
                .await
                .expect("the task ends")
                .expect("the task")
        }

        /// A call that must not wait for the launch's serve.
        async fn at_once<T>(call: impl std::future::Future<Output = T>, what: &str) -> T {
            tokio::time::timeout(Duration::from_secs(20), call)
                .await
                .unwrap_or_else(|_| panic!("{what} does not wait for the launch's serve"))
        }

        /// A wake of a session of the launch mob's own member, while that mob
        /// awaits the launch's first serve, answers at once that no owner
        /// holds the session: it does not wait for the serve, loads nothing
        /// and asks the composition for nothing. The launch serves its mob,
        /// and the mob's own actor then answers for its member. So it is on
        /// a host whose only mob is its launch's.
        #[tokio::test]
        async fn a_wake_of_a_session_neither_waits_for_the_launchs_serve_nor_loads_its_mob() {
            const LAUNCH: &str = row_id!("launch-mob");
            use meerkat_core::session_owner_wake::{
                SessionOwnerWakeOutcome, SessionOwnerWakeRegistry,
            };

            let svc = Arc::new(MockSessionSvc::new());
            let dir = tempfile::tempdir().expect("tempdir");
            let launch = MobId::from(LAUNCH);
            let worker = AgentIdentity::from("worker-1");
            let first = host_state(
                LAUNCH,
                &svc,
                dir.path(),
                &RecordingComposition::new(&svc),
                MobRestorePolicy::Eager,
            );
            first
                .serve_default_mob(explicit_definition(LAUNCH))
                .await
                .expect("the first launch creates the default mob");
            first
                .mob_spawn(
                    &launch,
                    ProfileName::from("worker"),
                    worker.clone(),
                    Some(MobRuntimeMode::TurnDriven),
                    None,
                    None,
                )
                .await
                .expect("seat a worker in the launch's mob");
            let session = first
                .mob_resolve_bridge_session_id(&launch, &worker)
                .await
                .expect("resolve bridge session")
                .expect("worker bridge session");
            end_process(&first).await;
            drop(first);
            let svc = Arc::new(svc.cold_restart().await);
            let composition = RecordingComposition::new(&svc);
            let state = host_state(
                LAUNCH,
                &svc,
                dir.path(),
                &composition,
                MobRestorePolicy::OnDemand,
            );
            state.answer_wakes_of_unserved_member_sessions();
            still_awaits_its_serve(LAUNCH, &state, &composition).await;
            let opens = state.store_opens_for_test();

            let woken = at_once(
                SessionOwnerWakeRegistry::global().wake(&session),
                "a wake of a session of the launch mob's member",
            )
            .await;
            assert!(
                matches!(woken, None | Some(Ok(SessionOwnerWakeOutcome::NotOwned))),
                "the set answers for no session of the launch's mob: {woken:?}"
            );
            still_awaits_its_serve(LAUNCH, &state, &composition).await;
            assert_eq!(
                state.store_opens_for_test(),
                opens,
                "the wake opened no store"
            );

            state
                .serve_default_mob(explicit_definition(LAUNCH))
                .await
                .expect("the serve loads the default mob");
            let woken = SessionOwnerWakeRegistry::global().wake(&session).await;
            assert!(
                matches!(woken, Some(Ok(SessionOwnerWakeOutcome::Ready))),
                "the launch mob's own actor answers for its member: {woken:?}"
            );
        }

        /// Every lookup of the default mob waits for the launch's first
        /// serve: nothing loads the mob, and nothing asks the composition
        /// for it, before the launch is ready. What hands out no handle
        /// answers at once, the launch's own read answers and releases
        /// nobody, other mobs load meanwhile without ending the wait, and
        /// the serve itself is not held. The serve releases every waiter.
        #[tokio::test]
        async fn lookups_of_the_default_mob_wait_for_the_launchs_first_serve() {
            const LAUNCH: &str = row_id!("launch-mob");
            let svc = Arc::new(MockSessionSvc::new());
            let dir = tempfile::tempdir().expect("tempdir");
            let others = launch_of_an_earlier_process(
                LAUNCH,
                &svc,
                dir.path(),
                &[
                    "other-0", "other-1", "other-2", "other-3", "other-4", "other-5", "other-6",
                    "other-7",
                ],
            )
            .await;
            let svc = Arc::new(svc.cold_restart().await);
            let composition = RecordingComposition::new(&svc);
            let state = host_state(
                LAUNCH,
                &svc,
                dir.path(),
                &composition,
                MobRestorePolicy::OnDemand,
            );
            let launch = MobId::from(LAUNCH);

            let held = lookups(&state, &launch, 8);
            all_still_wait(
                &held,
                "a lookup of the default mob waits for the launch's serve",
            )
            .await;
            still_awaits_its_serve(LAUNCH, &state, &composition).await;
            let inventory = at_once(state.mob_inventory(), "the inventory")
                .await
                .expect("the inventory");
            assert!(
                inventory.dormant.contains(&launch) && inventory.quarantined.is_empty(),
                "the default mob is listed as known and not loaded while it awaits its serve"
            );
            assert!(
                at_once(state.mob_list(), "the list")
                    .await
                    .expect("the list")
                    .is_empty()
            );
            let stored = at_once(
                state.default_mob_stored_definition(),
                "the launch's read of its store",
            )
            .await
            .expect("the read answers")
            .expect("the store holds the default mob");
            assert_eq!(stored.definition().id, launch);
            all_still_wait(&held, "the launch's read releases nobody").await;
            // Each load of another mob changes the set: a held lookup waits
            // for the serve, not for a number of changes.
            for other in &others {
                state
                    .mob_status(other)
                    .await
                    .expect("another mob loads while the default mob awaits");
            }
            all_still_wait(&held, "other mobs loading do not end the wait").await;
            assert!(
                !composition
                    .composed()
                    .iter()
                    .any(|(mob_id, _, _)| mob_id == &launch),
                "the composition is not asked for the default mob before the serve"
            );

            let served = at_once(
                state.serve_default_mob(explicit_definition(LAUNCH)),
                "the launch's own serve",
            )
            .await
            .expect("the serve loads the default mob");
            assert!(!served.created);
            for lookup in held {
                assert_eq!(
                    answer_of(lookup)
                        .await
                        .expect("a held lookup is served after the serve"),
                    MobState::Running
                );
            }
            assert_eq!(
                composition
                    .composed()
                    .into_iter()
                    .filter(|(mob_id, _, _)| mob_id == &launch)
                    .collect::<Vec<_>>(),
                vec![(launch, HostMobBuildStage::Load, true)],
                "the default mob was built once, by the serve"
            );
            end_process(&state).await;
        }

        /// Two first serves that arrive together answer the same mob: the
        /// second waits for the first, not for a serve that never comes.
        #[tokio::test]
        async fn two_first_serves_answer_the_same_mob() {
            const LAUNCH: &str = row_id!("launch-mob");
            let svc = Arc::new(MockSessionSvc::new());
            let dir = tempfile::tempdir().expect("tempdir");
            launch_of_an_earlier_process(LAUNCH, &svc, dir.path(), &[]).await;
            let svc = Arc::new(svc.cold_restart().await);
            let composition = RecordingComposition::new(&svc);
            let state = host_state(
                LAUNCH,
                &svc,
                dir.path(),
                &composition,
                MobRestorePolicy::Eager,
            );
            let serves = (0..2)
                .map(|_| {
                    let state = Arc::clone(&state);
                    tokio::spawn(async move {
                        state
                            .serve_default_mob(explicit_definition(LAUNCH))
                            .await
                            .map(|served| served.created)
                    })
                })
                .collect::<Vec<_>>();
            for serve in serves {
                assert!(
                    !answer_of(serve).await.expect("each serve answers the mob"),
                    "the store held the mob for both"
                );
            }
            assert_eq!(composition.composed().len(), 1, "the mob was built once");
            end_process(&state).await;
        }

        /// A stand-down releases the lookups held for the launch's serve
        /// with the stood-down error, and does not wait for them until its
        /// deadline.
        #[tokio::test]
        async fn a_stand_down_releases_the_lookups_held_for_the_launchs_serve() {
            const LAUNCH: &str = row_id!("launch-mob");
            let svc = Arc::new(MockSessionSvc::new());
            let dir = tempfile::tempdir().expect("tempdir");
            launch_of_an_earlier_process(LAUNCH, &svc, dir.path(), &[]).await;
            let svc = Arc::new(svc.cold_restart().await);
            let composition = RecordingComposition::new(&svc);
            let state = host_state(
                LAUNCH,
                &svc,
                dir.path(),
                &composition,
                MobRestorePolicy::Eager,
            );
            let launch = MobId::from(LAUNCH);
            let held = lookups(&state, &launch, 3);
            all_still_wait(
                &held,
                "a lookup of the default mob waits for the launch's serve",
            )
            .await;
            still_awaits_its_serve(LAUNCH, &state, &composition).await;

            let stood_down = tokio::time::timeout(
                Duration::from_secs(30),
                state.stand_down(std::time::Instant::now() + Duration::from_mins(10)),
            )
            .await
            .expect("the stand-down does not wait for the held lookups until its deadline");
            assert!(stood_down.is_clean(), "{stood_down:?}");
            for lookup in held {
                let answer = answer_of(lookup).await;
                assert!(
                    matches!(&answer, Err(MobError::Internal(reason)) if reason.contains("stood down")),
                    "a held lookup answers the stood-down error: {answer:?}"
                );
            }
            assert!(
                composition.composed().is_empty(),
                "nothing was built for a state that stood down"
            );
        }

        /// A first serve that fails releases the held lookups too: they
        /// answer the store's typed quarantine, not a wait without end.
        #[tokio::test]
        async fn a_failed_first_serve_releases_the_held_lookups_with_the_quarantine() {
            const LAUNCH: &str = row_id!("launch-mob");
            let svc = Arc::new(MockSessionSvc::new());
            let dir = tempfile::tempdir().expect("tempdir");
            launch_of_an_earlier_process(LAUNCH, &svc, dir.path(), &[]).await;
            let svc = Arc::new(svc.cold_restart().await);
            let composition = RecordingComposition::new(&svc);
            composition.refuse(true);
            let state = host_state(
                LAUNCH,
                &svc,
                dir.path(),
                &composition,
                MobRestorePolicy::Eager,
            );
            let launch = MobId::from(LAUNCH);
            let held = lookups(&state, &launch, 4);
            all_still_wait(
                &held,
                "a lookup of the default mob waits for the launch's serve",
            )
            .await;
            still_awaits_its_serve(LAUNCH, &state, &composition).await;

            let refused = state
                .serve_default_mob(explicit_definition(LAUNCH))
                .await
                .map(|_| ())
                .expect_err("the composition refuses the load")
                .error;
            assert_eq!(
                quarantine_data(&refused)["kind"],
                MOB_QUARANTINED_KIND,
                "{refused:?}"
            );
            for lookup in held {
                let answer = answer_of(lookup)
                    .await
                    .expect_err("the default mob is not served");
                assert_eq!(
                    quarantine_data(&answer)["kind"],
                    MOB_QUARANTINED_KIND,
                    "a held lookup answers the quarantine the serve met: {answer:?}"
                );
            }
        }

        /// A serve refused on its own arguments touched nothing and
        /// releases nobody: the default mob still awaits its serve, and the
        /// next serve releases the waiters.
        #[tokio::test]
        async fn a_serve_refused_on_its_arguments_releases_nobody() {
            const LAUNCH: &str = row_id!("launch-mob");
            let svc = Arc::new(MockSessionSvc::new());
            let dir = tempfile::tempdir().expect("tempdir");
            launch_of_an_earlier_process(LAUNCH, &svc, dir.path(), &[]).await;
            let svc = Arc::new(svc.cold_restart().await);
            let composition = RecordingComposition::new(&svc);
            let state = host_state(
                LAUNCH,
                &svc,
                dir.path(),
                &composition,
                MobRestorePolicy::Eager,
            );
            let launch = MobId::from(LAUNCH);
            let held = lookups(&state, &launch, 2);
            all_still_wait(
                &held,
                "a lookup of the default mob waits for the launch's serve",
            )
            .await;
            still_awaits_its_serve(LAUNCH, &state, &composition).await;

            assert!(matches!(
                state
                    .serve_default_mob(explicit_definition("another-mob"))
                    .await,
                Err(DefaultMobServeError {
                    error: MobError::WiringError(_),
                    declared_update: None,
                })
            ));
            all_still_wait(&held, "a serve refused on its arguments releases nobody").await;
            let stale = state
                .serve_default_mob(
                    DefaultMobServe::new(explicit_definition(LAUNCH)).declaring_update(7),
                )
                .await;
            assert!(
                matches!(
                    &stale,
                    Err(DefaultMobServeError {
                        declared_update: None,
                        ..
                    })
                ),
                "a declaration the store does not admit refuses the serve, with nothing committed: {stale:?}"
            );
            all_still_wait(
                &held,
                "a serve whose declared update is refused releases nobody",
            )
            .await;
            state
                .serve_default_mob(explicit_definition(LAUNCH))
                .await
                .expect("the next serve loads the default mob");
            for lookup in held {
                answer_of(lookup)
                    .await
                    .expect("the serve released the held lookup");
            }
            end_process(&state).await;
        }

        /// A refusal under the default mob's id is a refusal at once, also
        /// while the mob awaits its serve: a create, a foreign handle and a
        /// destroy do not wait, and none of them touches the store.
        #[tokio::test]
        async fn a_refusal_under_the_default_mobs_id_does_not_wait_for_the_serve() {
            const LAUNCH: &str = row_id!("launch-mob");
            let svc = Arc::new(MockSessionSvc::new());
            let dir = tempfile::tempdir().expect("tempdir");
            launch_of_an_earlier_process(LAUNCH, &svc, dir.path(), &[]).await;
            let svc = Arc::new(svc.cold_restart().await);
            let composition = RecordingComposition::new(&svc);
            let state = host_state(
                LAUNCH,
                &svc,
                dir.path(),
                &composition,
                MobRestorePolicy::Eager,
            );
            let launch = MobId::from(LAUNCH);

            let create = at_once(
                state.mob_create_definition(explicit_definition(LAUNCH)),
                "a create under the default mob's id",
            )
            .await;
            assert!(create.is_err(), "{create:?}");
            let foreign = MobBuilder::new(explicit_definition(LAUNCH), MobStorage::in_memory())
                .with_session_service(svc.clone())
                .allow_ephemeral_sessions(true)
                .create()
                .await
                .expect("a mob built outside the set");
            let insert = at_once(
                state.try_mob_insert_handle(launch.clone(), foreign.clone()),
                "a foreign handle under the default mob's id",
            )
            .await;
            assert!(
                matches!(&insert, Err(MobError::MobAlreadyExists(mob_id)) if mob_id.as_str() == LAUNCH),
                "{insert:?}"
            );
            foreign
                .shutdown()
                .await
                .expect("end the mob built outside the set");
            let destroy = at_once(state.mob_destroy(&launch), "a destroy of the default mob").await;
            assert!(
                matches!(
                    &destroy,
                    Err(MobMcpDestroyError::Mob(MobError::WiringError(_)))
                ),
                "the default mob is not destroyed through the set: {destroy:?}"
            );
            // An agent's tool is refused at once too: it does not resolve
            // the mob first, which would wait for the launch's serve.
            let operator = OperatorSession::new(&state);
            let tool = at_once(
                operator.call("mob_destroy", json!({ "mob_id": LAUNCH })),
                "an agent's destroy of the default mob",
            )
            .await;
            assert!(
                tool.is_err(),
                "an agent's tool does not destroy the default mob"
            );
            assert_eq!(
                state.mob_inventory().await.expect("the inventory").dormant,
                vec![launch],
                "the default mob still awaits its serve"
            );
            assert!(composition.composed().is_empty(), "and nothing was built");
        }

        /// The set refuses a destroy of the default mob at every door: the
        /// mob still serves and its store file is still there.
        #[tokio::test]
        async fn the_default_mob_is_not_destroyed_through_the_set() {
            const LAUNCH: &str = row_id!("launch-mob");
            const HOST_SECOND: &str = row_id!("host-second");
            let svc = Arc::new(MockSessionSvc::new());
            let dir = tempfile::tempdir().expect("tempdir");
            let composition = RecordingComposition::new(&svc);
            let state = host_state(
                LAUNCH,
                &svc,
                dir.path(),
                &composition,
                MobRestorePolicy::Eager,
            );
            let launch = MobId::from(LAUNCH);
            state
                .serve_default_mob(explicit_definition(LAUNCH))
                .await
                .expect("the set creates the default mob");

            let destroy = state.mob_destroy(&launch).await;
            assert!(
                matches!(
                    &destroy,
                    Err(MobMcpDestroyError::Mob(MobError::WiringError(_)))
                ),
                "a destroy of the default mob is refused: {destroy:?}"
            );
            let lifecycle = state
                .mob_lifecycle_action(&launch, WireMobLifecycleAction::Destroy)
                .await;
            assert!(
                matches!(
                    &lifecycle,
                    Err(MobMcpDestroyError::Mob(MobError::WiringError(_)))
                ),
                "and so is the lifecycle verb's destroy: {lifecycle:?}"
            );
            // The door the set's own cleanups use (a session's mobs, the
            // scavenge) meets the same refusal.
            let unchecked = state.mob_destroy_unchecked(&launch).await;
            assert!(
                matches!(
                    &unchecked,
                    Err(MobMcpDestroyError::Mob(MobError::WiringError(_)))
                ),
                "and the unchecked destroy: {unchecked:?}"
            );
            assert_eq!(
                state
                    .mob_status(&launch)
                    .await
                    .expect("the mob still serves"),
                MobState::Running
            );
            assert!(
                launch_store(dir.path()).exists(),
                "its store is still there"
            );
            // Another host mob is destroyed as before.
            let second = state
                .mob_create_definition(explicit_definition(HOST_SECOND))
                .await
                .expect("create a second host mob");
            state
                .mob_destroy(&second)
                .await
                .expect("a host mob that is not the default mob is destroyed");
            end_process(&state).await;
        }

        /// A completion owed to a member of the default mob, asked for
        /// before the launch's serve, waits for the serve and then finds
        /// the member: the mob is never read as gone while it awaits.
        #[tokio::test]
        async fn a_completion_owed_to_a_default_mob_member_waits_for_the_serve() {
            const LAUNCH: &str = row_id!("launch-mob");
            use meerkat::ContinuationAddressResolver as _;
            let svc = Arc::new(MockSessionSvc::new());
            let dir = tempfile::tempdir().expect("tempdir");
            let launch = MobId::from(LAUNCH);
            {
                let composition = RecordingComposition::new(&svc);
                let first = host_state(
                    LAUNCH,
                    &svc,
                    dir.path(),
                    &composition,
                    MobRestorePolicy::Eager,
                );
                first
                    .serve_default_mob(explicit_definition(LAUNCH))
                    .await
                    .expect("the first launch creates the default mob");
                spawn_worker(&first, &launch).await;
                end_process(&first).await;
            }
            let svc = Arc::new(svc.cold_restart().await);
            let composition = RecordingComposition::new(&svc);
            let state = host_state(
                LAUNCH,
                &svc,
                dir.path(),
                &composition,
                MobRestorePolicy::Eager,
            );
            state
                .mob_inventory()
                .await
                .expect("the first verb takes the census");
            assert!(
                !state.mob_is_retired(&launch).await,
                "a default mob that awaits its serve is not gone"
            );
            let owed = {
                let state = Arc::clone(&state);
                let launch = launch.clone();
                tokio::spawn(async move {
                    super::lazy_hosted_set::host_resolver(&state)
                        .current_address(&super::lazy_hosted_set::worker_owner(&launch))
                        .await
                })
            };
            all_still_wait(
                std::slice::from_ref(&owed),
                "a completion owed to a member of the default mob waits for the serve",
            )
            .await;
            still_awaits_its_serve(LAUNCH, &state, &composition).await;
            state
                .serve_default_mob(explicit_definition(LAUNCH))
                .await
                .expect("the serve loads the default mob");
            let address = answer_of(owed).await;
            assert!(
                matches!(address, Ok(Some(_))),
                "the member is found once its mob is served: {address:?}"
            );
            end_process(&state).await;
        }

        /// A completion owed to a member of the default mob stays owed when
