        /// The read is the console owner's: a mob that is not loaded has no
        /// machine running that could answer for a grant. A state bound to
        /// any other principal is refused with the typed scope denial, and
        /// nothing is opened or loaded for the refusal.
        #[tokio::test]
        async fn the_events_of_a_mob_that_is_not_loaded_are_the_console_owners_to_read() {
            let svc = Arc::new(MockSessionSvc::new());
            let root = tempfile::tempdir().expect("tempdir");
            let mobs = mobs_of_an_earlier_process(&svc, root.path(), &["journal-owner-only"]).await;
            let viewer = MobMcpState::new(
                svc.clone(),
                meerkat_mob::MobControlPrincipal::External(
                    meerkat_core::auth::PrincipalId::new("journal-viewer").expect("principal"),
                ),
            )
            .expect("runtime custody")
            .with_persistent_storage_root(Some(root.path().to_path_buf()))
            .with_mob_restore_policy(MobRestorePolicy::OnDemand);

            let denied = viewer.mob_events_without_load(&mobs[0], 0, 10).await;
            assert!(
                matches!(
                    &denied,
                    Err(MobError::ScopeDenied(denial))
                        if denial.required == ControlScope::SubscribeEvents
                ),
                "{denied:?}"
            );
            assert_eq!(
                viewer.store_opens_for_test(),
                0,
                "no store is opened for the refusal"
            );
            assert!(
                !viewer.hosted.read().await.is_loaded(&mobs[0]),
                "the mob is not loaded for the refusal"
            );
        }

        /// One door: a managed mob answers through its own handle, and once
        /// the idle unload has unloaded it the same read answers from its
        /// store and leaves the mob not loaded.
        #[tokio::test]
        async fn the_events_of_a_mob_are_read_before_and_after_its_idle_unload() {
            let svc = Arc::new(MockSessionSvc::new());
            let root = tempfile::tempdir().expect("tempdir");
            let lazy = lazy_state(&svc, root.path());
            let mob_id = lazy
                .mob_create_definition(explicit_definition("journal-unloaded-later"))
                .await
                .expect("create the mob");

            let managed = lazy
                .mob_events_without_load(&mob_id, 0, 10_000)
                .await
                .expect("read a managed mob's events");
            let polled = lazy
                .mob_events(&mob_id, 0, 10_000)
                .await
                .expect("poll the managed mob");
            assert!(!polled.is_empty(), "a created mob has a journal");
            assert_eq!(
                events_json(managed.events()),
                events_json(&polled),
                "a managed mob answers what its own poll answers"
            );
            assert_eq!(
                managed.latest_cursor(),
                lazy.mob_latest_event_cursor(&mob_id)
                    .await
                    .expect("the managed mob's latest cursor")
            );
            assert_eq!(
                managed.mob_id(),
                Some(&mob_id),
                "a page a managed mob answers names it"
            );

            assert_eq!(
                lazy.unload_idle_mobs().await,
                vec![mob_id.clone()],
                "the idle mob unloads"
            );
            let opens = lazy.store_opens_for_test();
            let stored = lazy
                .mob_events_without_load(&mob_id, 0, 10_000)
                .await
                .expect("read the unloaded mob's events");
            assert_eq!(
                inventory(&lazy).await.dormant,
                vec![mob_id.clone()],
                "the mob is still not loaded"
            );
            assert_eq!(
                lazy.store_opens_for_test(),
                opens,
                "no store was opened for writing"
            );
            assert!(
                stored.events().len() >= polled.len(),
                "the store holds at least what the mob answered while it ran"
            );
            assert_eq!(
                events_json(&stored.events()[..polled.len()]),
                events_json(&polled),
                "the journal read from the store starts with what the mob answered while it ran"
            );
            assert_eq!(
                Some(stored.latest_cursor()),
                stored.events().last().map(|event| event.cursor),
                "the latest cursor is the last event's"
            );
        }

        /// A store that cannot be read answers the read's own typed refusal
        /// and is judged by nothing here: the read quarantines no store.
        /// Once a request has quarantined it, the read answers that
        /// quarantine, as every lookup does, and re-attempts nothing.
        #[tokio::test]
        async fn an_unreadable_store_refuses_the_event_read_and_is_not_quarantined_by_it() {
            let svc = Arc::new(MockSessionSvc::new());
            let root = tempfile::tempdir().expect("tempdir");
            let broken = MobId::from("journal-broken");
            let mob_root = MobMcpState::persistent_mob_root(root.path());
            std::fs::create_dir_all(&mob_root).expect("the mob root");
            let broken_store = MobMcpState::persistent_storage_path(&mob_root, &broken);
            std::fs::write(&broken_store, b"not a sqlite database")
                .expect("write an undecodable mob store");
            let lazy = lazy_state(&svc, root.path());

            let refused = lazy
                .mob_events_without_load(&broken, 0, 10)
                .await
                .expect_err("a file that is not a mob store has no events to read");
            match &refused {
                MobError::StorageError(source) => assert!(
                    matches!(
                        source.downcast_ref::<meerkat_mob::MobStoredEventsReadError>(),
                        Some(meerkat_mob::MobStoredEventsReadError::ForeignSchema { .. })
                    ),
                    "the answer is the read's own refusal: {source:?}"
                ),
                other => panic!("expected the read's refusal, got {other:?}"),
            }
            let listed = inventory(&lazy).await;
            assert_eq!(
                listed.dormant,
                vec![broken.clone()],
                "the read judged nothing"
            );
            assert!(listed.quarantined.is_empty(), "{:?}", listed.quarantined);
            assert_eq!(lazy.store_opens_for_test(), 0);

            let lookup = lazy
                .mob_status(&broken)
                .await
                .expect_err("the unreadable store has no mob to serve");
            assert_eq!(quarantine_data(&lookup)["kind"], MOB_QUARANTINED_KIND);
            let opens = lazy.store_opens_for_test();
            let quarantined = lazy
                .mob_events_without_load(&broken, 0, 10)
                .await
                .expect_err("a quarantined store has no events to read");
            assert_eq!(
                quarantine_data(&quarantined)["kind"],
                MOB_QUARANTINED_KIND,
                "{quarantined:?}"
            );
            assert_eq!(
                lazy.store_opens_for_test(),
                opens,
                "the read re-attempts nothing"
            );
            assert!(broken_store.exists(), "the store is kept as found");
        }

        /// A store under one id that holds another mob's journal is no store
        /// of that id: the read answers not found, as the read of a stored
        /// definition does, and judges nothing.
        #[tokio::test]
        async fn a_store_that_holds_another_mob_has_no_events_under_its_id() {
            let svc = Arc::new(MockSessionSvc::new());
            let root = tempfile::tempdir().expect("tempdir");
            let mobs = mobs_of_an_earlier_process(&svc, root.path(), &["journal-original"]).await;
            let original = stored_journal(root.path(), &mobs[0]).await;
            assert!(!original.events().is_empty(), "the original has a journal");
            let copy = MobId::from("journal-copy");
            copy_store_under(root.path(), &mobs[0], &copy);
            let copied = stored_journal(root.path(), &copy).await;
            assert_eq!(
                events_json(copied.events()),
                events_json(original.events()),
                "the copy holds the original's journal"
            );
            let lazy = lazy_state(&svc, root.path());

            let refused = lazy.mob_events_without_load(&copy, 0, 10).await;
            assert!(
                matches!(&refused, Err(MobError::MobNotFound(id)) if id == &copy),
                "{refused:?}"
            );
            let listed = inventory(&lazy).await;
            assert_eq!(
                sorted(listed.dormant),
                sorted(vec![mobs[0].clone(), copy.clone()]),
                "neither store was loaded or judged"
            );
            assert!(listed.quarantined.is_empty(), "{:?}", listed.quarantined);
            assert_eq!(lazy.store_opens_for_test(), 0);
        }

        /// A copy of the store of `original` under the id `copy`, made before
        /// any state reads the root: a store whose journal names another
        /// mob than the id its file is listed under.
        fn copy_store_under(root: &std::path::Path, original: &MobId, copy: &MobId) {
            let sidecar = |path: &std::path::Path, suffix: &str| {
                let mut value = path.as_os_str().to_os_string();
                value.push(suffix);
                PathBuf::from(value)
            };
            for suffix in ["", "-wal"] {
                let from = sidecar(&stored_mob_path(root, original), suffix);
                if from.exists() {
                    std::fs::copy(&from, sidecar(&stored_mob_path(root, copy), suffix))
                        .expect("copy the store");
                }
            }
        }

        /// A store that holds another mob is no store of its id whatever
        /// the page asked for holds: a page past the journal's end and a
        /// page of limit zero are not found either, and tell nothing of the
        /// other mob's journal.
        #[tokio::test]
        async fn an_empty_page_of_a_store_that_holds_another_mob_is_not_found() {
            let svc = Arc::new(MockSessionSvc::new());
            let root = tempfile::tempdir().expect("tempdir");
            let mobs =
                mobs_of_an_earlier_process(&svc, root.path(), &["journal-original-page"]).await;
            let original = stored_journal(root.path(), &mobs[0]).await;
            let copy = MobId::from("journal-copy-page");
            copy_store_under(root.path(), &mobs[0], &copy);
            let lazy = lazy_state(&svc, root.path());

            for (after_cursor, limit, what) in [
                (original.latest_cursor(), 10, "a page past the end"),
                (0, 0, "a page of limit zero"),
            ] {
                let refused = lazy
                    .mob_events_without_load(&copy, after_cursor, limit)
                    .await;
                assert!(
                    matches!(&refused, Err(MobError::MobNotFound(id)) if id == &copy),
                    "{what} of a store that holds another mob is not found: {refused:?}"
                );
            }
            let own = lazy
                .mob_events_without_load(&mobs[0], original.latest_cursor(), 10)
                .await
                .expect("the original's own page past the end");
            assert!(own.events().is_empty());
            assert_eq!(own.latest_cursor(), original.latest_cursor());
            assert_eq!(lazy.store_opens_for_test(), 0);
        }

