        /// A mob whose idle unload is in flight is read from its store: the
        /// read does not wait for the unload and does not hand out the mob.
        #[tokio::test]
        async fn the_events_of_a_mob_whose_unload_is_in_flight_are_read_from_its_store() {
            let svc = Arc::new(MockSessionSvc::new());
            let root = tempfile::tempdir().expect("tempdir");
            let lazy = lazy_state(&svc, root.path());
            let mob_id = lazy
                .mob_create_definition(explicit_definition("journal-unloading"))
                .await
                .expect("create the mob");
            let polled = lazy
                .mob_events(&mob_id, 0, 10_000)
                .await
                .expect("poll the managed mob");
            assert!(!polled.is_empty(), "a created mob has a journal");

            let question = hold_at(&lazy, "unload question");
            let pass = unload_pass(&lazy);
            wait_until_reached(&question).await;
            let page = tokio::time::timeout(
                Duration::from_secs(10),
                lazy.mob_events_without_load(&mob_id, 0, 10_000),
            )
            .await
            .expect("the read does not wait for the unload")
            .expect("read the mob whose unload is in flight");
            question.release.notify_one();

            assert!(page.events().len() >= polled.len());
            assert_eq!(
                events_json(&page.events()[..polled.len()]),
                events_json(&polled),
                "the page starts with what the mob answered while it was managed"
            );
            assert_eq!(
                pass.await.expect("the unload pass"),
                vec![mob_id.clone()],
                "the unload ends as it would have"
            );
            assert_eq!(inventory(&lazy).await.dormant, vec![mob_id]);
        }

        /// A mob whose one load is in flight is read from its store: the
        /// read does not wait for the load, and the load ends as it would
        /// have.
        #[tokio::test]
        async fn the_events_of_a_mob_whose_load_is_in_flight_are_read_from_its_store() {
            let svc = Arc::new(MockSessionSvc::new());
            let root = tempfile::tempdir().expect("tempdir");
            let mobs = mobs_of_an_earlier_process(&svc, root.path(), &["journal-loading"]).await;
            let stored = stored_journal(root.path(), &mobs[0]).await;
            let lazy = lazy_state(&svc, root.path());
            let activation = Arc::new(InsertHold::default());
            let parked = Arc::clone(&activation);
            let hook: meerkat_mob::MobBeforeActivation = Arc::new(move |_handle| {
                let parked = Arc::clone(&parked);
                Box::pin(async move {
                    parked
                        .reached
                        .store(true, std::sync::atomic::Ordering::SeqCst);
                    parked.release.notified().await;
                    Ok(())
                })
            });
            lazy.set_before_activation(hook)
                .expect("bind the activation hook");

            let load = {
                let lazy = Arc::clone(&lazy);
                let mob_id = mobs[0].clone();
                tokio::spawn(async move { lazy.mob_status(&mob_id).await })
            };
            wait_until_reached(&activation).await;
            let page = tokio::time::timeout(
                Duration::from_secs(10),
                lazy.mob_events_without_load(&mobs[0], 0, 10_000),
            )
            .await
            .expect("the read does not wait for the load")
            .expect("read the mob whose load is in flight");
            let loaded_meanwhile = lazy.hosted.read().await.is_loaded(&mobs[0]);
            activation.release.notify_one();

            assert!(!loaded_meanwhile, "the mob was not served yet");
            assert!(page.events().len() >= stored.events().len());
            assert_eq!(
                events_json(&page.events()[..stored.events().len()]),
                events_json(stored.events()),
                "the page starts with the journal the store held before the load"
            );
            load.await
                .expect("the load task")
                .expect("the load ends as it would have");
            assert_eq!(managed_ids(&inventory(&lazy).await), mobs);
        }

        /// A child mob held before activation is read from its store: its
        /// journal, the seated worker's spawn among it, with the hold left
