        /// The worker every mob of the stop rows seats.
        fn the_worker() -> AgentIdentity {
            AgentIdentity::from("worker-1")
        }

        /// Seat [`the_worker`] in the mob `mob_id` of `state`.
        async fn seat_the_worker(state: &MobMcpState, mob_id: &MobId) {
            state
                .mob_spawn(
                    mob_id,
                    ProfileName::from("worker"),
                    the_worker(),
                    Some(MobRuntimeMode::TurnDriven),
                    None,
                    None,
                )
                .await
                .expect("spawn worker");
        }

        /// Create the mobs `ids` under `root` in an earlier process, each
        /// with [`the_worker`] seated, stop the ones `stopped` names, and
        /// end the process.
        async fn mobs_of_an_earlier_process_some_stopped(
            svc: &Arc<MockSessionSvc>,
            root: &std::path::Path,
            ids: &[&str],
            stopped: &[&str],
        ) -> Vec<MobId> {
            let state = restored_state(svc, root);
            let mut created = Vec::new();
            for id in ids {
                let mob_id = state
                    .mob_create_definition(explicit_definition(id))
                    .await
                    .expect("create a mob of the earlier process");
                seat_the_worker(&state, &mob_id).await;
                if stopped.contains(id) {
                    state.mob_stop(&mob_id).await.expect("stop the mob");
                }
                created.push(mob_id);
            }
            for mob_id in &created {
                state
                    .handle_for(mob_id)
                    .await
                    .expect("predecessor mob handle")
                    .shutdown()
                    .await
                    .expect("retire the predecessor supervisor route");
            }
            created
        }

        /// What a send to [`the_worker`] of the mob `mob_id` is answered:
        /// that it was delivered, or its refusal's own words.
        async fn a_send(state: &MobMcpState, mob_id: &MobId) -> String {
            match state
                .mob_member_send(
                    mob_id,
                    the_worker(),
                    ContentInput::from("work for the mob"),
                    HandlingMode::Queue,
                    None,
                )
                .await
            {
                Ok(_) => "delivered".to_string(),
                Err(error) => format!("refused: {error}"),
            }
        }

        /// Whether `answer` is the refusal a stopped mob gives work.
        fn is_the_stopped_mobs_refusal(answer: &Result<MobHandle, MobError>) -> bool {
            matches!(
                answer,
                Err(MobError::InvalidTransition {
                    from: MobState::Stopped,
                    to: MobState::Running,
                })
            )
        }

        /// A mob that was stopped before the idle unload closed it is
        /// listed as stopped while it is not loaded, and a mob that was not
        /// stopped is listed as dormant only. No store is opened for it:
        /// the mob itself said it when its actor closed.
        #[tokio::test]
        async fn a_mob_stopped_before_its_unload_is_listed_as_stopped_while_it_is_not_loaded() {
            let svc = Arc::new(MockSessionSvc::new());
            let root = tempfile::tempdir().expect("tempdir");
            let lazy = lazy_state(&svc, root.path());
            let stopped = lazy
                .mob_create_definition(explicit_definition("stopped-then-unloaded"))
                .await
                .expect("create the mob that is stopped");
            let running = lazy
                .mob_create_definition(explicit_definition("running-then-unloaded"))
                .await
                .expect("create the mob that runs");
            lazy.mob_stop(&stopped).await.expect("stop the mob");
            let both = sorted(vec![stopped.clone(), running.clone()]);

            assert_eq!(
                sorted(lazy.unload_idle_mobs().await),
                both,
                "both idle mobs unload, the stopped one too"
            );
            let opens = lazy.store_opens_for_test();
            let listed = inventory(&lazy).await;
            assert_eq!(sorted(listed.dormant.clone()), both);
            assert_eq!(
                listed.dormant_stopped,
                vec![stopped.clone()],
                "only the stopped mob lists as stopped"
            );
            assert_eq!(
                lazy.store_opens_for_test(),
                opens,
                "no store was opened for the listing"
            );
        }

        /// A mob stopped in an earlier process is listed as stopped once
        /// this state read its store: in the sweep over the dormant mobs,
        /// which opens each store once anyway, or in the read of who
        /// created one mob. Before any read it is listed as dormant only,
        /// and no listing opens a store.
        #[tokio::test]
        async fn a_mob_stopped_in_an_earlier_process_is_listed_as_stopped_once_its_store_was_read()
        {
            let svc = Arc::new(MockSessionSvc::new());
            let root = tempfile::tempdir().expect("tempdir");
            let mobs = sorted(
                mobs_of_an_earlier_process_some_stopped(
                    &svc,
                    root.path(),
                    &["stopped-and-swept", "running-and-swept"],
                    &["stopped-and-swept"],
                )
                .await,
            );
            let lazy = lazy_state(&svc, root.path());
            let before = inventory(&lazy).await;
            assert_eq!(sorted(before.dormant.clone()), mobs);
            assert!(
                before.dormant_stopped.is_empty(),
                "nothing is read before the sweep: {:?}",
                before.dormant_stopped
            );
            assert_eq!(lazy.store_opens_for_test(), 0);

            let torn_down = lazy.sweep_dormant_mobs().await;
            assert!(torn_down.is_empty(), "{torn_down:?}");
            let opens = lazy.store_opens_for_test();
            assert_eq!(opens, mobs.len(), "the sweep opens each dormant store once");
            let swept = inventory(&lazy).await;
            assert_eq!(sorted(swept.dormant.clone()), mobs, "the mobs stay dormant");
            assert_eq!(
                swept.dormant_stopped,
                vec![MobId::from("stopped-and-swept")],
                "the sweep's one open read the stop"
            );
            assert_eq!(
                lazy.store_opens_for_test(),
                opens,
                "a listing opens no store"
            );

            // The read of who created one mob: one open, the stop with it.
            let other_root = tempfile::tempdir().expect("tempdir");
            mobs_of_an_earlier_process_some_stopped(
                &svc,
                other_root.path(),
                &["stopped-and-asked"],
                &["stopped-and-asked"],
            )
            .await;
            let asked_of = lazy_state(&svc, other_root.path());
            let asked = MobId::from("stopped-and-asked");
            assert!(inventory(&asked_of).await.dormant_stopped.is_empty());
            assert_eq!(
                asked_of
                    .unloaded_mob_creation(&asked)
                    .await
                    .expect("the read of one store's creation record"),
                Some(meerkat_mob::MobProvenance::Host)
            );
            assert_eq!(asked_of.store_opens_for_test(), 1);
            let listed = inventory(&asked_of).await;
            assert_eq!(listed.dormant, vec![asked.clone()], "the mob stays dormant");
            assert_eq!(
                listed.dormant_stopped,
                vec![asked.clone()],
                "the read's one open read the stop"
            );
        }

        /// Work for a mob that is stopped and not loaded is refused as the
        /// loaded stopped mob refuses it, and nothing is loaded for it: the
        /// mob stays dormant and no store is opened. A read of the mob
        /// loads it, stopped as it was; a resume starts it, and work is
        /// then admitted.
        #[tokio::test]
        async fn work_for_a_stopped_mob_that_is_not_loaded_is_refused_as_by_the_loaded_mob() {
            let svc = Arc::new(MockSessionSvc::new());
            let root = tempfile::tempdir().expect("tempdir");
            let lazy = lazy_state(&svc, root.path());
            let mob_id = lazy
                .mob_create_definition(explicit_definition("stopped-not-loaded"))
                .await
                .expect("create the mob");
            seat_the_worker(&lazy, &mob_id).await;
            lazy.mob_stop(&mob_id).await.expect("stop the mob");

            let by_the_loaded_mob = a_send(&lazy, &mob_id).await;
            assert_eq!(
                by_the_loaded_mob,
                format!(
                    "refused: {}",
                    MobError::InvalidTransition {
                        from: MobState::Stopped,
                        to: MobState::Running,
                    }
                ),
                "the loaded stopped mob refuses a send as a transition from Stopped to Running"
            );
            assert!(
                lazy.handle_for_work(&mob_id).await.is_ok(),
                "a loaded mob answers for itself: the lookup for work hands it out"
            );

            assert_eq!(
                lazy.unload_idle_mobs().await,
                vec![mob_id.clone()],
                "the idle stopped mob unloads"
            );
            let opens = lazy.store_opens_for_test();
            assert_eq!(
                a_send(&lazy, &mob_id).await,
                by_the_loaded_mob,
                "the send is answered as the loaded stopped mob answers it"
            );
            assert!(
                is_the_stopped_mobs_refusal(&lazy.handle_for_work(&mob_id).await),
                "the lookup for work answers the stopped mob's refusal"
            );
            let listed = inventory(&lazy).await;
            assert_eq!(listed.dormant, vec![mob_id.clone()], "nothing was loaded");
            assert_eq!(listed.dormant_stopped, vec![mob_id.clone()]);
            assert!(listed.managed.is_empty(), "{:?}", listed.managed);
            assert_eq!(
                lazy.store_opens_for_test(),
                opens,
                "and no store was opened for the refusals"
            );

            assert_eq!(
                lazy.mob_status(&mob_id)
                    .await
                    .expect("a read loads the mob"),
                MobState::Stopped,
                "the mob is loaded stopped, as it was"
            );
            assert_eq!(managed_ids(&inventory(&lazy).await), vec![mob_id.clone()]);
            lazy.mob_resume(&mob_id).await.expect("a resume starts it");
            assert!(
                lazy.handle_for_work(&mob_id).await.is_ok(),
                "work is admitted to the resumed mob"
            );
            assert_ne!(
                a_send(&lazy, &mob_id).await,
                by_the_loaded_mob,
                "and a send is no longer refused as to a stopped mob"
            );
        }

        /// What a call of the mob set is answered: that it was admitted, or
        /// its refusal's own words.
        fn told<T>(answer: Result<T, MobError>) -> String {
            match answer {
                Ok(_) => "admitted".to_string(),
                Err(error) => format!("refused: {error}"),
            }
        }

        /// What the calls of the mob set that a stopped mob refuses as work
        /// are answered for the mob `mob_id`, by a name for the call: a send
        /// to a member and a flow run, each with and without an external
        /// delivery identity.
        async fn refused_work_answers(
            state: &MobMcpState,
            mob_id: &MobId,
        ) -> BTreeMap<&'static str, String> {
            let content = || ContentInput::from("work for the mob");
            // The correlation id of a delivery is a canonical UUID.
            let delivery = |key: &str| {
                meerkat_mob::MobExternalDeliveryIdentity::new(
                    key,
                    "5f0c2f6e-9a53-4c1b-8a55-2b7f3d6e9c41",
                )
                .expect("an external delivery identity")
            };
            let mut answers = BTreeMap::new();
            answers.insert(
                "a send",
                told(
                    state
                        .mob_member_send(mob_id, the_worker(), content(), HandlingMode::Queue, None)
                        .await,
                ),
            );
            answers.insert(
                "a send with a delivery identity",
                told(
                    state
                        .mob_member_send_with_external_identity(
                            mob_id,
                            the_worker(),
                            content(),
                            HandlingMode::Queue,
                            None,
                            delivery("stop-rows-send"),
                        )
                        .await,
                ),
            );
            answers.insert(
                "a flow run",
                told(
                    state
                        .mob_run_flow_with_stream(
                            mob_id,
                            FlowId::from("no-such-flow"),
                            json!({}),
                            None,
                        )
                        .await,
                ),
            );
            answers.insert(
                "a flow run with a delivery identity",
                told(
                    state
                        .mob_run_flow_with_external_identity(
                            mob_id,
                            FlowId::from("no-such-flow"),
                            json!({}),
                            &delivery("stop-rows-flow"),
                        )
                        .await,
                ),
            );
            answers
        }

        /// What the other calls that address a member's work are answered
        /// for the mob `mob_id`, by a name for the call: the ones a loaded
        /// stopped mob does not refuse as work (it keeps a keyed send's key
        /// or says why it cannot, resolves a turn's target, and answers an
        /// ingress interaction in its own words).
        async fn other_work_answers(
            state: &MobMcpState,
            mob_id: &MobId,
        ) -> BTreeMap<&'static str, String> {
            let content = || ContentInput::from("work for the mob");
            let mut answers = BTreeMap::new();
            answers.insert(
                "a keyed send",
                told(
                    state
                        .mob_member_send_keyed(
                            mob_id,
                            the_worker(),
                            content(),
                            HandlingMode::Queue,
                            "stop-rows-external",
                        )
                        .await,
                ),
            );
            answers.insert(
                "a keyed send as the host",
                told(
                    state
                        .mob_member_send_keyed_as_host(
                            mob_id,
                            the_worker(),
                            content(),
                            HandlingMode::Queue,
                            "stop-rows-host",
                        )
                        .await,
                ),
            );
            answers.insert(
                "an ingress interaction",
                told(
                    state
                        .mob_ingress_interaction(
                            mob_id,
                            SpawnMemberSpec::new("worker", "worker-1"),
                            content(),
                            HandlingMode::Queue,
                            None,
                        )
                        .await,
                ),
            );
            answers.insert(
                "a turn start",
                told(state.mob_turn_start_target(mob_id, &the_worker()).await),
            );
            answers
        }

        /// Each call of the mob set that originates work answers a stopped
        /// mob the same whether the mob is loaded or not. The calls the
        /// loaded stopped mob refuses as work (a send and a flow run, with
        /// and without an external delivery identity) are refused the same
        /// while it is not loaded, and none of them loads it. The calls the
        /// loaded stopped mob answers in another way load it, and it
        /// answers them itself, stopped as it was.
        #[tokio::test]
        async fn each_call_that_originates_work_answers_a_stopped_mob_the_same_loaded_or_not() {
            let svc = Arc::new(MockSessionSvc::new());
            let root = tempfile::tempdir().expect("tempdir");
            let lazy = lazy_state(&svc, root.path());
            let mob_id = lazy
                .mob_create_definition(explicit_definition("stopped-every-call"))
                .await
                .expect("create the mob");
            seat_the_worker(&lazy, &mob_id).await;
            lazy.mob_stop(&mob_id).await.expect("stop the mob");

            let refused_by_the_loaded_mob = refused_work_answers(&lazy, &mob_id).await;
            let the_stopped_mobs_refusal = format!(
                "refused: {}",
                MobError::InvalidTransition {
                    from: MobState::Stopped,
                    to: MobState::Running,
                }
            );
            assert!(
                refused_by_the_loaded_mob
                    .values()
                    .all(|answer| answer == &the_stopped_mobs_refusal),
                "the loaded stopped mob refuses each as a transition from Stopped to Running: \
                 {refused_by_the_loaded_mob:#?}"
            );
            let others_by_the_loaded_mob = other_work_answers(&lazy, &mob_id).await;
            assert_eq!(
                lazy.unload_idle_mobs().await,
                vec![mob_id.clone()],
                "the stopped mob unloads after the calls it answered: \
                 {others_by_the_loaded_mob:#?}"
            );

            let opens = lazy.store_opens_for_test();
            assert_eq!(
                refused_work_answers(&lazy, &mob_id).await,
                refused_by_the_loaded_mob,
                "each is refused as the loaded stopped mob refuses it"
            );
            let listed = inventory(&lazy).await;
            assert_eq!(
                listed.dormant,
                vec![mob_id.clone()],
                "no refused call loaded the mob"
            );
            assert!(listed.managed.is_empty(), "{:?}", listed.managed);
            assert_eq!(
                lazy.store_opens_for_test(),
                opens,
                "and no store was opened for them"
            );

            assert_eq!(
                other_work_answers(&lazy, &mob_id).await,
                others_by_the_loaded_mob,
                "the other calls are answered by the mob itself, loaded for them"
            );
            assert_eq!(managed_ids(&inventory(&lazy).await), vec![mob_id.clone()]);
            assert_eq!(
                lazy.mob_status(&mob_id).await.expect("the mob's status"),
                MobState::Stopped,
                "the mob is still stopped"
            );
        }

        /// A state whose console principal is not the owner gives no refusal
        /// without a load: whether that principal may give the mob work is
        /// the mob's own grants' to say, and only the loaded mob reads
        /// them. Its send to a member of a stopped mob that is not loaded
        /// loads the mob, which answers the principal itself (here the
        /// scope it lacks), and the mob stays stopped. The owner's state,
        /// over the same stores, is refused the stopped mob's refusal and
        /// loads nothing.
        #[tokio::test]
        async fn work_by_a_principal_that_is_not_the_owner_loads_the_stopped_mob_to_answer_it() {
            let svc = Arc::new(MockSessionSvc::new());
            let root = tempfile::tempdir().expect("tempdir");
            mobs_of_an_earlier_process_some_stopped(
                &svc,
                root.path(),
                &["stopped-for-a-guest"],
                &["stopped-for-a-guest"],
            )
            .await;
            let mob_id = MobId::from("stopped-for-a-guest");

            let owner = lazy_state(&svc, root.path());
            assert!(
                is_the_stopped_mobs_refusal(&owner.handle_for_work(&mob_id).await),
                "the owner's call for work is refused without a load"
            );
            assert_eq!(inventory(&owner).await.dormant, vec![mob_id.clone()]);
            drop(owner);

            let guest = Arc::new(
                MobMcpState::new(
                    svc.clone(),
                    MobControlPrincipal::External(
                        meerkat_core::auth::PrincipalId::new("stop-rows-guest").expect("principal"),
                    ),
                )
                .expect("runtime custody")
                .with_persistent_storage_root(Some(root.path().to_path_buf()))
                .with_mob_restore_policy(MobRestorePolicy::OnDemand),
            );
            let activated = count_activations(&guest);
            let answer = a_send(&guest, &mob_id).await;
            assert!(
                answer.starts_with("refused: ") && !answer.contains("Stopped -> Running"),
                "the loaded mob answers the principal itself, by its grants: {answer}"
            );
            assert_eq!(
                *activated
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner),
                vec![mob_id.clone()],
                "the send loaded the mob, once"
            );
            let loaded = guest
                .handle_for(&mob_id)
                .await
                .expect("the mob the send loaded");
            assert_eq!(
                loaded.status_observation_snapshot(),
                MobState::Stopped,
                "and the mob is still stopped"
            );
        }

        /// What the agent tool `mob_list` answers a session, by mob id: the
        /// status it names for each mob.
        async fn listed_to(
            state: &Arc<MobMcpState>,
            session: &SessionId,
        ) -> BTreeMap<String, String> {
            listed_with(
                state,
                session,
                meerkat_runtime::mob_operator_authority::create_only_mob_operator_authority()
                    .expect("generated create-only mob authority"),
            )
            .await
        }

        /// What the agent tool `mob_list` answers a session whose mob tools
        /// hold `authority`, by mob id: the status it names for each mob.
        async fn listed_with(
            state: &Arc<MobMcpState>,
            session: &SessionId,
            authority: meerkat_core::service::MobToolAuthorityContext,
        ) -> BTreeMap<String, String> {
            let surface = destroy_surface(state, session.clone(), authority);
            let args = serde_json::value::RawValue::from_string("{}".to_string())
                .expect("empty arguments");
            let answer = surface
                .dispatch(ToolCallView {
                    id: "list-1",
                    name: "mob_list",
                    args: &args,
                })
                .await
                .expect("mob_list");
            let parsed: serde_json::Value =
                serde_json::from_str(&answer.result.text_content()).expect("the list is JSON");
            parsed["mobs"]
                .as_array()
                .expect("mobs")
                .iter()
                .map(|mob| {
                    (
                        mob["mob_id"].as_str().expect("mob_id").to_string(),
                        mob["status"].as_str().expect("status").to_string(),
                    )
                })
                .collect()
        }

        /// The mob a session creates with the agent tool `mob_create`.
        async fn created_by_the_tool(
            state: &Arc<MobMcpState>,
            session: &SessionId,
            id: &str,
        ) -> MobId {
            let surface = destroy_surface(
                state,
                session.clone(),
                meerkat_runtime::mob_operator_authority::create_only_mob_operator_authority()
                    .expect("generated create-only mob authority"),
            );
            let args = serde_json::value::RawValue::from_string(
                json!({
                    "definition": {
                        "id": id,
                        "profiles": {
                            "worker": {
                                "model": "claude-sonnet-4-5",
                                "tools": { "comms": true },
                                "peer_description": "worker",
                                "runtime_mode": "turn_driven"
                            }
                        }
                    }
                })
                .to_string(),
            )
            .expect("create arguments");
            let created = surface
                .dispatch(ToolCallView {
                    id: "create-1",
                    name: "mob_create",
                    args: &args,
                })
                .await
                .expect("a create-only authority allows mob_create");
            let created: serde_json::Value =
                serde_json::from_str(&created.result.text_content()).expect("the answer is JSON");
            MobId::from(created["mob_id"].as_str().expect("mob_id"))
        }

        /// The agent tool `mob_list` names the mobs the caller's own session
        /// created with its own create that the set knows and has not
        /// loaded: `Dormant`, or `Stopped` for one that was stopped before
        /// it was unloaded. It loads nothing and opens no store for them.
        /// Another session is told of none of them. A mob the host created,
        /// for no session or for the caller's (a create that grants the
        /// session nothing, so the list leaves the mob out while it is
        /// loaded), is not listed to the caller while it is not loaded
        /// either.
        #[tokio::test]
        async fn the_agents_mob_list_names_its_own_mobs_that_are_not_loaded() {
            let svc = Arc::new(MockSessionSvc::new());
            let root = tempfile::tempdir().expect("tempdir");
            let lazy = lazy_state(&svc, root.path());
            let creator = SessionId::new();
            let asleep = created_by_the_tool(&lazy, &creator, "listed-while-dormant").await;
            let stopped = created_by_the_tool(&lazy, &creator, "listed-while-stopped").await;
            let of_the_host = lazy
                .mob_create_definition(explicit_definition("the-hosts-own"))
                .await
                .expect("create a mob of the host");
            let made_for_it = lazy
                .mob_create_definition_with_owner_bridge_session(
                    explicit_definition("made-for-the-session"),
                    creator.clone(),
                    false,
                    false,
                )
                .await
                .expect("the host creates a mob for the session");
            assert_eq!(
                listed_to(&lazy, &creator).await,
                BTreeMap::from([
                    (asleep.to_string(), "Running".to_string()),
                    (stopped.to_string(), "Running".to_string()),
                ]),
                "the creator lists the two mobs it created while they are loaded"
            );
            lazy.mob_stop(&stopped).await.expect("stop the mob");
            assert_eq!(
                sorted(lazy.unload_idle_mobs().await),
                sorted(vec![
                    asleep.clone(),
                    stopped.clone(),
                    of_the_host.clone(),
                    made_for_it.clone(),
                ]),
                "the four idle mobs unload"
            );
            assert!(
                matches!(
                    inventory(&lazy).await.dormant_creation.get(&made_for_it),
                    Some(meerkat_mob::MobProvenance::Session { session_id }) if *session_id == creator
                ),
                "the record of the mob the host made names the session, and no create of its own"
            );

            let opens = lazy.store_opens_for_test();
            assert_eq!(
                listed_to(&lazy, &creator).await,
                BTreeMap::from([
                    (asleep.to_string(), "Dormant".to_string()),
                    (stopped.to_string(), "Stopped".to_string()),
                ]),
                "the creator is told of its own mobs that are not loaded, and of no other"
            );
            assert!(
                listed_to(&lazy, &SessionId::new()).await.is_empty(),
                "another session is told of none of them"
            );
            let listed = inventory(&lazy).await;
            assert!(
                listed.managed.is_empty(),
                "the list loaded nothing: {:?}",
                listed.managed
            );
            assert_eq!(lazy.store_opens_for_test(), opens, "and opened no store");
        }

        /// The agent tool `mob_list` names a mob the caller's mob tools hold
        /// a manage grant over, loaded or not: the grant is bound to the
        /// mob's incarnation, and the set's record keeps the incarnation of
        /// a mob it created or loaded once the mob is unloaded. So a session
        /// is still told of a mob it manages (its delegation mob, for one)
        /// while that mob sleeps, as `Dormant`, and nothing is loaded or
        /// opened for the answer. A grant over an earlier mob of the same
        /// id lists nothing, loaded or not: the mob under the id now is
        /// another mob.
        #[tokio::test]
        async fn the_agents_mob_list_names_a_mob_it_manages_that_is_not_loaded() {
            let svc = Arc::new(MockSessionSvc::new());
            let root = tempfile::tempdir().expect("tempdir");
            let lazy = lazy_state(&svc, root.path());
            let session = SessionId::new();
            let managed = lazy
                .mob_create_definition(explicit_definition("managed-while-dormant"))
                .await
                .expect("create the mob the session manages");
            let replaced = lazy
                .mob_create_definition(explicit_definition("created-again"))
                .await
                .expect("create the mob that is created again");
            let earlier = managing_authority(
                &replaced,
                lazy.handle_for(&replaced)
                    .await
                    .expect("the first mob under the id")
                    .live_incarnation(),
            );
            lazy.mob_destroy(&replaced)
                .await
                .expect("destroy the first mob under the id");
            assert_eq!(
                lazy.mob_create_definition(explicit_definition("created-again"))
                    .await
                    .expect("create a mob under the id again"),
                replaced
            );
            let granted = managing_authority(
                &managed,
                lazy.handle_for(&managed)
                    .await
                    .expect("the managed mob")
                    .live_incarnation(),
            );
            let only_managed =
                |status: &str| BTreeMap::from([(managed.to_string(), status.to_string())]);
            assert_eq!(
                listed_with(&lazy, &session, granted.clone()).await,
                only_managed("Running"),
                "the session lists the mob it manages while it is loaded"
            );
            assert!(
                listed_with(&lazy, &session, earlier.clone())
                    .await
                    .is_empty(),
                "a grant over the earlier mob of an id lists nothing while the later one is loaded"
            );
            assert_eq!(
                sorted(lazy.unload_idle_mobs().await),
                sorted(vec![managed.clone(), replaced.clone()]),
                "the two idle mobs unload"
            );

            let opens = lazy.store_opens_for_test();
            assert_eq!(
                listed_with(&lazy, &session, granted).await,
                only_managed("Dormant"),
                "the session is told of the mob it manages while it is not loaded"
            );
            assert!(
                listed_with(&lazy, &session, earlier).await.is_empty(),
                "a grant over the earlier mob of an id lists nothing while the later one is not \
                 loaded"
            );
            assert!(
                listed_to(&lazy, &session).await.is_empty(),
                "a session without the grant is told of neither"
            );
            let listed = inventory(&lazy).await;
            assert!(
                listed.managed.is_empty(),
                "the list loaded nothing: {:?}",
                listed.managed
            );
            assert_eq!(lazy.store_opens_for_test(), opens, "and opened no store");
        }

        /// The first work for a mob that is not loaded, in a process that
        /// has not read its store, reads that one store once: a stopped mob
        /// is refused as above and stays dormant, the record keeps the
        /// answer (a second call opens nothing), and a mob that is not
        /// stopped is loaded and served.
        #[tokio::test]
        async fn the_first_work_for_a_mob_of_an_earlier_process_reads_whether_it_is_stopped() {
            let svc = Arc::new(MockSessionSvc::new());
            let root = tempfile::tempdir().expect("tempdir");
            mobs_of_an_earlier_process_some_stopped(
                &svc,
                root.path(),
                &["stopped-earlier", "running-earlier"],
                &["stopped-earlier"],
            )
            .await;
            let lazy = lazy_state(&svc, root.path());
            let stopped = MobId::from("stopped-earlier");
            let running = MobId::from("running-earlier");
            assert_eq!(lazy.store_opens_for_test(), 0);

            assert!(
                is_the_stopped_mobs_refusal(&lazy.handle_for_work(&stopped).await),
                "work for the stopped mob is refused"
            );
            assert_eq!(
                lazy.store_opens_for_test(),
                1,
                "the one store was read once, and nothing else"
            );
            assert!(
                a_send(&lazy, &stopped).await.starts_with("refused: "),
                "a send is refused too"
            );
            assert_eq!(
                lazy.store_opens_for_test(),
                1,
                "the record kept the answer: no second open"
            );
            let listed = inventory(&lazy).await;
            assert_eq!(
                sorted(listed.dormant.clone()),
                sorted(vec![stopped.clone(), running.clone()]),
                "both mobs are dormant still"
            );
            assert_eq!(listed.dormant_stopped, vec![stopped.clone()]);

            assert!(
                lazy.handle_for_work(&running).await.is_ok(),
                "work for the mob that is not stopped loads it"
            );
            let listed = inventory(&lazy).await;
            assert_eq!(managed_ids(&listed), vec![running.clone()]);
            assert_eq!(listed.dormant, vec![stopped.clone()]);
        }

        /// Park the next idle observation of a managed mob right after its
        /// actor answered, before the set is read again.
        fn park_next_idle_observation(state: &MobMcpState) -> Arc<InsertHold> {
            let hold = Arc::new(InsertHold::default());
            *state
                .idle_observation_hold
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(Arc::clone(&hold));
            hold
        }

        /// What one idle observation of `mob_id` answers.
        async fn idle_observed(state: &MobMcpState, mob_id: &MobId) -> HostedMobIdle {
            state
                .mob_idle_observation(mob_id)
                .await
                .expect("the idle observation")
        }

        /// An idle observation reads the set's record and loads nothing: a
        /// mob that is not loaded, a quarantined store, a held child and an
        /// id no record names each have their own answer, none of them
        /// idle, and only a mob that is served is answered by its actor.
        /// Before the set is complete an id it does not know yet is not
        /// answered as absent, and no census is started to find out.
        #[tokio::test]
        async fn an_idle_observation_loads_nothing_and_tells_the_sets_records_apart() {
            let svc = Arc::new(MockSessionSvc::new());
            let root = tempfile::tempdir().expect("tempdir");
            let (svc, held, owner, _worker_session) =
                seat_child_worker_then_exit(&svc, root.path(), "observed-held").await;
            svc.script_observation(
                &owner,
                Ok(meerkat_mob::LiveDurableSourceObservation::Absent),
            );
            let mobs = mobs_of_an_earlier_process(
                &svc,
                root.path(),
                &["observed-asleep", "observed-served"],
            )
            .await;
            let broken = MobId::from("observed-broken");
            let mob_root = MobMcpState::persistent_mob_root(root.path());
            std::fs::write(
                MobMcpState::persistent_storage_path(&mob_root, &broken),
                b"not a sqlite database",
            )
            .expect("write an undecodable mob store");
            let nowhere = MobId::from("observed-nowhere");
            let lazy = lazy_state(&svc, root.path());

            assert_eq!(
                idle_observed(&lazy, &mobs[0]).await,
                HostedMobIdle::SetIncomplete,
                "before the census a stored mob is not known, and is not answered as absent"
            );
            assert!(
                !lazy.mob_set_complete() && lazy.store_opens_for_test() == 0,
                "no census is started for an observation"
            );

            inventory(&lazy).await;
            drop(lazy.handle_for(&mobs[1]).await.expect("load one mob"));
            assert!(
                lazy.handle_for(&broken).await.is_err(),
                "the undecodable store is refused by its load"
            );
            assert_held_before_activation(lazy.handle_for(&held).await, "owner_absent");
            let opens = lazy.store_opens_for_test();

            assert_eq!(idle_observed(&lazy, &mobs[0]).await, HostedMobIdle::Dormant);
            assert_eq!(
                idle_observed(&lazy, &broken).await,
                HostedMobIdle::Quarantined
            );
            assert_eq!(idle_observed(&lazy, &held).await, HostedMobIdle::Held);
            assert_eq!(idle_observed(&lazy, &nowhere).await, HostedMobIdle::Absent);
            let served = idle_observed(&lazy, &mobs[1]).await;
            assert!(
                matches!(served, HostedMobIdle::Observed(_)),
                "a mob that is served is answered by its actor: {served:?}"
            );
            let listed = inventory(&lazy).await;
            assert_eq!(
                managed_ids(&listed),
                vec![mobs[1].clone()],
                "no observation loaded a mob"
            );
            assert!(
                listed.dormant.contains(&mobs[0]),
                "the mob that is not loaded is still not loaded"
            );
            assert_eq!(
                lazy.store_opens_for_test(),
                opens,
                "and no observation opened a store"
            );
        }

        /// The observation of a mob that is served is its actor's: a
        /// foreground owner lease reads busy, the mob reads idle once the
        /// lease is dropped, and no observation closed the mob's admission
        /// or kept it loaded: the idle unload takes it as before, and it
        /// then answers as a mob that is not loaded, which is not idle.
        #[tokio::test]
        async fn an_idle_observation_of_a_served_mob_is_its_actors_and_closes_nothing() {
            let svc = Arc::new(MockSessionSvc::new());
            let root = tempfile::tempdir().expect("tempdir");
            let mobs = mobs_of_an_earlier_process(&svc, root.path(), &["observed-busy"]).await;
            let lazy = lazy_state(&svc, root.path());
            let handle = lazy.handle_for(&mobs[0]).await.expect("load the mob");

            let lease = handle.acquire_owner().expect("an owner lease");
            match idle_observed(&lazy, &mobs[0]).await {
                HostedMobIdle::Observed(found) => {
                    assert_eq!(found.busy.foreground_owners, 1, "{found:?}");
                    assert!(!found.is_idle(), "{found:?}");
                }
                other => panic!("a served mob is answered by its actor, got {other:?}"),
            }
            drop(lease);
            let idle = tokio::time::timeout(Duration::from_mins(1), async {
                loop {
                    match idle_observed(&lazy, &mobs[0]).await {
                        HostedMobIdle::Observed(found) if found.is_idle() => break,
                        HostedMobIdle::Observed(_) => {
                            tokio::time::sleep(Duration::from_millis(10)).await;
                        }
                        other => panic!("a served mob is answered by its actor, got {other:?}"),
                    }
                }
            })
            .await;
            assert!(idle.is_ok(), "the mob reads idle once the lease is dropped");
            assert!(
                handle.admission_closed().borrow().is_none(),
                "no observation closed the mob's admission"
            );
            drop(handle);

            assert_eq!(
                lazy.unload_idle_mobs().await,
                mobs,
                "the idle unload takes the observed mob as before"
            );
            assert_eq!(
                idle_observed(&lazy, &mobs[0]).await,
                HostedMobIdle::Dormant,
                "a mob that is not loaded does not read idle"
            );
        }

        /// An observation is given only for the actor that still serves the
        /// mob. One whose actor answered and whose mob was then unloaded
        /// answers what the record says by then, never that actor's idle;
        /// and an observation that meets an admitted unload says so.
        #[tokio::test]
        async fn an_idle_observation_never_answers_for_an_actor_that_serves_the_mob_no_longer() {
            let svc = Arc::new(MockSessionSvc::new());
            let root = tempfile::tempdir().expect("tempdir");
            let mobs =
                mobs_of_an_earlier_process(&svc, root.path(), &["observed-then-unloaded"]).await;
            let lazy = lazy_state(&svc, root.path());
            lazy.mob_status(&mobs[0]).await.expect("load the mob");

            let hold = park_next_idle_observation(&lazy);
            let observing = {
                let lazy = Arc::clone(&lazy);
                let mob_id = mobs[0].clone();
                tokio::spawn(async move { lazy.mob_idle_observation(&mob_id).await })
            };
            reached(&hold).await;

            let unload_hold = park_next_unload(&lazy);
            let unloading = {
                let lazy = Arc::clone(&lazy);
                tokio::spawn(async move { lazy.unload_idle_mobs().await })
            };
            reached(&unload_hold).await;
            assert_eq!(
                idle_observed(&lazy, &mobs[0]).await,
                HostedMobIdle::Unloading,
                "an observation that meets an admitted unload says so"
            );
            unload_hold.release.notify_one();
            let unloaded = tokio::time::timeout(Duration::from_mins(1), unloading)
                .await
                .expect("the unload pass finishes")
                .expect("the unload task");
            assert_eq!(unloaded, mobs, "the idle mob is unloaded");

            hold.release.notify_one();
            let answer = tokio::time::timeout(Duration::from_mins(1), observing)
                .await
                .expect("the parked observation finishes")
                .expect("the observation task")
                .expect("the idle observation");
            assert_eq!(
                answer,
                HostedMobIdle::Dormant,
                "the actor that answered serves the mob no longer: the record answers"
            );
        }

        /// A mob whose one load is in flight answers so, and is not asked
        /// and not waited for. And an observation whose actor answered,
        /// and whose mob was then unloaded and loaded again, says that the
        /// mob changed: another actor serves the id by then, and neither
        /// the earlier actor's answer nor one the later actor never gave is
        /// handed out.
        #[tokio::test]
        async fn an_idle_observation_says_a_load_in_flight_and_a_mob_another_actor_serves() {
            let svc = Arc::new(MockSessionSvc::new());
            let root = tempfile::tempdir().expect("tempdir");
            let mobs =
                mobs_of_an_earlier_process(&svc, root.path(), &["observed-while-loading"]).await;
            let lazy = lazy_state(&svc, root.path());
            assert_eq!(inventory(&lazy).await.dormant, mobs);

            let resume_hold = Arc::new(InsertHold::default());
            park_resumes(&lazy, Some(&resume_hold));
            let loading = {
                let lazy = Arc::clone(&lazy);
                let mob_id = mobs[0].clone();
                tokio::spawn(async move { lazy.mob_status(&mob_id).await })
            };
            reached(&resume_hold).await;
            let while_loading =
                tokio::time::timeout(Duration::from_secs(10), lazy.mob_idle_observation(&mobs[0]))
                    .await
                    .expect("the observation does not wait for the load")
                    .expect("the idle observation");
            assert_eq!(while_loading, HostedMobIdle::Loading);
            park_resumes(&lazy, None);
            resume_hold.release.notify_one();
            tokio::time::timeout(Duration::from_mins(1), loading)
                .await
                .expect("the load finishes")
                .expect("the load task")
                .expect("the mob is loaded");

            let hold = park_next_idle_observation(&lazy);
            let observing = {
                let lazy = Arc::clone(&lazy);
                let mob_id = mobs[0].clone();
                tokio::spawn(async move { lazy.mob_idle_observation(&mob_id).await })
            };
            reached(&hold).await;
            assert_eq!(
                lazy.unload_idle_mobs().await,
                mobs,
                "the mob is unloaded while the answer waits"
            );
            lazy.mob_status(&mobs[0])
                .await
                .expect("and is loaded again: another actor serves it");
            hold.release.notify_one();
            let answer = tokio::time::timeout(Duration::from_mins(1), observing)
                .await
                .expect("the parked observation finishes")
                .expect("the observation task")
                .expect("the idle observation");
            assert_eq!(
                answer,
                HostedMobIdle::Changed,
                "the earlier actor's answer is not given for the mob another actor serves"
            );
        }

        /// An idle observation needs the console owner. Any other principal
        /// is refused with the typed scope denial before anything is read,
        /// the same for a mob the set stores and for an id nothing names,
        /// so the refusal tells nothing of the mob. A set that stood down
        /// refuses it as it refuses every read.
        #[tokio::test]
        async fn an_idle_observation_needs_the_console_owner_and_a_standing_set() {
            let svc = Arc::new(MockSessionSvc::new());
            let root = tempfile::tempdir().expect("tempdir");
            let mobs =
                mobs_of_an_earlier_process(&svc, root.path(), &["observed-by-a-viewer"]).await;
            let viewer = MobMcpState::new(
                svc.clone(),
                MobControlPrincipal::External(
                    meerkat_core::auth::PrincipalId::new("idle-observation-viewer")
                        .expect("principal"),
                ),
            )
            .expect("runtime custody")
            .with_persistent_storage_root(Some(root.path().to_path_buf()))
            .with_mob_restore_policy(MobRestorePolicy::OnDemand);
            for asked in [mobs[0].clone(), MobId::from("observed-by-nobody")] {
                let denied = viewer
                    .mob_idle_observation(&asked)
                    .await
                    .expect_err("only the console owner observes");
                assert!(
                    matches!(
                        &denied,
                        MobError::ScopeDenied(denial)
                            if denial.required == ControlScope::List
                                && denial.presented.is_empty()
                    ),
                    "{denied:?}"
                );
            }
            assert_eq!(
                viewer.store_opens_for_test(),
                0,
                "a refused observation read nothing"
            );

            let lazy = lazy_state(&svc, root.path());
            inventory(&lazy).await;
            lazy.stand_down(std::time::Instant::now() + Duration::from_secs(30))
                .await;
            let refused = lazy.mob_idle_observation(&mobs[0]).await;
            assert!(
                refused.is_err(),
                "a set that stood down observes nothing: {refused:?}"
            );
        }

        /// Move the store of `mob_id` under `root` to a file whose name
        /// encodes no mob id, before any state reads the root: the store
        /// then takes the id its own records name.
        fn file_store_under_no_id(root: &std::path::Path, mob_id: &MobId) {
            let with_suffix = |path: &std::path::Path, suffix: &str| {
                let mut value = path.as_os_str().to_os_string();
                value.push(suffix);
                PathBuf::from(value)
            };
            let unnamed = MobMcpState::persistent_mob_root(root)
                .join(format!("{}%zz.db", MobMcpState::MOB_STORE_FILE_PREFIX));
            for suffix in ["", "-wal"] {
                let from = with_suffix(&stored_mob_path(root, mob_id), suffix);
                if from.exists() {
                    std::fs::rename(&from, with_suffix(&unnamed, suffix)).expect("move the store");
                }
            }
        }

        /// The read of who created a mob that is not loaded takes a store
        /// only under the id its file's name encodes, as the restore and
        /// the sweep do: a file named for one mob whose records hold another
        /// answers nothing and the record keeps nothing of the other mob,
        /// so who created the one is never read from the other's records.
        /// The store stays listed: its load refuses it. A store under its
        /// own mob's name, and one whose file's name encodes no id and
        /// which therefore takes the id its records name, are read as
        /// before.
        #[tokio::test]
        async fn the_creation_read_takes_no_store_filed_under_another_mobs_id() {
            let svc = Arc::new(MockSessionSvc::new());
            let root = tempfile::tempdir().expect("tempdir");
            let mobs = mobs_of_an_earlier_process(
                &svc,
                root.path(),
                &["creation-original", "creation-unnamed"],
            )
            .await;
            let copy = MobId::from("creation-copy");
            copy_store_under(root.path(), &mobs[0], &copy);
            file_store_under_no_id(root.path(), &mobs[1]);
            let lazy = lazy_state(&svc, root.path());

            for (asked, what) in [
                (&mobs[0], "a store under its own mob's name"),
                (&mobs[1], "a store whose file's name encodes no id"),
            ] {
                let read = lazy
                    .unloaded_mob_creation(asked)
                    .await
                    .expect("the creation read");
                assert!(read.is_some(), "{what} tells who created its mob");
            }
            let read = lazy
                .unloaded_mob_creation(&copy)
                .await
                .expect("the creation read");
            assert!(
                read.is_none(),
                "a file named for one mob that holds another tells nothing: {read:?}"
            );
            let listed = inventory(&lazy).await;
            assert!(
                !listed.dormant_creation.contains_key(&copy)
                    && !listed.dormant_incarnation.contains_key(&copy),
                "and the record keeps nothing of the other mob"
            );
            assert!(
                listed.dormant.contains(&copy) && listed.quarantined.is_empty(),
                "the store stays listed, for its load to refuse: {:?}",
                listed.quarantined
            );
        }

        /// The read of whether a mob that is not loaded is stopped takes a
        /// store only under the id its file's name encodes: a file named
        /// for one mob whose records hold another, stopped, mob does not
        /// make the one a stopped mob. The record keeps nothing, the work
        /// goes on to the load, and the load refuses the store as the
        /// restore does. A stopped mob under its own name, and one whose
        /// file's name encodes no id, refuse work as stopped, as before.
        #[tokio::test]
        async fn the_stop_read_takes_no_store_filed_under_another_mobs_id() {
            let svc = Arc::new(MockSessionSvc::new());
            let root = tempfile::tempdir().expect("tempdir");
            let names = ["stop-original", "stop-unnamed"];
            let mobs =
                mobs_of_an_earlier_process_some_stopped(&svc, root.path(), &names, &names).await;
            let copy = MobId::from("stop-copy");
            copy_store_under(root.path(), &mobs[0], &copy);
            file_store_under_no_id(root.path(), &mobs[1]);
            let lazy = lazy_state(&svc, root.path());

            for (asked, what) in [
                (&mobs[0], "a stopped mob under its own name"),
                (&mobs[1], "a stopped mob whose file's name encodes no id"),
            ] {
                assert!(
                    is_the_stopped_mobs_refusal(&lazy.handle_for_work(asked).await),
                    "{what} refuses work as stopped"
                );
            }
            let answer = lazy.handle_for_work(&copy).await;
            assert!(
                !is_the_stopped_mobs_refusal(&answer),
                "the stop of the mob a file holds is not the stop of the mob it is named for"
            );
            assert!(
                matches!(
                    &answer,
                    Err(MobError::MobQuarantined {
                        class: meerkat_mob::MobQuarantineClass::ResumeRefused,
                        ..
                    })
                ),
                "the load refuses the store, as the restore does: {:?}",
                answer.as_ref().err()
            );
            let listed = inventory(&lazy).await;
            assert_eq!(
                sorted(listed.dormant_stopped.clone()),
                sorted(mobs.clone()),
                "the record keeps the stop of the two mobs under their own stores, and no other"
            );
        }

        /// A mob whose store is quarantined keeps who created it when this
        /// state read that before the store failed, and the read opens
        /// nothing for it; a store quarantined before anything of it was
        /// read answers that it is not known, and is not opened either.
        #[tokio::test]
        async fn who_created_a_quarantined_mob_is_answered_from_the_record_and_never_by_an_open() {
            let svc = Arc::new(MockSessionSvc::new());
            let root = tempfile::tempdir().expect("tempdir");
            let mobs = mobs_of_an_earlier_process(&svc, root.path(), &["read-then-broken"]).await;
            let never_read = MobId::from("broken-unread");
            let mob_root = MobMcpState::persistent_mob_root(root.path());
            std::fs::write(
                MobMcpState::persistent_storage_path(&mob_root, &never_read),
                b"not a sqlite database",
            )
            .expect("write an undecodable mob store");
            let lazy = lazy_state(&svc, root.path());

            assert_eq!(
                lazy.unloaded_mob_creation(&mobs[0])
                    .await
                    .expect("the read while the store is dormant"),
                Some(meerkat_mob::MobProvenance::Host)
            );
            std::fs::write(
                MobMcpState::persistent_storage_path(&mob_root, &mobs[0]),
                b"not a sqlite database",
            )
            .expect("damage the store that was read");
            for mob_id in [&mobs[0], &never_read] {
                let lookup = lazy
                    .mob_status(mob_id)
                    .await
                    .expect_err("the unreadable store has no mob to serve");
                assert_eq!(
                    quarantine_data(&lookup)["kind"],
                    MOB_QUARANTINED_KIND,
                    "{lookup:?}"
                );
            }
            let opens = lazy.store_opens_for_test();

            assert_eq!(
                lazy.unloaded_mob_creation(&mobs[0])
                    .await
                    .expect("the read of a quarantined mob that was read before"),
                Some(meerkat_mob::MobProvenance::Host),
                "the record keeps who created the mob across its quarantine"
            );
            assert_eq!(
                lazy.unloaded_mob_creation(&never_read)
                    .await
                    .expect("the read of a quarantined mob that was never read"),
                None
            );
            assert_eq!(
                lazy.store_opens_for_test(),
                opens,
                "neither read opened a quarantined store"
            );
        }

        /// A mob whose idle unload is admitted and not answered yet keeps
        /// who created it for the read: its record answers, the answer it
        /// gives once the mob is dormant, and the read opens no store,
        /// loads no mob and does not wait for the unload.
        #[tokio::test]
        async fn who_created_a_mob_whose_unload_is_admitted_is_answered_from_its_record() {
            let svc = Arc::new(MockSessionSvc::new());
            let root = tempfile::tempdir().expect("tempdir");
            let mobs = mobs_of_an_earlier_process(&svc, root.path(), &["unloading-creation"]).await;
            let lazy = lazy_state(&svc, root.path());
            lazy.mob_status(&mobs[0]).await.expect("load the mob");

            let unload_hold = park_next_unload(&lazy);
            let unloading = unload_pass(&lazy);
            reached(&unload_hold).await;
            assert!(
                lazy.hosted.read().await.unload_in_flight(&mobs[0]),
                "the mob's unload is admitted and not answered"
            );
            let opens = lazy.store_opens_for_test();

            let while_unloading = tokio::time::timeout(
                Duration::from_secs(10),
                lazy.unloaded_mob_creation(&mobs[0]),
            )
            .await
            .expect("the read does not wait for the unload")
            .expect("the read while the unload is open");
            assert_eq!(
                while_unloading,
                Some(meerkat_mob::MobProvenance::Host),
                "the record keeps who created the mob while its unload is open"
            );
            assert_eq!(
                lazy.store_opens_for_test(),
                opens,
                "the read opened no store"
            );
            assert!(
                lazy.hosted.read().await.unload_in_flight(&mobs[0]),
                "and the unload is still the one that was admitted: nothing was loaded"
            );
            unload_hold.release.notify_one();

            assert_eq!(finished(unloading, "the unload pass").await, mobs);
            assert_eq!(
                lazy.unloaded_mob_creation(&mobs[0])
                    .await
                    .expect("the read once the mob is dormant"),
                while_unloading,
                "the dormant mob's record answers the same"
            );
        }

        /// A create under the id of a dormant mob is refused from the
        /// records, without opening the dormant mob's store, and the dormant
        /// mob is untouched: it still loads.
        #[tokio::test]
        async fn a_create_with_the_id_of_a_dormant_mob_is_refused() {
            let svc = Arc::new(MockSessionSvc::new());
            let root = tempfile::tempdir().expect("tempdir");
            let mobs = mobs_of_an_earlier_process(&svc, root.path(), &["lazy-taken"]).await;
            let lazy = lazy_state(&svc, root.path());
            let activated = count_activations(&lazy);

            let refused = lazy
                .mob_create_definition(explicit_definition("lazy-taken"))
                .await
                .expect_err("the id is a dormant mob's");
            assert!(
                refused
                    .to_string()
                    .contains("mob already exists: lazy-taken"),
                "{refused:?}"
            );
            assert_eq!(
                refused.structured_data(),
                Some(serde_json::json!({
                    "kind": "mob_already_exists",
                    "mob_id": "lazy-taken",
                })),
                "the refusal is typed: its kind and the id"
            );
            assert_eq!(
                lazy.store_opens_for_test(),
                0,
                "the refusal read the records, not the store"
            );
            assert_eq!(
                inventory(&lazy).await.dormant,
                mobs,
                "the dormant mob is still dormant"
            );
            lazy.mob_status(&mobs[0])
                .await
                .expect("the dormant mob is intact and loads");
            assert_eq!(
                *activated
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner),
                mobs,
                "only the dormant mob's own store was ever activated"
            );
        }

        /// A create hook that records the ids it was asked for: the host's
        /// hook is where everything the host keeps under an id is released
        /// before a create, so an id it never saw had nothing released.
        fn record_create_hook_calls(state: &MobMcpState) -> Arc<std::sync::Mutex<Vec<MobId>>> {
            let asked = Arc::new(std::sync::Mutex::new(Vec::new()));
            let recorder = Arc::clone(&asked);
            let hook: MobBeforeCreate = Arc::new(move |request: MobCreateRequest| {
                recorder
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner)
                    .push(request.mob_id);
                Box::pin(async { Ok(()) })
            });
            state.set_before_create(hook).expect("bind the create hook");
            asked
        }

        /// What the create hook was asked, read once.
        fn create_hook_calls(asked: &Arc<std::sync::Mutex<Vec<MobId>>>) -> Vec<MobId> {
            asked
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .clone()
        }

        /// The bytes of the store of `mob_id` under `root` and of its
        /// sidecars, by file.
        fn store_bytes(root: &std::path::Path, mob_id: &MobId) -> Vec<(PathBuf, Vec<u8>)> {
            let path = MobMcpState::persistent_storage_path(
                &MobMcpState::persistent_mob_root(root),
                mob_id,
            );
            existing_storage_files(&path)
                .into_iter()
                .map(|file| {
                    let bytes = std::fs::read(&file).expect("read a store file");
                    (file, bytes)
                })
                .collect()
        }

        /// A mob store placed under the root while the host runs is not in
        /// the census, which a state takes once. A create under its id
        /// still meets it: the id is taken, as a stored mob's is; the host's
        /// create hook is not asked, so nothing the host keeps under the id
        /// is released; the store is left byte for byte; and the set knows
        /// the mob from then on and loads it when it is addressed.
        #[tokio::test]
        async fn a_create_under_the_id_of_a_store_placed_after_the_census_is_taken_and_asks_no_hook()
         {
            let svc = Arc::new(MockSessionSvc::new());
            // The store of a mob another host made, under another root.
            let elsewhere = tempfile::tempdir().expect("tempdir");
            let placed =
                mobs_of_an_earlier_process(&svc, elsewhere.path(), &["placed-later"]).await;
            let root = tempfile::tempdir().expect("tempdir");
            let lazy = lazy_state(&svc, root.path());
            let asked = record_create_hook_calls(&lazy);
            assert!(
                inventory(&lazy).await.dormant.is_empty(),
                "the census found no store under the root"
            );

            // The store arrives behind the running host, file by file.
            for (file, bytes) in store_bytes(elsewhere.path(), &placed[0]) {
                let name = file.file_name().expect("a store file has a name");
                let to = MobMcpState::persistent_mob_root(root.path()).join(name);
                std::fs::write(&to, bytes).expect("place a store file under the root");
            }
            let before = store_bytes(root.path(), &placed[0]);
            assert!(!before.is_empty(), "the store is under the root now");

            let refused = lazy
                .mob_create_definition(explicit_definition("placed-later"))
                .await
                .expect_err("the id is the placed store's");
            // The three facts are read before any is judged, so a failure
            // shows all of them.
            let hook_calls = create_hook_calls(&asked);
            let unchanged = store_bytes(root.path(), &placed[0]) == before;
            let taken = refused.structured_data()
                == Some(serde_json::json!({
                    "kind": "mob_already_exists",
                    "mob_id": "placed-later",
                }));
            assert!(
                taken && hook_calls.is_empty() && unchanged,
                "a create under the id of a store the census did not list is answered that \
                 the id is taken (answered: {refused}), the host's create hook is not asked, \
                 so nothing kept under the id is released (asked for: {hook_calls:?}), and \
                 the placed store is byte for byte as it was placed (unchanged: {unchanged})"
            );
            assert_eq!(
                inventory(&lazy).await.dormant,
                placed,
                "the set knows the mob from then on"
            );
            lazy.mob_status(&placed[0])
                .await
                .expect("the placed mob loads when it is addressed");
        }

        /// Under the eager policy the census loads every store it lists. A
        /// store placed under the root after it is met by a create under
        /// its id the same way: the id is taken, the host's create hook is
        /// not asked, and the store is loaded, as the restore pass would
        /// have loaded it.
        #[tokio::test]
        async fn a_create_under_the_id_of_a_store_placed_after_an_eager_restore_is_taken_and_loads_it()
         {
            let svc = Arc::new(MockSessionSvc::new());
            let elsewhere = tempfile::tempdir().expect("tempdir");
            let placed =
                mobs_of_an_earlier_process(&svc, elsewhere.path(), &["placed-eager"]).await;
            let root = tempfile::tempdir().expect("tempdir");
            let eager = restored_state(&svc, root.path());
            let asked = record_create_hook_calls(&eager);
            let at_start = inventory(&eager).await;
            assert!(
                at_start.managed.is_empty() && at_start.dormant.is_empty(),
                "the restore pass found no store under the root"
            );

            for (file, bytes) in store_bytes(elsewhere.path(), &placed[0]) {
                let name = file.file_name().expect("a store file has a name");
                let to = MobMcpState::persistent_mob_root(root.path()).join(name);
                std::fs::write(&to, bytes).expect("place a store file under the root");
            }

            let refused = eager
                .mob_create_definition(explicit_definition("placed-eager"))
                .await
                .expect_err("the id is the placed store's");
            let hook_calls = create_hook_calls(&asked);
            let after = inventory(&eager).await;
            let taken = refused.structured_data()
                == Some(serde_json::json!({
                    "kind": "mob_already_exists",
                    "mob_id": "placed-eager",
                }));
            assert!(
                taken
                    && hook_calls.is_empty()
                    && managed_ids(&after) == placed
                    && after.dormant.is_empty(),
                "a create under the id of a store an eager state did not list is answered \
                 that the id is taken (answered: {refused}), the host's create hook is not \
                 asked (asked for: {hook_calls:?}), and the store is loaded as the restore \
                 pass loads every store (managed: {:?}, dormant: {:?})",
                managed_ids(&after),
                after.dormant
            );
        }

        /// A create of this state that fails after it made its store, and
        /// before it wrote a creation, leaves a store that holds no mob
        /// (here: a definition without a profile, which the mob's own
        /// create refuses). The same id is free for the next create: the
        /// store a failed create left is no stored mob's, under the
        /// on-demand policy as under the eager one.
        async fn a_failed_create_leaves_its_id_free(policy: MobRestorePolicy, id: &str) {
            let svc = Arc::new(MockSessionSvc::new());
            let root = tempfile::tempdir().expect("tempdir");
            let state = Arc::new(
                MobMcpState::new(svc.clone(), meerkat_mob::MobControlPrincipal::Owner)
                    .expect("runtime custody")
                    .with_persistent_storage_root(Some(root.path().to_path_buf()))
                    .with_mob_restore_policy(policy),
            );
            let failed = state
                .mob_create_definition(MobDefinition::explicit(MobId::from(id)))
                .await
                .expect_err("a definition without a profile creates no mob");
            assert!(
                matches!(failed, MobError::DefinitionError(_)),
                "the mob's own create refuses the definition: {failed:?}"
            );
            assert_eq!(
                mob_store_files(root.path()),
                1,
                "the failed create left the store it made under the root"
            );

            let created = state
                .mob_create_definition(explicit_definition(id))
                .await
                .map_err(|error| error.to_string());
            assert_eq!(
                created,
                Ok(MobId::from(id)),
                "the id of a create that failed before it wrote a creation is free"
            );
            assert_eq!(
                managed_ids(&inventory(&state).await),
                vec![MobId::from(id)],
                "the mob the second create made is managed"
            );
        }

        #[tokio::test]
        async fn a_create_that_failed_after_its_store_was_made_leaves_its_id_free_on_demand() {
            a_failed_create_leaves_its_id_free(MobRestorePolicy::OnDemand, "retried-on-demand")
                .await;
        }

        #[tokio::test]
        async fn a_create_that_failed_after_its_store_was_made_leaves_its_id_free_eagerly() {
            a_failed_create_leaves_its_id_free(MobRestorePolicy::Eager, "retried-eagerly").await;
        }

        /// A store whose event log is empty while its creation record still
        /// names a mob is not a store that holds no mob: its log lost the
        /// creation the record names. Placed under the root after the
        /// census, it is listed by the look a create makes: the create
        /// under its id is answered that the id is taken, the host's create
        /// hook is not asked, and a lookup of the mob answers the
        /// quarantine its load gives such a store.
        #[tokio::test]
        async fn a_create_under_the_id_of_a_placed_store_whose_log_lost_its_creation_asks_no_hook()
        {
            let svc = Arc::new(MockSessionSvc::new());
            let elsewhere = tempfile::tempdir().expect("tempdir");
            let placed =
                mobs_of_an_earlier_process(&svc, elsewhere.path(), &["placed-lost-log"]).await;
            MobStorage::drop_event_log_for_test(&MobMcpState::persistent_storage_path(
                &MobMcpState::persistent_mob_root(elsewhere.path()),
                &placed[0],
            ))
            .expect("drop the log, not through the destroy's clear");
            let root = tempfile::tempdir().expect("tempdir");
            let lazy = lazy_state(&svc, root.path());
            let asked = record_create_hook_calls(&lazy);
            assert!(
                inventory(&lazy).await.dormant.is_empty(),
                "the census found no store under the root"
            );
            for (file, bytes) in store_bytes(elsewhere.path(), &placed[0]) {
                let name = file.file_name().expect("a store file has a name");
                let to = MobMcpState::persistent_mob_root(root.path()).join(name);
                std::fs::write(&to, bytes).expect("place a store file under the root");
            }

            let refused = lazy
                .mob_create_definition(explicit_definition("placed-lost-log"))
                .await
                .expect_err("the id is the placed store's");
            let hook_calls = create_hook_calls(&asked);
            let taken = refused.structured_data()
                == Some(serde_json::json!({
                    "kind": "mob_already_exists",
                    "mob_id": "placed-lost-log",
                }));
            assert!(
                taken && hook_calls.is_empty(),
                "a create under the id of a placed store whose log lost its creation is \
                 answered that the id is taken (answered: {refused}), and the host's create \
                 hook is not asked (asked for: {hook_calls:?})"
            );
            let lookup = lazy
                .mob_status(&placed[0])
                .await
                .expect_err("a store whose log lost its creation has no mob to serve");
            assert_eq!(
                quarantine_data(&lookup)["kind"],
                MOB_QUARANTINED_KIND,
                "its load quarantines it: {lookup:?}"
            );
        }

        /// A create under the id of a mob whose store is quarantined is
        /// answered the quarantine, and the host's create hook is not
        /// asked: the record holds the id.
        #[tokio::test]
        async fn a_create_under_the_id_of_a_quarantined_store_is_refused_and_asks_no_hook() {
            let svc = Arc::new(MockSessionSvc::new());
            let root = tempfile::tempdir().expect("tempdir");
            let mobs = mobs_of_an_earlier_process(&svc, root.path(), &["taken-quarantined"]).await;
            std::fs::write(
                MobMcpState::persistent_storage_path(
                    &MobMcpState::persistent_mob_root(root.path()),
                    &mobs[0],
                ),
                b"not a sqlite database",
            )
            .expect("damage the store");
            let lazy = lazy_state(&svc, root.path());
            let asked = record_create_hook_calls(&lazy);
            let lookup = lazy
                .mob_status(&mobs[0])
                .await
                .expect_err("the unreadable store has no mob to serve");
            assert_eq!(
                quarantine_data(&lookup)["kind"],
                MOB_QUARANTINED_KIND,
                "{lookup:?}"
            );

            let refused = lazy
                .mob_create_definition(explicit_definition("taken-quarantined"))
                .await
                .expect_err("the id is the quarantined store's");
            assert_eq!(
                quarantine_data(&refused)["kind"],
                MOB_QUARANTINED_KIND,
                "the create is answered the quarantine: {refused:?}"
            );
            assert_eq!(
                create_hook_calls(&asked),
                Vec::<MobId>::new(),
                "the host's create hook was not asked"
            );
        }

        /// A create under the id of a mob whose load is in flight is
        /// answered that the id is taken, at once, and the host's create
        /// hook is not asked.
        #[tokio::test]
        async fn a_create_under_the_id_of_a_store_that_is_being_loaded_is_taken_and_asks_no_hook() {
            let svc = Arc::new(MockSessionSvc::new());
            let root = tempfile::tempdir().expect("tempdir");
            let mobs = mobs_of_an_earlier_process(&svc, root.path(), &["taken-loading"]).await;
            let lazy = lazy_state(&svc, root.path());
            let asked = record_create_hook_calls(&lazy);
            assert_eq!(inventory(&lazy).await.dormant, mobs);

            let hold = Arc::new(InsertHold::default());
            park_resumes(&lazy, Some(&hold));
            let loading = {
                let lazy = Arc::clone(&lazy);
                let mob_id = mobs[0].clone();
                tokio::spawn(async move { lazy.mob_status(&mob_id).await })
            };
            reached(&hold).await;

            let refused = tokio::time::timeout(
                Duration::from_secs(10),
                lazy.mob_create_definition(explicit_definition("taken-loading")),
            )
            .await
            .expect("the create does not wait for the load")
            .expect_err("the id is the loading store's");
            assert_eq!(
                refused.structured_data(),
                Some(serde_json::json!({
                    "kind": "mob_already_exists",
                    "mob_id": "taken-loading",
                })),
                "{refused}"
            );
            assert_eq!(
                create_hook_calls(&asked),
                Vec::<MobId>::new(),
                "the host's create hook was not asked"
            );
            park_resumes(&lazy, None);
            hold.release.notify_one();
            finished(loading, "the load")
                .await
                .expect("the lookup that started the load is served");
        }

        /// A create under the id of a mob whose idle unload is admitted and
        /// not answered yet is answered that the id is taken, at once, and
